INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('45-degree-hyperextension-0489', '45 Degree Hyperextension', 'A lower back exercise on a 45-degree hyperextension bench that targets the spinal erectors and posterior chain.', 'Set up on a 45-degree hyperextension bench with hips supported and ankles secured. Cross arms over the chest or place hands behind the head. Hinge at the hips, lower your torso toward the floor, then contract lower back and glutes to return to start.', ARRAY['Position yourself on the 45-degree hyperextension bench with ankles secured.', 'Cross arms over chest or place hands behind head.', 'Lower your upper body forward at the hips.', 'Stop when your upper body is just below parallel to the floor.', 'Lift your torso back up in line with your legs.']::text[], 'Exhale as you rise, inhale as you lower.', ARRAY['Rounding the back', 'Overextending at the top', 'Using momentum']::text[], 'beginner'::difficulty_level, 'erector_spinae', ARRAY['glutes', 'hamstrings', 'lower_back']::text[], ARRAY['machine']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/45-degree-hyperextension.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/45-degree-hyperextension.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('45-degree-bicycle-twisting-crunch-drv-45-degree-bycicle-twisting-crunch', '45-Degree Bicycle Twisting Crunch', 'A twisting crunch performed at a 45-degree angle to target the obliques and rectus abdominis.', 'Lie flat on your back with hands behind your head and legs raised at a 45-degree angle. Bring your right elbow toward your left knee while extending the opposite leg, then alternate sides in a pedaling motion.', ARRAY['Lie down with your hands behind your head and legs extended upwards at about a 45-degree angle.', 'Engage your core and lift your shoulders off the ground.', 'Twist your upper body, bringing your right elbow toward your left knee as you extend your right leg.', 'Return to the starting position and repeat to the opposite side.', 'Continue alternating sides in a controlled, twisting motion.']::text[], 'Exhale during the twist, inhale as you return to center.', ARRAY['Pulling on the neck', 'Using momentum instead of abs', 'Allowing hips to sag']::text[], 'intermediate'::difficulty_level, 'obliques', ARRAY['rectus_abdominis', 'hip_flexors']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'abs'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/45-degree-bycicle-twisting-crunch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/45-degree-bycicle-twisting-crunch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('45-degree-bicycle-twisting-crunch-drv-45-degree-bycicle-twisting-crunch-1', '45-Degree Bicycle Twisting Crunch', 'A twisting ab exercise performed at a 45-degree angle to target the abdominals and obliques.', 'Lie flat on your back with knees bent and hands behind your head. Lift your shoulders and legs off the ground to a 45-degree angle and alternate bringing each knee in toward your chest while twisting the opposite elbow towards it, simulating a bicycle pedaling motion. Maintain controlled, twisting movement for each rep.', ARRAY['Lie on your back with hands behind your head and knees bent.', 'Lift your shoulders and feet off the ground, creating a 45-degree angle with your torso and legs.', 'Bring your right knee in while twisting your left elbow towards it.', 'Switch sides, extending the right leg and bringing the left knee in as your right elbow moves towards it.', 'Continue alternating sides in a smooth, controlled motion.']::text[], 'Exhale as you crunch and twist, inhale as you return to center.', ARRAY['Using momentum', 'Pulling on neck', 'Not twisting fully']::text[], 'beginner'::difficulty_level, 'abdominals', ARRAY['obliques', 'hip_flexors']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'abs'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/45-degree-bycicle-twisting-crunch-1.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/45-degree-bycicle-twisting-crunch-1.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('all-fours-groin-stretch-drv-stretching-all-fours-squad-stretch', 'All Fours Groin Stretch', 'A floor stretch on hands and knees targeting the adductors and groin area.', 'Begin on your hands and knees. Widen your knees apart as far as comfortable, keeping your feet in line with your knees. Sink your hips back slightly until a stretch is felt in the inner thighs and groin, holding with steady breathing.', ARRAY['Start on hands and knees (quadruped position).', 'Slide knees apart, keeping shins and feet in line with knees.', 'Lower hips toward the floor, maintaining a flat back.', 'Move hips back gently until you feel a stretch in the groin.', 'Hold the position and breathe deeply.']::text[], 'Breathe slowly and deeply throughout the stretch.', ARRAY['Arching lower back', 'Letting feet come together', 'Overstretching past comfort']::text[], 'beginner'::difficulty_level, 'adductors', ARRAY['glutes', 'hamstrings']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'mobility'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-all-fours-squad-stretch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-all-fours-squad-stretch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('band-assisted-pull-up-0970', 'Band Assisted Pull-up', 'A vertical pulling exercise using a resistance band for assistance to build pull-up strength in the lats, biceps, and upper back.', 'Attach the band to a pull-up bar or sturdy anchor point. Step onto the band and grip the bar with your palms facing away from you, hands slightly wider than shoulder-width apart. Hang with your arms fully extended, keeping your core engaged and your shoulders down and back. Pull your body up towards the bar by squeezing your shoulder blades together and driving your elbows down towards your hips. Continue pulling until your chin is above the bar, then slowly lower yourself back down to the starting position. Repeat for the desired number of repetitions.', ARRAY['Loop the band securely over a pull-up bar and place one foot or knee into the bottom of the band.', 'Grip the bar slightly wider than shoulder width with your palms facing away from you.', 'Hang with straight arms, tighten your midsection, and pull your shoulders down away from your ears.', 'Pull yourself up by driving your elbows down and back until your chin clears the bar.', 'Lower yourself with control until your arms are straight again, keeping tension through your torso.']::text[], 'Inhale at the bottom before you pull, exhale as you pull up, and inhale again as you lower under control.', ARRAY['Kicking or swinging to get up', 'Shrugging shoulders up toward the ears', 'Stopping short with the chin below the bar', 'Dropping quickly to the bottom without control']::text[], 'intermediate'::difficulty_level, 'lats', ARRAY['biceps', 'forearms']::text[], ARRAY['band']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-assisted-pull-up.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/band-assisted-pull-up.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('band-bent-over-rear-lateral-raise-drv-band-bent-over-rear-lateral-raise', 'Band Bent-Over Rear Lateral Raise', 'A rear shoulder and upper back exercise using a resistance band in a bent-over position.', 'Stand on a resistance band, hinge forward at the hips with a flat back. Grip the band ends and raise your arms laterally to shoulder level, keeping elbows slightly bent, then lower with control.', ARRAY['Stand on a resistance band, feet shoulder-width apart.', 'Hinge forward at hips, keeping back flat.', 'Hold band with both hands, arms hanging down.', 'Raise arms out to sides until parallel with shoulders.', 'Lower arms back down with control.']::text[], 'Exhale during the raise, inhale during the lowering.', ARRAY['Rounding back', 'Shrugging shoulders', 'Using momentum']::text[], 'beginner'::difficulty_level, 'posterior_deltoid', ARRAY['rhomboids', 'traps', 'infraspinatus']::text[], ARRAY['band']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'shoulders'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-bent-over-rear-lateral-raise.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/band-bent-over-rear-lateral-raise.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('band-hip-abduction-3006', 'Band Hip Abduction', 'A lateral leg movement with a resistance band to activate and strengthen the hip abductor muscles.', 'Place a resistance band around your lower thighs or ankles. Stand tall, shift your weight to one leg, and move the other leg out to the side against the band, then return under control. Repeat for both sides.', ARRAY['Place a resistance band around your thighs or ankles.', 'Stand tall with feet hip-width apart.', 'Shift weight to one leg.', 'Lift the other leg laterally against band resistance.', 'Return leg to start; repeat on both sides.']::text[], 'Exhale as you lift leg, inhale as you return.', ARRAY['Leaning torso', 'Poor balance', 'Letting band snap back']::text[], 'beginner'::difficulty_level, 'gluteus_medius', ARRAY['gluteus_minimus', 'tensor_fasciae_latae']::text[], ARRAY['band']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'glutes'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-hip-abduction.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/band-hip-abduction.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('band-hip-adduction-drv-band-hip-adduction', 'Band Hip Adduction', 'A resistance band exercise that strengthens the inner thigh muscles through hip adduction.', 'Attach a resistance band to a stable anchor and loop it around your ankle. Stand side-on to the anchor and bring your working leg across your body against the band’s resistance, focusing on squeezing your inner thigh.', ARRAY['Secure a resistance band to a sturdy anchor at ankle height.', 'Loop the other end around your working ankle.', 'Stand tall and hold onto a support if needed.', 'Bring your working leg across your body, adducting at the hip.', 'Slowly return to the starting position and repeat.']::text[], 'Exhale as you pull leg inward, inhale as you return.', ARRAY['Using momentum', 'Rotating hips outward', 'Bending the standing leg excessively']::text[], 'beginner'::difficulty_level, 'adductors', ARRAY['gluteus_medius', 'quadriceps']::text[], ARRAY['band']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'mobility'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-hip-adduction.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/band-hip-adduction.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('band-kneeling-one-arm-pulldown-0983', 'Band Kneeling One Arm Pulldown', 'A kneeling single-arm band pulldown that trains the lats by pulling the elbow down from an overhead position.', 'Attach the band to a sturdy anchor point above your head. Kneel down and hold the band with one hand, palm facing down. Extend your arm fully overhead, keeping your elbow slightly bent. Engage your lat muscles and pull the band down towards your side, bringing your elbow towards your ribcage. Pause for a moment at the bottom, then slowly release the tension and return to the starting position. Repeat for the desired number of repetitions, then switch sides.', ARRAY['Anchor the band overhead and kneel facing the anchor point.', 'Grab the band with one hand and extend that arm up and slightly forward.', 'Brace your torso and keep your chest tall without leaning back.', 'Pull your elbow down toward your side until your hand reaches about shoulder or rib level.', 'Squeeze your lat at the bottom while keeping your shoulder down.', 'Slowly straighten your arm back overhead under control.', 'Complete all reps on one side, then switch arms.']::text[], 'Inhale as your arm returns overhead, and exhale as you pull the band down to your side.', ARRAY['Leaning the torso back to finish the pull', 'Shrugging the shoulder up toward the ear', 'Bending and straightening the wrist during the pull', 'Letting the band snap the arm back overhead']::text[], 'beginner'::difficulty_level, 'lats', ARRAY['biceps', 'rhomboids']::text[], ARRAY['band']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-kneeling-one-arm-pulldown.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/band-kneeling-one-arm-pulldown.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('band-one-arm-front-raise-1017', 'Band One Arm Front Raise', 'Isolation shoulder exercise raising one arm forward against band resistance to target the anterior deltoid.', 'Stand on the band with feet shoulder-width apart and hold one handle with your working hand by your side. Keeping your arm straight but not locked, raise it in front of you to shoulder level. Pause, then slowly lower back down with control. Repeat on both sides.', ARRAY['Stand with one foot on the band for resistance.', 'Hold handle in one hand at thigh level, palm facing down.', 'Keep arm straight, raise it forward to shoulder height.', 'Pause briefly at the top.', 'Lower arm back down slowly and repeat.']::text[], 'Exhale as you lift, inhale as you lower.', ARRAY['Swinging the arm', 'Bending at the elbow', 'Raising above shoulder']::text[], 'beginner'::difficulty_level, 'anterior_deltoid', ARRAY['upper_pectoralis', 'serratus_anterior']::text[], ARRAY['band']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'shoulders'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-one-arm-forward-raise.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/band-one-arm-forward-raise.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('band-one-leg-kickback-bent-position-drv-band-one-leg-kickback-bent-position', 'Band One-Leg Kickback (Bent Position)', 'A glute-focused kickback performed from a bent-over position using a resistance band for added intensity.', 'Secure a resistance band around your working ankle and a sturdy anchor. Start on all fours with knees bent, kick one leg back against the band''s resistance while keeping your core tight, then return and repeat for reps before switching sides.', ARRAY['Anchor the band and loop it around your working ankle.', 'Start on all fours with hands under shoulders and knees bent.', 'Engage your core and extend one leg backward against band resistance.', 'Pause and squeeze the glute at the top.', 'Return to starting position and repeat for desired reps, then switch legs.']::text[], 'Exhale as you kick back, inhale as you bring the knee in.', ARRAY['Sagging the lower back', 'Rotating the hips', 'Using momentum']::text[], 'beginner'::difficulty_level, 'glutes', ARRAY['hamstrings', 'lower_back']::text[], ARRAY['band']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'glutes'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-one-leg-kickback-bent-position.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/band-one-leg-kickback-bent-position.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
