INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('band-overhead-triceps-extension-new-band-overhead-triceps-extension', 'Band Overhead Triceps Extension', 'A standing band triceps exercise where you extend your elbows overhead while keeping your upper arms mostly fixed.', 'Anchor a resistance band low behind you or hold it under your feet. Face away, grip the band with both hands and arms overhead, elbows bent. Extend your arms fully overhead while keeping elbows stationary, then return to the starting position with control.', ARRAY['Stand on the middle of the band with feet hip-width apart and hold one end in each hand.', 'Raise your hands overhead and bend your elbows so your hands move behind your head.', 'Keep your upper arms close to your ears and brace your midsection.', 'Straighten your elbows to press the band overhead until your arms are fully extended.', 'Pause briefly at the top, then bend your elbows slowly to return behind your head.', 'Repeat without letting your elbows flare wide.']::text[], 'Inhale as you lower your hands behind your head, and exhale as you straighten your elbows overhead.', ARRAY['Elbows flare out to the sides', 'Lower back arches as the band goes overhead', 'Upper arms drift forward and backward', 'Only moving partway instead of fully extending']::text[], 'beginner'::difficulty_level, 'triceps', ARRAY['shoulders', 'core']::text[], ARRAY['band']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'triceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-overhead-triceps-extension.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/band-overhead-triceps-extension.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('band-prone-leg-curl-0976', 'Band Prone Leg Curl', 'A hamstring isolation exercise performed lying face down and flexing the knee using resistance from a band.', 'Lie face down, anchor a resistance band at your feet, and loop the other end around your ankle. Curl your heel toward your glutes, contracting your hamstring, then slowly lower back to start and repeat.', ARRAY['Anchor the band securely at ground level.', 'Lie face down with legs extended.', 'Loop the band around your ankle.', 'Flex your knee, bringing your heel toward your glutes.', 'Slowly return to the start; repeat and switch legs if desired.']::text[], 'Exhale as you curl, inhale as you lower.', ARRAY['Lifting hips off ground', 'Using momentum', 'Letting band snap back']::text[], 'beginner'::difficulty_level, 'hamstrings', ARRAY['gastrocnemius', 'glutes']::text[], ARRAY['band']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'hamstrings'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-leg-curl.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/band-leg-curl.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('band-pull-through-0991', 'Band Pull Through', 'A banded hip hinge that trains the glutes and hamstrings by pulling the band through the legs as you stand tall.', 'Attach a resistance band to a sturdy anchor point at ground level. Stand facing away from the anchor point with your feet shoulder-width apart. Step forward to create tension in the band, keeping your knees slightly bent. Hinge at the hips and push your glutes back, maintaining a slight bend in your knees. Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings. Drive your hips forward and squeeze your glutes to return to the starting position. Repeat for the desired number of repetitions.', ARRAY['Anchor the band at floor level and loop it between your legs.', 'Face away from the anchor and walk forward until the band is taut.', 'Stand with feet about hip-width apart and soften your knees.', 'Push your hips back and hinge forward, letting the band travel behind you.', 'Lower until you feel your hamstrings stretch while keeping your back flat.', 'Drive your hips forward to stand tall and squeeze your glutes at the top.']::text[], 'Inhale as you hinge back and exhale as you drive your hips forward to stand.', ARRAY['Squatting down instead of hinging back', 'Rounding the lower back as you fold forward', 'Letting the band pull the hips backward at lockout', 'Bending the knees too much and shifting into the quads']::text[], 'beginner'::difficulty_level, 'glutes', ARRAY['hamstrings', 'lower_back']::text[], ARRAY['band']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'glutes'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-pull-through.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/band-pull-through.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
