INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('band-resisted-decline-sit-up-drv-band-decline-sit-ups', 'Band Resisted Decline Sit-Up', 'A decline sit-up performed with band resistance to increase tension on the abdominals.', 'Secure a resistance band behind your head or at chest level and lie on a decline bench. Perform a sit-up against the resistance, focusing on contracting your abs to lift your torso.', ARRAY['Attach a resistance band securely behind the decline bench.', 'Lie on the bench with your feet anchored, holding the band at the chest or behind the neck.', 'Engage your core and perform a sit-up, raising your torso towards your knees.', 'Control the movement back down to starting position.', 'Repeat for the desired repetitions.']::text[], 'Exhale as you sit up, inhale as you lower down.', ARRAY['Using momentum', 'Letting band go slack', 'Improper anchoring of feet']::text[], 'intermediate'::difficulty_level, 'rectus_abdominis', ARRAY['hip_flexors', 'obliques']::text[], ARRAY['band']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-decline-sit-ups.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/band-decline-sit-ups.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
