INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('band-seated-leg-extension-0980', 'Band Seated Leg Extension', 'A seated exercise using a resistance band to isolate and strengthen the quadriceps.', 'Sit on a chair, anchor a resistance band behind you, and loop it around your ankle. Extend your knee to straighten your leg against the band''s resistance, then lower back with control.', ARRAY['Sit upright on a sturdy chair with feet flat.', 'Anchor one end of a band behind the chair leg.', 'Loop the other end of the band around your ankle.', 'Raise your lower leg to extend the knee fully.', 'Lower the leg back down under control; repeat and switch legs.']::text[], 'Exhale as you extend, inhale as you return.', ARRAY['Swinging the leg', 'Allowing the knee to drift or twist', 'Arching back']::text[], 'beginner'::difficulty_level, 'quadriceps', '{}'::text[], ARRAY['band']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'quads'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-seated-leg-extension.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/band-seated-leg-extension.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
