INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('band-seated-row-0990', 'Band Seated Row', 'Seated row using resistance bands that targets the mid-back and lats.', 'Sit on the floor with your legs extended, loop the band around your feet, and grasp the ends. Keeping your back straight and core tight, pull the band handles towards your torso, squeezing your shoulder blades together. Slowly release to the starting position with control, maintaining slight tension in the band.', ARRAY['Sit on the floor with legs straight and loop the band over your feet.', 'Grab the band handles or ends with both hands, arms extended.', 'Keep back straight and chest up.', 'Pull the handles back, driving elbows past your torso and squeezing shoulder blades.', 'Release slowly to the starting position.']::text[], 'Exhale as you row, inhale as you return to start.', ARRAY['Rounding the back', 'Using momentum', 'Letting band slack between reps']::text[], 'beginner'::difficulty_level, 'lats', ARRAY['rhomboids', 'traps', 'posterior_deltoid', 'biceps']::text[], ARRAY['band']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-seated-row.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/band-seated-row.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
