INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('band-shoulder-warm-up-stretch-drv-stretching-band-warm-up-shoulder-stretch', 'Band Shoulder Warm-Up Stretch', 'A shoulder stretch and mobility drill using a resistance band to warm up the deltoids and rotator cuff.', 'Grip a resistance band with both hands wider than shoulder-width. Keep arms straight and move the band from hips, overhead, and behind the back to stretch the shoulders, then reverse the motion. Maintain a steady, controlled movement.', ARRAY['Stand tall and grip band with hands wider than shoulders.', 'Hold arms straight, band in front of thighs.', 'Slowly raise band overhead while keeping arms straight.', 'Move band behind head and down to lower back.', 'Reverse the movement to bring band to starting position.']::text[], 'Breathe naturally throughout stretch.', ARRAY['Bending arms', 'Rushing the movement', 'Arching lower back']::text[], 'beginner'::difficulty_level, 'deltoids', ARRAY['rotator_cuff', 'traps', 'pectoralis_major']::text[], ARRAY['band']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'shoulders'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-band-warm-up-shoulder-stretch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-band-warm-up-shoulder-stretch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('band-side-bend-0002', 'Band Side Bend', 'A standing lateral bend using a resistance band to target and strengthen the oblique muscles.', 'Stand upright with feet shoulder-width apart, holding one end of a resistance band anchored at your side. Keep your torso straight and bend laterally away from the anchored band, contracting your obliques, then return to the starting position.', ARRAY['Anchor the resistance band securely at ground level.', 'Stand beside the anchor point, feet shoulder-width apart.', 'Hold the band handle with the outside hand, arm extended alongside your body.', 'Keeping your torso straight, bend sideways at the waist away from the anchor.', 'Return to the starting position and repeat for reps, then switch sides.']::text[], 'Exhale while bending, inhale on the return.', ARRAY['Rotating the torso instead of bending laterally', 'Bending forward or backward', 'Letting the band snap back', 'Using momentum']::text[], 'beginner'::difficulty_level, 'obliques', ARRAY['rectus_abdominis', 'erector_spinae']::text[], ARRAY['band']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'abs'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-side-bend.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/band-side-bend.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('band-standing-calf-raise-0999', 'Band Standing Calf Raise', 'Standing calf raise performed with a resistance band to strengthen the calves.', 'Stand upright with both feet on the band and hold the handles by your sides or shoulders. Press through the balls of your feet to rise onto your toes, stretching the band, and slowly lower back down. Maintain balance and perform the movement with controlled tempo.', ARRAY['Stand with feet shoulder-width on the band.', 'Hold band handles by sides or at shoulders for resistance.', 'Keep torso upright and brace core.', 'Raise heels to stand on the balls of your feet, contracting calves.', 'Lower heels back to the floor slowly.']::text[], 'Exhale as you rise, inhale as you lower.', ARRAY['Partial reps', 'Letting heels drop too quickly', 'Leaning forward or backward']::text[], 'beginner'::difficulty_level, 'calves', ARRAY['soleus', 'tibialis_posterior']::text[], ARRAY['band']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-standing-calf-raise.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/band-standing-calf-raise.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
