INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('band-standing-crunch-1005', 'Band Standing Crunch', 'A standing abdominal crunch using a resistance band to train the abs and obliques through spinal flexion.', 'Attach the band to a sturdy anchor point at waist height. Stand facing away from the anchor point with your feet shoulder-width apart. Hold the band with both hands and bring it up to your chest, keeping your elbows bent and close to your body. Engage your abs and slowly crunch forward, bringing your chest towards your knees. Pause for a moment at the top of the crunch, then slowly return to the starting position. Repeat for the desired number of repetitions.', ARRAY['Attach the band to an anchor around waist height and stand facing away from it.', 'Hold the band at your chest with both hands and step forward until the band is taut.', 'Set your feet about hip-width apart and soften your knees.', 'Brace your midsection and curl your ribs down, bending your torso forward.', 'Pause briefly at the bottom while keeping your hips mostly still.', 'Slowly uncurl your torso and return to an upright position under control.']::text[], 'Exhale as you crunch forward, and inhale as you return to standing.', ARRAY['Pulling the band with the arms instead of curling the torso.', 'Hinging at the hips like a bow instead of rounding into a crunch.', 'Letting the band snap the torso back upright.', 'Standing too close to the anchor so the band has no tension.']::text[], 'beginner'::difficulty_level, 'abdominals', ARRAY['obliques']::text[], ARRAY['band']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-standing-crunch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/band-standing-crunch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('band-standing-leg-curl-0988', 'Band Standing Leg Curl', 'A standing hamstring curl variation using resistance from a band for leg flexion.', 'Anchor a resistance band at ankle height behind you, securing the loop around your ankle. Stand upright and curl your heel toward your glutes, keeping the upper leg stationary, then return to the starting position under control.', ARRAY['Anchor the resistance band behind you at ground level.', 'Loop the band around one ankle.', 'Stand on the opposite leg and balance.', 'Curl your heel toward your glutes by flexing your knee.', 'Lower leg slowly; repeat and switch sides.']::text[], 'Exhale as you curl, inhale as you return.', ARRAY['Letting knees move forward', 'Using back to assist', 'Letting band snap']::text[], 'beginner'::difficulty_level, 'hamstrings', ARRAY['gastrocnemius', 'glutes']::text[], ARRAY['band']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'hamstrings'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-standing-leg-curl.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/band-standing-leg-curl.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('band-standing-lift-1408', 'Band Standing Lift', 'A diagonal band movement to train the obliques and core stabilizers.', 'Anchor a resistance band low to the side. Stand sideways and grasp the free end with both hands. With arms extended, lift and rotate your torso diagonally upward across your body, then return in control.', ARRAY['Anchor the band low near the floor.', 'Stand side-on to the anchor, feet shoulder-width.', 'Hold the band handle with both hands at hip level.', 'Lift and rotate your torso diagonally to the opposite side and above shoulder.', 'Return to start; repeat, then switch sides.']::text[], 'Exhale as you lift/rotate, inhale as you return.', ARRAY['Using arms instead of core', 'Not rotating torso', 'Bending elbows excessively']::text[], 'beginner'::difficulty_level, 'obliques', ARRAY['rectus_abdominis', 'shoulders', 'hip_flexors']::text[], ARRAY['band']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'abs'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-standing-lift.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/band-standing-lift.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
