INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('band-standing-rear-delt-row-1022', 'Band Standing Rear Delt Row', 'A bent-over band row with elbows flared out to target the rear delts and upper back.', 'Stand with your feet shoulder-width apart and place the band under your feet. Hold the band handles with your palms facing each other and your arms extended in front of you. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Pull the band towards your chest, squeezing your shoulder blades together. Pause for a moment at the top, then slowly release the tension and return to the starting position. Repeat for the desired number of repetitions.', ARRAY['Stand on the middle of the band with feet about hip-width apart and hold one end in each hand.', 'Hinge forward at the hips with a soft bend in your knees until your torso leans forward and your arms hang below your shoulders.', 'Set your shoulders down and keep your chest open with your palms facing each other or slightly inward.', 'Pull your elbows out and back until your hands reach around lower chest to upper rib level.', 'Squeeze your rear shoulders and upper back at the top without shrugging.', 'Lower your hands back down under control until your arms are straight again.']::text[], 'Inhale as you lower to the start, and exhale as you row the band up.', ARRAY['Standing too upright and turning it into a regular row', 'Shrugging the shoulders toward the ears at the top', 'Pulling the hands too low toward the waist', 'Rounding the upper or lower back while hinging']::text[], 'beginner'::difficulty_level, 'deltoids', ARRAY['traps', 'rhomboids', 'biceps']::text[], ARRAY['band']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-standing-rear-delt-row.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/band-standing-rear-delt-row.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('band-straight-back-seated-row-3144', 'Band Straight-Back Seated Row', 'A banded rowing movement emphasizing the upper back and lats while seated with a straight torso.', 'Sit on the floor with legs extended, loop a resistance band around your feet, and hold the handles with both hands. Keeping your back straight and core engaged, pull the band towards your torso, squeezing your shoulder blades together, then return to the starting position with control.', ARRAY['Sit on the floor and extend your legs forward.', 'Loop the band around your feet securely.', 'Grip the band handles with both hands, arms extended.', 'Keeping your back straight, pull the handles toward your waist, elbows close to your body.', 'Pause, squeeze your shoulder blades, then slowly return to the starting position.']::text[], 'Exhale as you row, inhale as you return to start.', ARRAY['Rounding your back', 'Letting arms flare out', 'Using momentum rather than back muscles']::text[], 'beginner'::difficulty_level, 'lats', ARRAY['rhomboids', 'traps', 'biceps']::text[], ARRAY['band']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-straight-back-seated-row.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/band-straight-back-seated-row.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
