INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('band-triceps-pushdown-new-band-triceps-pushdown', 'Band Triceps Pushdown', 'An isolation triceps exercise using an overhead-anchored band to straighten the elbows against resistance.', 'Secure a resistance band to a high anchor. Stand facing the band, grasping it with both hands and elbows at your sides. Extend your arms downward, fully straightening the elbows, then return with control to the starting position.', ARRAY['Anchor the band overhead and stand facing it with a handle or end in each hand.', 'Bend your elbows to about 90 degrees and pin your upper arms close to your sides.', 'Brace your torso and press your hands straight down until your elbows fully extend.', 'Pause briefly at the bottom and squeeze your triceps.', 'Slowly let the band rise back up until your forearms return to the start position.', 'Repeat without letting your elbows drift forward or outward.']::text[], 'Exhale as you press the band down, and inhale as you return to the start.', ARRAY['Upper arms swinging forward and back', 'Elbows flaring away from the torso', 'Leaning body weight onto the band', 'Stopping short of full elbow extension']::text[], 'beginner'::difficulty_level, 'triceps', ARRAY['forearms']::text[], ARRAY['band']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'triceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-triceps-pushdown.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/band-triceps-pushdown.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
