INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('barbell-back-squat-1435', 'Barbell Back Squat', 'Classic compound lower body lift with barbell across traps, targeting quads and glutes.', 'Stand with barbell placed across upper back, feet shoulder-width apart. Lower into a squat by hinging hips and bending knees until your thighs are parallel to the floor. Press through your heels to stand back up, keeping your chest up and back straight.', ARRAY['Position barbell on upper traps, unrack.', 'Stand with feet shoulder-width apart.', 'Descend into squat keeping back neutral.', 'Lower until thighs parallel or below.', 'Drive up through heels to standing.']::text[], 'Inhale lowering, exhale rising.', ARRAY['Knees caving in', 'Rounding lower back', 'Heels lifting off floor']::text[], 'intermediate'::difficulty_level, 'quadriceps', ARRAY['glutes', 'hamstrings', 'erector_spinae', 'adductors', 'core']::text[], ARRAY['barbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/classic-barbell-squat.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/classic-barbell-squat.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('barbell-bench-press-0025', 'Barbell Bench Press', 'A flat bench press using a barbell to train the chest, triceps, and shoulders with a horizontal pressing motion.', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench. Grasp the barbell with an overhand grip slightly wider than shoulder-width apart. Lift the barbell off the rack and hold it directly above your chest with your arms fully extended. Lower the barbell slowly towards your chest, keeping your elbows tucked in. Pause for a moment when the barbell touches your chest. Push the barbell back up to the starting position by extending your arms. Repeat for the desired number of repetitions.', ARRAY['Lie flat on the bench with your eyes under the bar and plant your feet firmly on the floor.', 'Grip the bar slightly wider than shoulder width and straighten your arms to unrack it over your chest.', 'Lower the bar under control to your mid-chest while keeping your wrists stacked over your forearms.', 'Lightly touch your chest, then press the bar straight up until your arms are fully extended.', 'Guide the bar back into the rack once you finish the set.']::text[], 'Inhale as you lower the bar to your chest, and exhale as you press it back up.', ARRAY['Bar drifts toward the neck or stomach', 'Elbows flare straight out from the shoulders', 'Wrists bend backward under the bar', 'Hips lift off the bench during the press']::text[], 'intermediate'::difficulty_level, 'pectoralis_major', ARRAY['triceps', 'shoulders']::text[], ARRAY['barbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'chest'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/barbell-bench-press.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/barbell-bench-press.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('barbell-clean-and-press-0028', 'Barbell Clean And Press', 'A full-body barbell lift that moves the bar from the floor to the shoulders, then presses it overhead.', 'Stand with your feet shoulder-width apart and the barbell on the floor in front of you. Bend your knees and hinge at the hips to lower down and grip the barbell with an overhand grip, hands slightly wider than shoulder-width apart. Drive through your heels and extend your hips and knees to lift the barbell off the floor, keeping it close to your body. As the barbell reaches your thighs, explosively extend your hips, shrug your shoulders, and pull the barbell up towards your chest. As the barbell reaches chest height, quickly drop under it and catch it at shoulder level, with your elbows pointing forward and your palms facing up. From the catch position, press the barbell overhead by extending your arms and pushing the barbell straight up. Lower the barbell back down to the starting position and repeat for the desired number of repetitions.', ARRAY['Stand with your feet hip- to shoulder-width apart and place the barbell over your midfoot.', 'Bend at your hips and knees, grip the bar just outside your legs, and set your back flat with your chest up.', 'Push the floor away and lift the bar, keeping it close to your shins and thighs as you stand.', 'Explosively extend your hips, knees, and ankles, then shrug and pull yourself under the bar.', 'Catch the bar on the fronts of your shoulders with elbows forward and stand tall.', 'Press the bar straight overhead until your arms are locked out and the bar is over your shoulders.', 'Lower the bar back to your shoulders, then guide it down to the floor under control.']::text[], 'Inhale and brace before pulling from the floor, then exhale as you press overhead and reset your breath before the next rep.', ARRAY['Starting with the bar too far in front of the feet', 'Rounding the lower back when pulling from the floor', 'Catching the bar with elbows low and chest collapsed', 'Pressing the bar forward instead of overhead']::text[], 'advanced'::difficulty_level, 'quadriceps', ARRAY['hamstrings', 'glutes', 'shoulders', 'triceps']::text[], ARRAY['barbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/barbell-clean-and-press.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/barbell-clean-and-press.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('barbell-close-grip-bench-press-0030', 'Barbell Close Grip Bench Press', 'Bench press variation with close grip targeting triceps along with chest and shoulders.', 'Lie on a bench with feet flat, grip the barbell with hands about shoulder-width apart or slightly narrower. Lower the bar to your lower chest while keeping elbows tucked. Press the bar back up, focusing on extending through your triceps.', ARRAY['Lie on bench and grasp barbell with close grip.', 'Unrack and position bar above lower chest.', 'Lower bar slowly, elbows close to sides.', 'Touch chest briefly, then press bar to starting position.', 'Repeat for reps.']::text[], 'Exhale pressing up, inhale lowering bar.', ARRAY['Gripping too narrow or wide', 'Elbows flaring out', 'Bouncing bar on chest']::text[], 'intermediate'::difficulty_level, 'triceps', ARRAY['pectoralis_major', 'anterior_deltoid']::text[], ARRAY['barbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'triceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/barbell-close-grip-bench-press.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/barbell-close-grip-bench-press.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('barbell-curl-0031', 'Barbell Curl', 'A standing biceps exercise where you curl a barbell from your thighs to shoulder height with an underhand grip.', 'Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing forward. Keep your elbows close to your torso and exhale as you curl the weights while contracting your biceps. Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale as you slowly begin to lower the bar back to the starting position. Repeat for the desired number of repetitions.', ARRAY['Stand tall with your feet hip-width apart and hold the barbell at your thighs with an underhand grip.', 'Set your shoulders back, brace your torso, and keep your elbows pinned by your sides.', 'Curl the bar upward by bending your elbows until the bar reaches about shoulder height.', 'Pause briefly at the top and squeeze your biceps without letting your elbows drift forward.', 'Lower the bar slowly back to your thighs until your arms are straight.']::text[], 'Exhale as you curl the bar up, and inhale as you lower it back down under control.', ARRAY['Swinging the torso to start the bar moving', 'Letting the elbows drift forward as the bar rises', 'Bending the wrists back instead of keeping them neutral', 'Dropping the bar quickly on the way down']::text[], 'beginner'::difficulty_level, 'biceps', ARRAY['forearms']::text[], ARRAY['barbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'biceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/barbell-curl.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/barbell-curl.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('barbell-decline-bench-press-0033', 'Barbell Decline Bench Press', 'A decline barbell press done on a downward-angled bench to train the chest, triceps, and shoulders through a pressing pattern.', 'Lie on a decline bench with your feet secured and your head lower than your hips. Grasp the barbell with an overhand grip slightly wider than shoulder-width apart. Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in. Pause for a moment at the bottom, then push the barbell back up to the starting position. Repeat for the desired number of repetitions.', ARRAY['Lie on the decline bench and secure your legs under the pads with your eyes under the bar.', 'Grip the bar slightly wider than shoulder width and pull your shoulder blades back into the bench.', 'Unrack the bar and hold it above your lower chest with straight wrists and locked elbows.', 'Lower the bar under control to your lower chest or upper sternum while keeping your elbows at about a 45-degree angle.', 'Press the bar straight up until your elbows are extended and the bar returns over your lower chest.', 'Repeat each rep with the same bar path and controlled tempo.']::text[], 'Inhale as you lower the bar to your chest, and exhale as you press it back up.', ARRAY['Bouncing the bar off the chest', 'Flaring the elbows straight out to the sides', 'Letting the wrists bend back under the bar', 'Pressing the bar toward the face instead of over the chest']::text[], 'intermediate'::difficulty_level, 'pectoralis_major', ARRAY['triceps', 'shoulders']::text[], ARRAY['barbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'chest'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/barbell-decline-bench-press.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/barbell-decline-bench-press.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('barbell-drag-curl-0038', 'Barbell Drag Curl', 'A barbell biceps curl variation where the bar stays close to the torso and the elbows move back as you lift.', 'Stand with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up. Let the barbell hang at arm''s length in front of your thighs. Keeping your upper arms stationary, curl the barbell up towards your chest by contracting your biceps. Pause for a moment at the top, then slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', ARRAY['Stand tall with feet about hip-width apart and hold the barbell with an underhand grip at your thighs.', 'Pull your shoulders slightly back and keep your elbows behind your torso.', 'Curl the bar upward by sliding it close along the front of your body as your elbows travel back.', 'Lift until the bar reaches your upper stomach or lower chest without letting it drift away from you.', 'Lower the barbell slowly along the same path until your arms are straight again.']::text[], 'Inhale at the bottom, exhale as you drag-curl the bar up, and inhale as you lower it back down.', ARRAY['Letting the bar swing forward away from the body', 'Bending the wrists back as the bar rises', 'Rocking the torso to start the curl', 'Flaring the elbows out to the sides']::text[], 'intermediate'::difficulty_level, 'biceps', ARRAY['forearms']::text[], ARRAY['barbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'biceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/barbell-drag-curl.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/barbell-drag-curl.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
