INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('barbell-front-raise-0041', 'Barbell Front Raise', 'A shoulder isolation exercise where you lift a barbell straight in front of your body to train the front delts.', 'Stand with your feet shoulder-width apart and hold a barbell in front of your thighs with an overhand grip. Keep your arms straight and lift the barbell forward and upward until it reaches shoulder level. Pause for a moment at the top, then slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', ARRAY['Stand tall with your feet hip-width apart and hold the barbell against your thighs with an overhand grip.', 'Brace your core and keep a soft bend in your elbows.', 'Raise the barbell straight forward in front of you until it reaches shoulder height.', 'Pause briefly without shrugging your shoulders.', 'Lower the barbell back to your thighs with control.', 'Reset your posture and repeat the movement.']::text[], 'Exhale as you raise the barbell, and inhale as you lower it back down.', ARRAY['Leaning back to start the lift.', 'Swinging the barbell with the hips.', 'Raising the barbell above shoulder height.', 'Shrugging the shoulders toward the ears.']::text[], 'beginner'::difficulty_level, 'deltoids', ARRAY['biceps', 'triceps']::text[], ARRAY['barbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/barbell-front-raise.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/barbell-front-raise.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
