INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('barbell-front-squat-0042', 'Barbell Front Squat', 'Squat variation with barbell held at the front rack position, targeting the quadriceps.', 'Stand upright, barbell resting across front shoulders, elbows high. Descend into a squat while keeping torso upright and elbows elevated. Push through your heels to return to standing, maintaining bar balance throughout.', ARRAY['Rack barbell at collarbone level, elbows up.', 'Stand with feet shoulder-width apart.', 'Descend into squat keeping torso upright.', 'Lower until thighs are parallel to floor.', 'Drive up through heels to stand.']::text[], 'Inhale when lowering, exhale standing up.', ARRAY['Letting elbows drop', 'Rounding back', 'Heels lifting off floor']::text[], 'intermediate'::difficulty_level, 'quadriceps', ARRAY['glutes', 'hamstrings', 'erector_spinae', 'core']::text[], ARRAY['barbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/barbell-front-chest-squat.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/barbell-front-chest-squat.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
