INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('barbell-lunge-0054', 'Barbell Lunge', 'A lower-body lunge with a barbell on your upper back that trains the glutes, quads, and hamstrings one leg at a time.', 'Start by standing with your feet shoulder-width apart and a barbell resting on your upper back. Take a step forward with your right foot, keeping your torso upright. Lower your body by bending your right knee until your thigh is parallel to the ground. Push through your right heel to return to the starting position. Repeat with your left leg, alternating legs for the desired number of repetitions.', ARRAY['Set the barbell across your upper back and stand tall with feet hip-width apart.', 'Brace your core and take a controlled step forward with one foot.', 'Lower your body until both knees bend and your back knee moves toward the floor.', 'Keep your front foot flat and your torso upright at the bottom position.', 'Push through the front foot to stand back up and bring your feet together.', 'Repeat on the other side, alternating legs each rep.']::text[], 'Inhale as you step forward and lower down, then exhale as you push back to standing.', ARRAY['Taking such a short step that the front knee shoots far past the toes.', 'Leaning the torso forward as you lower.', 'Letting the front knee cave inward.', 'Pushing off the back foot instead of driving through the front foot.']::text[], 'intermediate'::difficulty_level, 'glutes', ARRAY['quadriceps', 'hamstrings', 'calves']::text[], ARRAY['barbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'glutes'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/barbell-lunge.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/barbell-lunge.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
