INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('barbell-prone-incline-curl-0072', 'Barbell Prone Incline Curl', 'A chest-supported biceps curl on an incline bench using a barbell to isolate elbow flexion with minimal body swing.', 'Set up an incline bench at a 45-degree angle. Lie face down on the bench with your chest and stomach resting against it. Hold a barbell with an underhand grip, shoulder-width apart. Extend your arms fully, allowing the barbell to hang down towards the floor. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the barbell until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the barbell back to the starting position. Repeat for the desired number of repetitions.', ARRAY['Set an incline bench and lie face down with your chest supported and your feet planted on the floor.', 'Hold the barbell with an underhand grip about shoulder-width apart and let your arms hang straight down.', 'Brace your torso against the bench and keep your upper arms still.', 'Curl the barbell upward by bending your elbows until the bar reaches near the front of your shoulders.', 'Squeeze your biceps briefly at the top without lifting your chest off the bench.', 'Lower the barbell under control until your elbows are fully extended again.']::text[], 'Inhale at the bottom, exhale as you curl the bar up, and inhale again as you lower it back down.', ARRAY['Lifting the chest off the bench to help the bar up', 'Letting the elbows drift forward during the curl', 'Using body swing or kicking the legs to create momentum', 'Dropping the bar quickly instead of lowering it under control']::text[], 'beginner'::difficulty_level, 'biceps', ARRAY['forearms']::text[], ARRAY['barbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'biceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/barbell-prone-incline-curl.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/barbell-prone-incline-curl.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
