INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('barbell-rear-delt-raise-0075', 'Barbell Rear Delt Raise', 'A bent-over barbell raise that targets the rear delts by lifting the arms out to the sides while holding a barbell.', 'Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Raise the barbell out to the sides, keeping your arms straight, until they are parallel to the ground. Pause for a moment at the top, then slowly lower the barbell back to the starting position. Repeat for the desired number of repetitions.', ARRAY['Stand tall holding the barbell with a shoulder-width overhand grip.', 'Soften your knees and hinge at your hips until your torso is nearly parallel to the floor.', 'Let the bar hang below your chest with your arms straight and your neck neutral.', 'Raise the bar out and up by moving your upper arms to the sides until they reach shoulder height.', 'Pause briefly at the top while keeping your torso still.', 'Lower the bar under control to the starting position.']::text[], 'Inhale as you lower the bar and set your hinge, then exhale as you raise the bar out to the sides.', ARRAY['Rounding the lower back as you hinge forward', 'Swinging the torso to heave the bar upward', 'Shrugging the shoulders toward the ears', 'Turning it into a row by bending the elbows too much']::text[], 'intermediate'::difficulty_level, 'deltoids', ARRAY['traps', 'rhomboids']::text[], ARRAY['barbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/barbell-rear-delt-raise.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/barbell-rear-delt-raise.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('barbell-reverse-wrist-curl-0082', 'Barbell Reverse Wrist Curl', 'A wrist flexion exercise performed with a pronated grip to target the forearm extensors.', 'Sit on a bench holding a barbell with an overhand grip, forearms resting on your thighs, and wrists hanging over the edge. Extend your wrists upward, lifting the bar, then lower under control.', ARRAY['Sit on a bench and grasp a barbell with an overhand (pronated) grip.', 'Rest your forearms on your thighs with wrists hanging just beyond your knees.', 'Begin with your wrists flexed downward.', 'Slowly curl your wrists upward, lifting the barbell.', 'Lower under control to the starting position.']::text[], 'Exhale as you curl the bar up, inhale as you lower.', ARRAY['Using too much weight', 'Lifting with elbows or shoulders', 'Letting the barbell roll in hands']::text[], 'beginner'::difficulty_level, 'forearms', '{}'::text[], ARRAY['barbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'triceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/barbell-reverse-wrist-curl-over-grip.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/barbell-reverse-wrist-curl-over-grip.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('barbell-seated-behind-the-neck-press-drv-barbell-seated-behind-head-military-press', 'Barbell Seated Behind-The-Neck Press', 'A shoulder press variation performed seated with a barbell lowered behind the neck to target the deltoids.', 'Sit on a bench with back support and grip the barbell with hands wider than shoulder-width. Lower the barbell slowly behind your head to just below ear level, then press upward until arms are fully extended. Use a spotter and maintain upright posture.', ARRAY['Sit on a bench with back support; grip barbell wider than shoulders.', 'Unrack barbell and hold above your head.', 'Lower barbell behind your head to just below ear level.', 'Press barbell back up to the starting position.', 'Repeat for desired reps, keeping core engaged.']::text[], 'Exhale when pressing up, inhale when lowering the bar.', ARRAY['Flaring elbows excessively', 'Arching lower back', 'Lowering bar too far']::text[], 'advanced'::difficulty_level, 'deltoids', ARRAY['triceps', 'traps']::text[], ARRAY['barbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'shoulders'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/barbell-seated-behind-head-military-press.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/barbell-seated-behind-head-military-press.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('barbell-shrug-0095', 'Barbell Shrug', 'A standing trap exercise where you hold a barbell at your thighs and lift your shoulders straight up and down.', 'Stand with your feet shoulder-width apart and hold a barbell in front of you with an overhand grip. Keep your arms straight and your back straight throughout the exercise. Lift your shoulders up towards your ears as high as possible, squeezing your traps at the top. Hold for a moment, then slowly lower your shoulders back down to the starting position. Repeat for the desired number of repetitions.', ARRAY['Stand tall with your feet hip- to shoulder-width apart and hold the barbell in front of your thighs with an overhand grip.', 'Let your arms hang straight, brace your torso, and keep your chest up.', 'Lift your shoulders straight up toward your ears without bending your elbows or leaning back.', 'Pause briefly at the top and squeeze your upper traps.', 'Lower your shoulders under control until they return to the starting position.']::text[], 'Inhale before each rep, exhale as you shrug your shoulders up, and inhale as you lower back down.', ARRAY['Bending the elbows to curl the bar upward.', 'Rolling the shoulders forward or backward at the top.', 'Leaning back and swinging the torso to move the bar.', 'Letting the head jut forward as the shoulders rise.']::text[], 'beginner'::difficulty_level, 'traps', ARRAY['shoulders']::text[], ARRAY['barbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/barbell-shrug.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/barbell-shrug.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('barbell-standing-back-wrist-curl-0104', 'Barbell Standing Back Wrist Curl', 'A standing forearm exercise where you hold a barbell behind your body and lift it by curling only your wrists.', 'Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip. Rest the barbell on the back of your hands with your palms facing down and your fingers pointing towards your body. Keeping your upper arms stationary, exhale and curl your wrists upwards as far as possible. Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position. Repeat for the desired number of repetitions.', ARRAY['Stand tall with your feet about hip-width apart and hold a barbell behind your hips with an overhand grip.', 'Let the bar rest across your fingers so your knuckles face the floor and your palms face behind you.', 'Keep your elbows close to your sides and straighten your wrists to lower the bar toward your fingertips.', 'Curl your wrists upward to roll the bar back into your hands and lift it as high as you can.', 'Pause briefly at the top, then lower the bar with control back to the starting position.']::text[], 'Inhale as you lower the bar toward your fingertips, and exhale as you curl your wrists up.', ARRAY['Swinging the bar with the shoulders or torso', 'Bending the elbows to lift the bar', 'Letting the bar slip too far out of the hands', 'Using short, jerky wrist motions']::text[], 'beginner'::difficulty_level, 'forearms', ARRAY['biceps', 'shoulders']::text[], ARRAY['barbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'triceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/barbell-standing-back-wrist-curl.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/barbell-standing-back-wrist-curl.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('barbell-straight-leg-deadlift-0116', 'Barbell Straight Leg Deadlift', 'A barbell hip hinge that trains the hamstrings and glutes by lowering the bar down the legs with minimal knee bend.', 'Stand with your feet shoulder-width apart and your toes pointing forward. Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart. Bend at your hips and lower the barbell towards the ground, keeping your back straight and your knees slightly bent. Lower the barbell until you feel a stretch in your hamstrings. Engage your hamstrings and glutes to lift the barbell back up to the starting position. Repeat for the desired number of repetitions.', ARRAY['Stand tall with your feet hip-width apart and hold the barbell in front of your thighs with straight arms.', 'Soften your knees slightly and brace your midsection.', 'Push your hips back and lower the bar down your legs while keeping your back flat and your legs nearly straight.', 'Lower until the bar reaches mid-shin or until you feel a strong hamstring stretch without losing your back position.', 'Drive your hips forward and stand tall, keeping the bar close to your legs the whole way up.', 'Finish with your hips locked out and shoulders stacked over your hips.']::text[], 'Inhale and brace before hinging down, then exhale as you drive your hips forward to stand up.', ARRAY['Bending the knees into a squat as the bar lowers', 'Letting the bar drift forward away from the legs', 'Rounding the lower back near the bottom', 'Jerking the bar off the bottom instead of lifting smoothly']::text[], 'intermediate'::difficulty_level, 'hamstrings', ARRAY['glutes', 'lower_back']::text[], ARRAY['barbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'hamstrings'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/barbell-straight-leg-deadlift.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/barbell-straight-leg-deadlift.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
