INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('barbell-underhand-bent-over-row-0027', 'Barbell Underhand Bent-Over Row', 'Row performed bent over with barbell and an underhand (supinated) grip, targeting lats and biceps.', 'Stand with feet hip-width apart, grasp the barbell with a supinated (underhand) grip. Bend forward at the hips keeping your back flat, bar hanging from extended arms. Pull the bar towards your lower ribs, squeezing shoulder blades, then lower it until arms are straight.', ARRAY['Stand with feet hip-width apart, barbell on floor.', 'Bend forward from hips, back straight, grasp bar underhand.', 'Let bar hang at arm’s length below shoulders.', 'Row barbell to torso, elbows close to sides.', 'Lower barbell under control to starting position.']::text[], 'Exhale as you row up, inhale as you lower down.', ARRAY['Rounding lower back', 'Flaring elbows excessively', 'Using momentum']::text[], 'intermediate'::difficulty_level, 'lats', ARRAY['biceps', 'rhomboids', 'traps', 'posterior_deltoid']::text[], ARRAY['barbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/barbell-underhand-bent-over-row.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/barbell-underhand-bent-over-row.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('barbell-wide-grip-upright-row-0123', 'Barbell Wide-Grip Upright Row', 'A compound barbell lift with a wide grip to target the shoulders and upper back.', 'Stand with feet shoulder-width apart, holding a barbell with a wide grip resting in front of your thighs. Pull the bar straight up toward your chest, lifting elbows high, then lower slowly.', ARRAY['Stand upright with feet shoulder width apart.', 'Hold the barbell using a wide, overhand grip.', 'Let the bar rest in front of your thighs.', 'Lift the bar straight up toward your chest, elbows out to the sides.', 'Lower the bar slowly to the starting position.']::text[], 'Exhale as you lift, inhale as you lower.', ARRAY['Shrugging shoulders excessively', 'Using too much momentum', 'Hands too close']::text[], 'intermediate'::difficulty_level, 'deltoids', ARRAY['traps', 'biceps']::text[], ARRAY['barbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'shoulders'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/barbell-upright-row-wide-grip.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/barbell-upright-row-wide-grip.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('battling-ropes-0128', 'Battling Ropes', 'A rope conditioning exercise using alternating arm waves to train the shoulders, forearms, and core.', 'Stand with your feet shoulder-width apart and knees slightly bent. Hold one end of the rope in each hand, with your palms facing each other. Raise your arms to shoulder height, keeping your elbows slightly bent. Begin making alternating waves with the ropes by rapidly raising and lowering each arm. Continue for the desired duration or number of repetitions.', ARRAY['Anchor your stance with feet about shoulder-width apart and bend your knees slightly.', 'Hold one rope end in each hand with your palms facing each other and your arms in front of you.', 'Brace your core and lift one hand as you lower the other to start the waves.', 'Keep alternating your arms quickly to send continuous waves down the ropes.', 'Maintain the slight knee bend and steady torso as you keep the waves even.']::text[], 'Breathe steadily throughout, exhaling with the arm drive and inhaling as the arms switch.', ARRAY['Standing upright with locked knees', 'Swinging the whole torso instead of the arms', 'Letting the waves become uneven or stop', 'Lifting the shoulders up toward the ears']::text[], 'beginner'::difficulty_level, 'deltoids', ARRAY['forearms', 'core']::text[], ARRAY['band']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/battling-ropes.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/battling-ropes.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
