INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('bench-crunch-drv-crunch-on-bench', 'Bench Crunch', 'An abdominal crunch performed lying on a flat or decline bench to isolate the abs.', 'Lie back on a bench with your knees bent and feet on the bench or floor. Cross your arms over your chest or place hands lightly behind your head, engage your abs, and lift your shoulders off the bench before lowering them down under control.', ARRAY['Lie flat on a bench with knees bent and feet secured or flat.', 'Cross your arms over your chest or place hands behind your head.', 'Engage your core and lift your shoulders towards your knees.', 'Squeeze at the top and hold briefly.', 'Lower your upper body back to bench in a controlled manner.']::text[], 'Exhale as you lift, inhale as you lower.', ARRAY['Pulling on neck', 'Rushing reps', 'Lifting too high']::text[], 'beginner'::difficulty_level, 'rectus_abdominis', ARRAY['obliques']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/crunch-on-bench.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/crunch-on-bench.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('bench-dips-drv-bench-dips', 'Bench Dips', 'Bench dips are a bodyweight exercise targeting the triceps by lowering and raising the body using a bench for support.', 'Sit on the edge of a stable bench and place your hands next to your hips, fingers forward. Slide your hips off the edge, keeping your legs extended, and lower your body by bending your elbows until your upper arms are roughly parallel to the floor, then press back up to the starting position.', ARRAY['Sit on a bench and place your hands beside your hips, gripping the edge.', 'Extend your legs out in front with heels on the floor.', 'Slide your hips off the bench, supporting your weight with your arms.', 'Lower your body by bending your elbows to about 90 degrees.', 'Push through your palms to extend your elbows and return to the start.']::text[], 'Inhale as you lower down, exhale as you press upward.', ARRAY['Allowing elbows to flare out', 'Shrugging shoulders upward', 'Dropping hips too low']::text[], 'beginner'::difficulty_level, 'triceps', ARRAY['pectoralis_major', 'anterior_deltoid']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'triceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/bench-dips.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/bench-dips.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('bench-pull-up-0570', 'Bench Pull-Up', 'A pull-up variation using a bench for foot support to reduce load and assist the movement.', 'Set a bench or box under a pull-up bar and place your feet on it for support. Grip the bar overhead and engage your lats to pull your chest up, using your legs to assist as needed, then lower yourself under control.', ARRAY['Place a bench under a pull-up bar.', 'Grip the bar with hands wider than shoulder-width.', 'Position feet on the bench for support.', 'Pull your chest towards the bar, using feet as needed.', 'Lower yourself slowly to starting position.']::text[], 'Exhale as you pull up, inhale as you lower down.', ARRAY['Using too much leg drive', 'Swinging body or kicking feet', 'Chin barely reaching bar', 'Not controlling descent']::text[], 'beginner'::difficulty_level, 'lats', ARRAY['biceps', 'rhomboids', 'brachialis', 'traps']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/bench-pull-ups.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/bench-pull-ups.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('bent-knee-lying-twist-on-stability-ball-3639', 'Bent Knee Lying Twist on Stability Ball', 'A rotational stretch on a stability ball that targets the obliques and hip flexors.', 'Lie on your back with your calves resting on a stability ball, arms extended to sides. With knees bent, gently rotate your knees side to side, engaging your core to control the movement.', ARRAY['Lie on your back with calves on a stability ball.', 'Extend arms out at your sides for support.', 'Bend knees at 90 degrees over the ball.', 'Slowly drop knees to one side, keeping shoulders flat.', 'Return to center and repeat on the other side.']::text[], 'Exhale as you twist, inhale returning to center.', ARRAY['Letting shoulders lift off floor', 'Moving too quickly', 'Over-twisting hips']::text[], 'beginner'::difficulty_level, 'obliques', ARRAY['rectus_abdominis', 'glutes']::text[], ARRAY['bench']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'abs'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/bent-knee-lying-twist-on-stability-ball.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/bent-knee-lying-twist-on-stability-ball.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('bridge-pose-setu-bandhasana-drv-stretching-bridge-pose-setu-bandhasana', 'Bridge Pose (Setu Bandhasana)', 'A yoga pose that stretches and activates the glutes, lower back, and hip flexors.', 'Lie on your back with knees bent, feet flat on the floor. Push through your heels to lift your hips toward the ceiling while keeping your back straight. Hold, then lower back down slowly.', ARRAY['Lie on your back with your knees bent and feet hip-width apart.', 'Place your arms at your sides, palms down.', 'Press through your heels and lift your hips upward.', 'Hold the pose, engaging your glutes and core.', 'Lower your hips back to the starting position.']::text[], 'Exhale as you lift hips, inhale as you lower down.', ARRAY['Arching the back excessively', 'Letting knees fall outward or inward', 'Not engaging the core']::text[], 'beginner'::difficulty_level, 'glutes', ARRAY['hamstrings', 'erector_spinae', 'hip_flexors']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'glutes'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-bridge-pose-setu-bandhasana.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-bridge-pose-setu-bandhasana.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('bridge-pose-setu-bandhasana-drv-stretching-bridge-pose-setu-bandhasana-1', 'Bridge Pose (Setu Bandhasana)', 'Bridge Pose is a yoga stretch that lifts the hips to activate the glutes and open the chest and hip flexors.', 'Lie on your back with knees bent, feet flat on the floor, and arms at your sides. Press through your heels to lift your hips toward the ceiling, engaging the glutes and lower back, and hold at the top for a stretch. Lower slowly to the ground and repeat as needed.', ARRAY['Lie flat on your back with knees bent and feet hip-width apart.', 'Place arms alongside your body, palms down.', 'Press into your heels to lift your hips off the floor, creating a straight line from knees to shoulders.', 'Engage your glutes and hold the top position for several seconds.', 'Lower your hips back down in a controlled motion.']::text[], 'Exhale as you lift hips, inhale as you lower down.', ARRAY['Letting knees flare outward', 'Overarching lower back', 'Not engaging glutes']::text[], 'beginner'::difficulty_level, 'glutes', ARRAY['hamstrings', 'lower_back', 'hip_flexors']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'glutes'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-bridge-pose-setu-bandhasana-1.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-bridge-pose-setu-bandhasana-1.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('burpee-1160', 'Burpee', 'A full-body bodyweight movement that combines a squat, plank, push-up, and jump for conditioning.', 'Start in a standing position with your feet shoulder-width apart. Lower your body into a squat position by bending your knees and placing your hands on the floor in front of you. Kick your feet back into a push-up position. Perform a push-up, keeping your body in a straight line. Jump your feet back into the squat position. Jump up explosively, reaching your arms overhead. Land softly and immediately lower back into a squat position to begin the next repetition.', ARRAY['Stand tall with your feet about hip-width apart.', 'Bend your knees, hinge at your hips, and place your hands on the floor in front of your feet.', 'Jump both feet back to a high plank with your body in a straight line.', 'Lower your chest to the floor, then press back up to plank.', 'Jump both feet forward to the outside of your hands.', 'Drive through your feet and jump straight up, reaching your arms overhead as you leave the floor.', 'Land softly and go straight into the next rep.']::text[], 'Inhale as you drop down and move into plank, then exhale as you press up and jump.', ARRAY['Hips sagging low in the plank or push-up.', 'Feet landing too narrow under the body.', 'Hands placed far in front of the shoulders.', 'Landing stiff-legged with no knee bend.']::text[], 'intermediate'::difficulty_level, 'cardiovascular_system', ARRAY['quadriceps', 'hamstrings', 'calves', 'shoulders', 'chest']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/burpee.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/burpee.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('butterfly-yoga-pose-1494', 'Butterfly Yoga Pose', 'A seated stretch that opens the hips and groin by bringing the feet together and letting the knees fall outward.', 'Sit on the floor with your back straight, bring the soles of your feet together, and allow your knees to drop out to the sides. Hold your feet with your hands and gently press knees toward the ground for a deeper stretch.', ARRAY['Sit upright with feet together and knees bent out to sides.', 'Hold your feet with your hands.', 'Keep spine tall and shoulders relaxed.', 'Gently press knees toward the floor.', 'Hold the position, breathing deeply.']::text[], 'Breathe evenly throughout the stretch.', ARRAY['Rounding the back', 'Bouncing knees', 'Forcing knees down']::text[], 'beginner'::difficulty_level, 'adductors', ARRAY['groin', 'lower_back']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'mobility'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-butterfly-yoga-pose.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-butterfly-yoga-pose.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
