INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('cable-close-grip-lat-pulldown-0974', 'Cable Close Grip Lat Pulldown', 'A cable exercise using a close grip to target the latissimus dorsi and supporting back muscles.', 'Sit at a lat pulldown machine with a close (V-bar) handle attached. Grasp the handles with palms facing in, keep your torso upright, and pull the handle down to your chest by squeezing your back and bringing elbows down and back, then return the handle under control.', ARRAY['Attach a V-bar or close grip handle to the cable machine.', 'Sit down and secure your thighs under the pads.', 'Grasp the handle with a neutral grip, hands parallel.', 'Pull the handle down to the top of your chest, keeping torso vertical.', 'Slowly return the handle to the top without locking elbows.']::text[], 'Exhale as you pull down, inhale as you return up.', ARRAY['Leaning back excessively', 'Using momentum', 'Not fully engaging lats', 'Rounding shoulders forward']::text[], 'beginner'::difficulty_level, 'lats', ARRAY['biceps', 'rhomboids', 'teres_major', 'forearms']::text[], ARRAY['cable']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/cable-close-grip-front-lat-pulldown.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/cable-close-grip-front-lat-pulldown.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
