INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('cable-crossover-reverse-fly-0154', 'Cable Crossover Reverse Fly', 'A cable rear-delt fly where you pull crossed low handles out and back to train the back of the shoulders and upper back.', 'Attach a D-handle to each low pulley cable and stand in the middle of the cable crossover machine. Grasp the handles with a pronated grip (palms facing down) and take a step forward, positioning your feet shoulder-width apart. Bend your knees slightly and lean forward at the waist, keeping your back straight and your abs engaged. With your arms extended out to the sides and slightly bent at the elbows, exhale and squeeze your shoulder blades together as you pull the cables back and upward in a reverse fly motion. Pause for a moment at the peak contraction, then inhale and slowly return to the starting position. Repeat for the desired number of repetitions.', ARRAY['Set both cable handles to the low pulleys and stand centered between them.', 'Grab the left handle in your right hand and the right handle in your left hand, then step forward to create tension.', 'Hinge forward slightly with a soft bend in your knees and keep your chest up and back flat.', 'Start with your arms angled down and crossed in front of you, elbows slightly bent.', 'Pull both arms out and back in a wide arc until your hands reach about shoulder height.', 'Squeeze your rear shoulders and upper back at the end position.', 'Return the handles slowly to the start without shrugging or changing your torso position.']::text[], 'Inhale as you return the handles to the start, and exhale as you pull your arms out and back.', ARRAY['Standing fully upright and turning it into a row', 'Bending and straightening the elbows during the rep', 'Shrugging the shoulders up toward the ears', 'Swinging the torso to move the handles']::text[], 'intermediate'::difficulty_level, 'deltoids', ARRAY['rhomboids', 'traps']::text[], ARRAY['cable']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/cable-crossover-reverse-fly.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/cable-crossover-reverse-fly.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('cable-kneeling-crunch-0175', 'Cable Kneeling Crunch', 'A kneeling cable ab exercise where you curl your torso downward against a high pulley to train the abs and obliques.', 'Attach a rope handle to a high pulley and kneel down facing away from the machine. Hold the rope handle with both hands and place it behind your head, keeping your elbows out to the sides. Keeping your hips stationary, flex your waist and crunch your torso down towards your thighs. Pause for a moment at the bottom, then slowly return to the starting position. Repeat for the desired number of repetitions.', ARRAY['Attach a rope handle to the high pulley and kneel facing the machine.', 'Grab the rope ends and bring your hands beside your head with your elbows slightly forward.', 'Brace your midsection and keep your hips stacked over your knees.', 'Curl your ribcage toward your pelvis and bring your elbows down toward your thighs.', 'Pause briefly in the bottom position while keeping tension on the rope.', 'Slowly uncurl your spine and return to the start without letting the weight stack slam.']::text[], 'Exhale as you curl down into the crunch, and inhale as you slowly return to the starting position.', ARRAY['Pulling the rope down with the arms instead of curling the torso', 'Sitting hips back and turning it into a hip hinge', 'Jerking up and letting the weight stack drop between reps', 'Lifting the chest too high and losing abdominal tension at the top']::text[], 'beginner'::difficulty_level, 'abdominals', ARRAY['obliques']::text[], ARRAY['cable']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/cable-kneeling-crunch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/cable-kneeling-crunch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('cable-lateral-raise-0178', 'Cable Lateral Raise', 'A single-arm cable shoulder isolation exercise that raises the arm out to the side to target the lateral delts.', 'Stand with your feet shoulder-width apart and grasp the cable handles with an overhand grip. Keep your arms straight and your core engaged. Raise your arms out to the sides until they are parallel to the floor. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', ARRAY['Set the cable at the lowest position and stand side-on to it.', 'Grab the handle with the outside hand and let your arm hang by your thigh.', 'Stand tall with a slight bend in your elbow and brace your midline.', 'Raise your arm out to the side until your hand reaches shoulder height.', 'Pause briefly without shrugging your shoulder.', 'Lower the handle back down with control to the start position.']::text[], 'Exhale as you raise the handle to the side, and inhale as you lower it back down.', ARRAY['Shrugging the shoulder up toward the ear', 'Swinging the torso to lift the handle', 'Turning the raise into a front lift', 'Lifting the hand far above shoulder height']::text[], 'beginner'::difficulty_level, 'deltoids', ARRAY['traps', 'triceps']::text[], ARRAY['cable']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/cable-lateral-raise.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/cable-lateral-raise.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('cable-lying-triceps-extension-0186', 'Cable Lying Triceps Extension', 'A lying cable triceps exercise where you bend and straighten the elbows to move a rope handle over your chest.', 'Attach a rope handle to a low pulley cable machine. Lie down on a flat bench facing up, with your head towards the cable machine. Grasp the rope handle with both hands, palms facing each other, and extend your arms straight up over your chest. Keeping your upper arms stationary, slowly lower the rope handle towards your forehead by bending your elbows. Pause for a moment at the bottom, then extend your arms back up to the starting position. Repeat for the desired number of repetitions.', ARRAY['Attach a rope handle to a low cable and place a flat bench in line with the pulley.', 'Lie face up on the bench with your head closest to the cable and hold the rope with a neutral grip.', 'Press the rope straight above your chest with your arms fully extended.', 'Keep your upper arms mostly still and bend your elbows to lower the rope toward your forehead.', 'Pause briefly when your elbows are deeply bent.', 'Straighten your elbows to return the rope to the start position above your chest.']::text[], 'Inhale as you lower the rope toward your forehead, and exhale as you straighten your elbows back to the start.', ARRAY['Letting the elbows flare wide to the sides', 'Drifting the upper arms backward and turning it into a pullover', 'Lowering the rope behind the head instead of toward the forehead', 'Bouncing out of the bottom instead of controlling the cable']::text[], 'beginner'::difficulty_level, 'triceps', ARRAY['shoulders']::text[], ARRAY['cable']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'triceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/cable-lying-triceps-extension.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/cable-lying-triceps-extension.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('cable-one-arm-curl-0190', 'Cable One Arm Curl', 'A single-arm cable biceps exercise where you curl a handle upward while keeping your elbow tucked at your side.', 'Stand facing the cable machine with your feet shoulder-width apart. Grasp the cable handle with an underhand grip, palm facing up. Keep your elbow close to your side and slowly curl your forearm up towards your shoulder. Pause for a moment at the top, then slowly lower your forearm back down to the starting position. Repeat for the desired number of repetitions.', ARRAY['Stand beside the cable machine and hold the handle in one hand with your palm facing up.', 'Step out until the cable is taut, then stand tall with your elbow tucked against your side.', 'Curl the handle upward by bending your elbow without letting your upper arm drift forward.', 'Raise the handle until your forearm is close to your biceps, then briefly squeeze your arm.', 'Lower the handle slowly until your arm is straight again while keeping tension on the cable.', 'Complete all reps on one arm, then switch sides.']::text[], 'Exhale as you curl the handle up, and inhale as you lower it back down.', ARRAY['Elbow swings forward during the curl', 'Shoulder shrugs up toward the ear', 'Torso leans back to move the weight', 'Handle drops quickly on the way down']::text[], 'beginner'::difficulty_level, 'biceps', ARRAY['forearms']::text[], ARRAY['cable']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'biceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/cable-one-arm-curl.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/cable-one-arm-curl.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('cable-one-arm-front-raise-0162', 'Cable One Arm Front Raise', 'An isolation exercise that raises the arm forward using a cable to target the front deltoid.', 'Stand facing away from a low cable, grasping the handle with one hand. Keeping your arm straight, raise it in front of you up to shoulder height, pause, then lower under control.', ARRAY['Attach handle to low pulley and stand facing away from machine.', 'Grasp handle with one hand, arm by your side.', 'With a straight arm, raise it forward to shoulder height.', 'Pause briefly at the top.', 'Lower back to the start slowly and repeat.']::text[], 'Exhale as you lift, inhale as you lower.', ARRAY['Using momentum', 'Shrugging shoulder', 'Overextending at the top']::text[], 'intermediate'::difficulty_level, 'anterior_deltoid', ARRAY['traps', 'pectoralis_major']::text[], ARRAY['cable']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'shoulders'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/cable-one-arm-forward-raise.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/cable-one-arm-forward-raise.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('cable-one-arm-lateral-pulldown-2616', 'Cable One Arm Lateral Pulldown', 'A vertical pulling exercise that targets the latissimus dorsi using a single cable handle.', 'Sit or stand at a cable station, grasp the single handle with one hand overhead. Pull the handle down to shoulder level, pausing briefly, then control the return.', ARRAY['Attach a single handle to the high cable pulley.', 'Sit or stand, arm overhead grasping the handle.', 'Stabilize your body and engage your core.', 'Pull handle down to shoulder/upper chest level.', 'Pause, then return handle slowly.']::text[], 'Exhale while pulling down, inhale while releasing.', ARRAY['Arching back excessively', 'Letting shoulder roll forward', 'Using momentum']::text[], 'intermediate'::difficulty_level, 'lats', ARRAY['biceps', 'rhomboids']::text[], ARRAY['cable']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/cable-one-arm-lateral-pulldown.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/cable-one-arm-lateral-pulldown.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('cable-one-arm-lateral-raise-0192', 'Cable One Arm Lateral Raise', 'A single-arm shoulder isolation exercise using a cable to lift the arm out to the side and target the lateral delts.', 'Stand with your feet shoulder-width apart, facing the cable machine. Hold the cable handle with one hand, palm facing down, and stand far enough away from the machine so that there is tension on the cable. Keep your arm straight and slowly raise it out to the side until it is parallel to the ground. Pause for a moment at the top, then slowly lower your arm back down to the starting position. Repeat for the desired number of repetitions, then switch sides.', ARRAY['Stand sideways to the cable machine and grasp the handle with the outside hand.', 'Step away until the cable is taut, with your arm down by your side and a slight bend in your elbow.', 'Brace your torso and keep your shoulders level.', 'Raise your arm out to the side until your hand reaches about shoulder height.', 'Pause briefly without shrugging your shoulder.', 'Lower the handle back down with control to the starting position.', 'Complete the reps on one side, then switch arms.']::text[], 'Exhale as you raise your arm to the side, and inhale as you lower it back down under control.', ARRAY['Shrugging the working shoulder toward the ear', 'Swinging the torso to start the rep', 'Turning the raise into a front raise', 'Lifting the hand far above shoulder height']::text[], 'beginner'::difficulty_level, 'deltoids', ARRAY['traps', 'triceps']::text[], ARRAY['cable']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/cable-one-arm-lateral-raise.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/cable-one-arm-lateral-raise.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('cable-one-arm-twisting-seated-row-0861', 'Cable One-Arm Twisting Seated Row', 'A unilateral cable row variation adding torso rotation to activate both the lats and core.', 'Sit at a cable row station and grasp the handle with one hand. As you row the handle towards your torso, rotate your upper body toward the working side, then reverse the rotation as you extend your arm forward.', ARRAY['Sit on the cable row bench and grasp a single handle with one hand.', 'Keep back straight and feet planted on the platform.', 'Pull the handle toward your torso while rotating your shoulder and upper body toward the working side.', 'Pause and squeeze your back muscles at contraction.', 'Slowly return arm and torso to the starting position with control.']::text[], 'Exhale as you row and rotate, inhale as you extend and return.', ARRAY['Over-rotating', 'Using momentum', 'Shrugging the shoulder']::text[], 'intermediate'::difficulty_level, 'lats', ARRAY['obliques', 'rhomboids', 'biceps', 'posterior_deltoid']::text[], ARRAY['cable']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/cable-one-arm-twisting-seated-row.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/cable-one-arm-twisting-seated-row.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
