INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('cable-pulldown-0198', 'Cable Pulldown', 'A seated cable back exercise where you pull a bar from overhead to your upper chest to train the lats and upper arms.', 'Adjust the cable pulldown machine so that the seat is at a comfortable height and the knee pad is secured. Sit on the seat with your back straight and your feet flat on the ground. Grasp the cable bar with an overhand grip, slightly wider than shoulder-width apart. Lean back slightly and engage your core. Pull the cable bar down towards your chest, squeezing your shoulder blades together. Pause for a moment at the bottom of the movement, then slowly release the bar back to the starting position. Repeat for the desired number of repetitions.', ARRAY['Adjust the seat and knee pad so your thighs are held down and you can reach the bar overhead.', 'Sit tall with your feet flat, grab the bar with an overhand grip just outside shoulder width, and straighten your arms.', 'Lean back slightly and pull your shoulders down away from your ears.', 'Drive your elbows down and pull the bar to the top of your chest.', 'Pause briefly while keeping your chest lifted and your torso still.', 'Slowly straighten your arms and let the bar rise under control to the start position.']::text[], 'Inhale as the bar rises, and exhale as you pull the bar down to your upper chest.', ARRAY['Pulling the bar behind the neck', 'Swinging the torso backward to start the rep', 'Letting the shoulders shrug up at the top', 'Stopping short and not fully straightening the arms']::text[], 'beginner'::difficulty_level, 'lats', ARRAY['biceps', 'forearms']::text[], ARRAY['cable']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/cable-pulldown.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/cable-pulldown.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
