INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('cable-rear-delt-row-with-rope-0203', 'Cable Rear Delt Row (with rope)', 'A cable rowing variation with a rope that targets the rear delts by pulling the elbows out and back.', 'Attach a rope handle to a low pulley cable machine. Stand facing the machine with your feet shoulder-width apart. Grasp the rope handle with an overhand grip, palms facing each other. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Keep your elbows slightly bent and pull the rope towards your chest, squeezing your shoulder blades together. Pause for a moment at the top of the movement, then slowly release the tension and return to the starting position. Repeat for the desired number of repetitions.', ARRAY['Attach a rope to a low cable pulley and stand facing the machine.', 'Grab the rope with both hands, step back to create tension, and set your feet about hip-width apart.', 'Soften your knees and hinge forward slightly with a flat back and arms extended in front of you.', 'Lead with your elbows and row the rope up toward your upper chest while letting the rope ends separate.', 'Pause briefly as your elbows travel out and back and your shoulder blades squeeze together.', 'Lower the rope under control until your arms are extended again without rounding your shoulders.']::text[], 'Inhale as you lower the rope forward, and exhale as you row the rope toward your upper chest.', ARRAY['Standing fully upright and turning it into a regular cable row', 'Shrugging the shoulders up toward the ears during the pull', 'Pulling mostly with the hands and curling the rope in', 'Rounding the upper back as the rope returns forward']::text[], 'beginner'::difficulty_level, 'deltoids', ARRAY['traps', 'rhomboids', 'biceps']::text[], ARRAY['cable']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/cable-rear-delt-row-with-rope.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/cable-rear-delt-row-with-rope.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
