INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('cable-rope-overhead-triceps-extension-0194', 'Cable Rope Overhead Triceps Extension', 'An isolation exercise using a rope attachment on a high pulley to target the triceps overhead.', 'Stand or kneel with your back to the high pulley, grasping the rope with both hands. Lean forward slightly, extend your elbows to press the rope forward/upward, then return to start under control.', ARRAY['Attach a rope to a high pulley.', 'Stand (or kneel) with back facing the machine.', 'Grasp rope, step forward, and lean slightly.', 'Keep upper arms still, extend elbows bringing rope forward/upward.', 'Return to starting position slowly.']::text[], 'Exhale as you extend, inhale as you bend elbows.', ARRAY['Moving upper arms', 'Flaring elbows', 'Arching or swinging back']::text[], 'intermediate'::difficulty_level, 'triceps', ARRAY['deltoids', 'forearms']::text[], ARRAY['cable']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'triceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/cable-rope-high-pulley-overhead-triceps-extension.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/cable-rope-high-pulley-overhead-triceps-extension.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
