INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('cable-rope-triceps-pushdown-0200', 'Cable Rope Triceps Pushdown', 'A cable isolation exercise targeting the triceps by pressing a rope attachment downward.', 'Stand facing a cable stack with a rope attached to the high pulley. Grasp the rope with both hands, elbows at your sides, and push the rope downward by extending your arms. Control the movement back to the starting position for each rep.', ARRAY['Attach a rope to the high pulley and stand facing the machine.', 'Grab the rope with both hands, thumbs facing inward.', 'Keep elbows tucked at your sides and lean slightly forward.', 'Extend your arms down, splitting the rope at the bottom.', 'Slowly return to the start without letting elbows flare out.']::text[], 'Exhale as you push down, inhale as you return.', ARRAY['Flaring elbows', 'Using momentum', 'Not fully extending arms']::text[], 'beginner'::difficulty_level, 'triceps', ARRAY['anconeus', 'forearms']::text[], ARRAY['cable']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'triceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/cable-pushdown-rope-attachment.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/cable-pushdown-rope-attachment.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('cable-seated-high-row-v-bar-0213', 'Cable Seated High Row (V-bar)', 'A seated cable row using a V-bar handle, pulling toward the upper torso to train the lats, upper back, and biceps.', 'Sit on the cable machine with your feet flat on the floor and your knees slightly bent. Grasp the v-bar attachment with an overhand grip, palms facing each other, and your hands shoulder-width apart. Keep your back straight and lean slightly forward from the hips. Pull the v-bar towards your torso by retracting your shoulder blades and squeezing your back muscles. Pause for a moment at the peak of the contraction, then slowly release the tension and return to the starting position. Repeat for the desired number of repetitions.', ARRAY['Sit at the cable row station facing the stack and grasp the V-bar handle with a neutral grip.', 'Plant your feet, soften your knees, and sit tall with your chest up and arms extended.', 'Brace your torso and pull your shoulder blades back and down.', 'Drive your elbows back and out slightly as you row the handle toward your upper stomach or lower chest.', 'Pause briefly with the handle close to your torso and your shoulders pulled back.', 'Extend your arms forward under control until your shoulders are stretched, then repeat.']::text[], 'Inhale as you extend your arms forward, and exhale as you row the handle toward your torso.', ARRAY['Rounding the lower back as the handle moves forward', 'Leaning far back and using body swing to pull', 'Shrugging the shoulders up toward the ears', 'Pulling with the arms only and not moving the shoulder blades']::text[], 'beginner'::difficulty_level, 'lats', ARRAY['biceps', 'rhomboids', 'posterior_deltoid']::text[], ARRAY['cable']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/cable-seated-high-row-v-bar.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/cable-seated-high-row-v-bar.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
