INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('cable-standing-crunch-0226', 'Cable Standing Crunch', 'A standing cable ab exercise where you curl your torso downward against a high pulley to train the abs and obliques.', 'Attach a cable handle to a high pulley and stand facing away from the machine. Hold the handle with both hands and place it behind your head, keeping your elbows bent. Stand with your feet shoulder-width apart and your knees slightly bent. Keeping your abs engaged, exhale and crunch your torso down towards your knees, bringing your elbows towards your thighs. Pause for a moment at the bottom of the movement, then slowly return to the starting position. Repeat for the desired number of repetitions.', ARRAY['Set a cable at the high pulley and stand facing away from the machine.', 'Hold the attachment by the sides of your head with both hands and bend your knees slightly.', 'Brace your midsection and keep your hips mostly still.', 'Curl your ribcage down toward your pelvis, bringing your elbows toward your thighs.', 'Pause briefly in the bottom position and squeeze your abs.', 'Slowly uncurl your torso back to the start without letting the weight stack slam.']::text[], 'Inhale at the top, exhale as you curl down, and inhale again as you return under control.', ARRAY['Hinging forward at the hips instead of curling the spine', 'Pulling the attachment down with the arms', 'Standing too upright and barely moving the torso', 'Letting the weight yank the torso back up']::text[], 'beginner'::difficulty_level, 'abdominals', ARRAY['obliques']::text[], ARRAY['cable']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/cable-standing-crunch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/cable-standing-crunch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('cable-standing-fly-1269', 'Cable Standing Fly', 'A cable isolation exercise for the chest, performed standing and moving arms in a hugging motion.', 'Stand between two cable stacks, grab the D-handles, and take a step forward. With a slight bend in elbows, bring the handles together in front of the chest, then slowly return to the starting position.', ARRAY['Attach handles to both high pulleys.', 'Stand centered between pulleys, grasp handles in each hand.', 'Step forward into a staggered stance, arms outstretched.', 'With elbows slightly bent, bring handles together in front of chest.', 'Return slowly to starting position, feeling the stretch in the chest.']::text[], 'Exhale as you bring hands together, inhale as you return.', ARRAY['Over-extending arms', 'Letting elbows lock', 'Rounding the back']::text[], 'beginner'::difficulty_level, 'pectoralis_major', ARRAY['anterior_deltoid', 'biceps']::text[], ARRAY['cable']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'chest'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/cable-standing-fly-crossover-fly.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/cable-standing-fly-crossover-fly.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('cable-standing-inner-curl-0229', 'Cable Standing Inner Curl', 'A single-arm cable biceps curl done standing with an underhand grip to train elbow flexion under constant tension.', 'Stand facing a cable machine with your feet shoulder-width apart. Grasp the cable handle with an underhand grip, palms facing up. Keep your elbows close to your sides and your upper arms stationary. Exhale and curl the cable handle towards your shoulders, contracting your biceps. Pause for a moment at the top of the movement, squeezing your biceps. Inhale and slowly lower the cable handle back to the starting position. Repeat for the desired number of repetitions.', ARRAY['Set a cable handle to the lowest position and stand facing the machine.', 'Grab the handle with one hand using an underhand grip and let your arm hang straight by your side.', 'Step back until the cable is taut, then stand tall with your feet about hip-width apart.', 'Keep your elbow pinned near your side and curl the handle up toward your shoulder.', 'Squeeze your biceps at the top without letting your upper arm drift forward.', 'Lower the handle slowly until your arm is straight again, then repeat before switching sides.']::text[], 'Exhale as you curl the handle up, and inhale as you lower it back down.', ARRAY['Elbow drifts forward during the curl', 'Torso rocks back to move the weight', 'Wrist bends excessively instead of staying neutral', 'Letting the handle drop quickly on the way down']::text[], 'beginner'::difficulty_level, 'biceps', ARRAY['forearms']::text[], ARRAY['cable']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'biceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/cable-standing-inner-curl.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/cable-standing-inner-curl.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('cable-standing-lift-0230', 'Cable Standing Lift', 'A standing cable core exercise that lifts the handle diagonally across the body to train the abs and obliques.', 'Stand facing the cable machine with your feet shoulder-width apart. Hold the cable handle with both hands and position it at waist height. Engage your core and maintain a straight back throughout the exercise. Keeping your arms straight, exhale and lift the cable handle up towards your opposite shoulder, rotating your torso. Pause for a moment at the top, then inhale and slowly lower the cable handle back to the starting position. Repeat for the desired number of repetitions, then switch sides.', ARRAY['Set the cable handle to a low position and stand side-on to the machine with your feet about shoulder-width apart.', 'Hold the handle with both hands near the hip closest to the machine and straighten your arms with a soft bend in the elbows.', 'Brace your core and turn your chest slightly toward the handle without rounding your back.', 'Pull the handle diagonally up and across your body toward the opposite shoulder by rotating your torso and lifting your arms together.', 'Pause briefly at the top with your hips mostly facing forward and your arms extended.', 'Lower the handle back along the same diagonal path to the starting hip under control.', 'Complete all reps on one side, then turn around and repeat on the other side.']::text[], 'Inhale at the start, exhale as you lift and rotate across the body, then inhale as you return under control.', ARRAY['Bending the elbows and turning it into an arm pull', 'Twisting the knees inward instead of rotating the torso', 'Leaning back or arching the lower back at the top', 'Letting the weight snap back down without control']::text[], 'beginner'::difficulty_level, 'abdominals', ARRAY['obliques', 'lower_back']::text[], ARRAY['cable']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/cable-standing-lift.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/cable-standing-lift.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('cable-standing-one-arm-triceps-extension-0231', 'Cable Standing One Arm Triceps Extension', 'A single-arm cable triceps isolation exercise done standing, extending the elbow while keeping the upper arm fixed.', 'Stand with your feet shoulder-width apart, facing the cable machine. Hold the cable handle with your right hand, palm facing down, and position your arm so that it is fully extended and parallel to the ground. Keep your elbow stationary and close to your body. Slowly bend your elbow, lowering the cable handle towards the back of your head. Pause for a moment at the bottom of the movement, then extend your arm back to the starting position. Repeat for the desired number of repetitions, then switch sides and perform the exercise with your left arm.', ARRAY['Stand side-on to the cable machine and grasp the handle with one hand.', 'Step away until the cable is taut, then raise your upper arm so it stays roughly parallel to the floor.', 'Bend your elbow to bring the handle toward the side of your head while keeping your upper arm still.', 'Extend your elbow to press the handle away until your arm is straight.', 'Pause briefly with your triceps tight, then return under control.', 'Complete all reps on one side, then switch arms.']::text[], 'Inhale as you bend your elbow and bring the handle in; exhale as you straighten your arm.', ARRAY['Letting the elbow drift up and down during the rep', 'Turning the torso to help move the handle', 'Dropping the upper arm instead of keeping it level', 'Using momentum and snapping the cable back']::text[], 'beginner'::difficulty_level, 'triceps', ARRAY['shoulders']::text[], ARRAY['cable']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'triceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/cable-standing-one-arm-triceps-extension.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/cable-standing-one-arm-triceps-extension.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
