INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('cable-straight-arm-pulldown-0238', 'Cable Straight Arm Pulldown', 'A cable lat exercise where you pull a straight bar from shoulder height down to your thighs with mostly straight arms.', 'Attach a straight bar to the high pulley of a cable machine. Stand facing the machine with your feet shoulder-width apart. Grasp the bar with an overhand grip, keeping your arms straight and your palms facing down. Engage your lats and pull the bar down towards your thighs, keeping your arms straight throughout the movement. Pause for a moment at the bottom, then slowly return the bar to the starting position. Repeat for the desired number of repetitions.', ARRAY['Attach a straight bar to a high cable pulley and face the machine.', 'Grab the bar with an overhand grip, step back slightly, and hinge forward a little at the hips.', 'Start with your arms straight in front of you at shoulder height and your torso braced.', 'Pull the bar down in a wide arc toward your thighs without bending your elbows.', 'Squeeze your lats at the bottom with the bar close to your hips.', 'Raise the bar back up slowly to shoulder height while keeping your arms long and your torso still.']::text[], 'Inhale as the bar rises to the start, and exhale as you pull it down toward your thighs.', ARRAY['Bending the elbows and turning it into a triceps pressdown', 'Leaning back and using body swing to move the bar', 'Shrugging the shoulders up toward the ears', 'Letting the bar drift away from the body at the bottom']::text[], 'beginner'::difficulty_level, 'lats', ARRAY['shoulders', 'biceps']::text[], ARRAY['cable']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/cable-straight-arm-pulldown.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/cable-straight-arm-pulldown.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
