INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('cable-triceps-pushdown-1723', 'Cable Triceps Pushdown', 'An isolation cable exercise targeting the triceps by extending the arm downward against resistance.', 'Stand at a cable station with a rope or bar attached to a high pulley. Grasp the attachment with both hands, elbows at your sides, and push it downward, fully extending your arms before returning.', ARRAY['Stand facing the cable stack with attachment at high position.', 'Grip the bar or rope with both hands.', 'Keep elbows tight to your body.', 'Push the attachment down until arms are fully extended.', 'Return slowly to starting position.']::text[], 'Exhale as you push down, inhale as you return up.', ARRAY['Using too much weight', 'Letting elbows flare out', 'Leaning over the bar']::text[], 'beginner'::difficulty_level, 'triceps', ARRAY['anconeus', 'forearms']::text[], ARRAY['cable']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'triceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/cable-triceps-pushdown.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/cable-triceps-pushdown.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
