INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('cable-twist-up-down-0862', 'Cable Twist (up-down)', 'A standing cable rotation that trains the obliques by twisting the torso diagonally across the body.', 'Stand with your feet shoulder-width apart, facing the cable machine. Hold the cable handle with both hands in front of your chest, keeping your arms slightly bent. Engage your core and slowly rotate your torso to one side, keeping your hips and legs stable. Pause for a moment at the end of the rotation, then slowly return to the starting position. Repeat the rotation to the opposite side. Continue alternating sides for the desired number of repetitions.', ARRAY['Set the cable handle at about shoulder height and stand sideways to the machine with feet hip-width apart.', 'Grab the handle with both hands and extend your arms in front of your chest with a soft bend in your elbows.', 'Brace your core and rotate your torso away from the machine while guiding the handle diagonally down across your body.', 'Keep your hips mostly still and finish with your hands near the outside of your opposite hip.', 'Control the handle back to the start, then repeat all reps before switching sides or reverse the path to move from low to high.']::text[], 'Exhale as you rotate and pull the handle across your body; inhale as you return under control.', ARRAY['Turning the hips and feet with the cable', 'Bending and straightening the elbows to move the weight', 'Letting the cable yank the torso back', 'Shrugging the shoulders toward the ears']::text[], 'beginner'::difficulty_level, 'abdominals', ARRAY['obliques', 'lower_back']::text[], ARRAY['cable']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/cable-twist-up-down.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/cable-twist-up-down.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
