INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('calf-stretch-with-rope-1378', 'Calf Stretch with Rope', 'A static stretch for the calf muscles using a rope or strap to pull the foot into dorsiflexion.', 'Sit on the floor with your legs extended. Loop a rope or band around your foot, keep your knee straight, and gently pull your toes toward you to stretch your calf.', ARRAY['Sit on the floor with one leg extended.', 'Loop a rope or band around the ball of your foot.', 'Hold ends of rope and gently pull your foot toward you.', 'Keep knee straight for a deeper stretch.', 'Hold the stretch and then switch legs.']::text[], 'Breathe deeply and relax throughout the stretch.', ARRAY['Bending the knee', 'Jerking the rope', 'Holding breath']::text[], 'beginner'::difficulty_level, 'calves', '{}'::text[], ARRAY['band']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-calf-stretch-with-rope.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-calf-stretch-with-rope.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
