INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('calf-stretch-with-strap-1599', 'Calf Stretch with Strap', 'A seated stretch using a strap or resistance band to elongate the calf muscles.', 'Sit on the floor with one leg extended and loop a strap around the ball of your foot. Gently pull the strap towards you while keeping your knee straight, feeling a stretch along the back of your lower leg.', ARRAY['Sit with legs extended on the floor.', 'Loop a strap around the ball of one foot.', 'Hold strap ends and gently pull foot towards you.', 'Keep the knee straight and hold for desired time.', 'Switch sides and repeat.']::text[], 'Breathe deeply and steadily throughout stretch; exhale gently as you deepen the stretch.', ARRAY['Bending knee', 'Pulling too hard', 'Letting back round']::text[], 'beginner'::difficulty_level, 'calves', ARRAY['soleus']::text[], ARRAY['band']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-calf-stretch-with-strap.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-calf-stretch-with-strap.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
