INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('cambered-bar-lying-row-0248', 'Cambered Bar Lying Row', 'A chest-supported barbell row performed lying face down on a bench to train the upper back with minimal body English.', 'Set up a barbell on the floor and lie face down on a bench with your chest just off the edge. Reach down and grab the barbell with an overhand grip, slightly wider than shoulder-width apart. With your legs straight and feet on the ground, lift the barbell off the floor by extending your arms. Pull the barbell towards your chest, squeezing your shoulder blades together. Lower the barbell back down to the starting position and repeat for the desired number of repetitions.', ARRAY['Place a barbell on the floor under the end of a flat bench and lie face down so your chest is supported with your arms hanging straight down.', 'Plant your feet on the floor, brace your midsection, and grab the bar with an overhand grip slightly wider than shoulder width.', 'Lift the bar clear of the floor and let it hang directly below your shoulders with your neck neutral.', 'Pull the bar up toward the underside of the bench or lower chest by driving your elbows back.', 'Pause briefly at the top and squeeze your shoulder blades together.', 'Lower the bar under control until your arms are straight and the bar returns just above the floor.']::text[], 'Inhale as you lower the bar and exhale as you pull it up toward your chest.', ARRAY['Lifting the chest off the bench to move the bar', 'Shrugging the shoulders up toward the ears', 'Yanking the bar off the floor with momentum', 'Flaring the elbows straight out to the sides']::text[], 'intermediate'::difficulty_level, 'upper_back', ARRAY['biceps', 'forearms']::text[], ARRAY['barbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/cambered-bar-lying-row.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/cambered-bar-lying-row.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
