INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('cardio-exercise-drv-cardio-exercises', 'Cardio Exercise', 'Any aerobic physical activity aimed at increasing heart rate and cardiovascular health.', 'Choose a form of movement such as jogging, jumping jacks, or burpees. Perform continuously at a moderate to vigorous intensity for the desired time or repetitions, maintaining proper posture and consistent breathing.', ARRAY['Select a cardio activity (running, jumping jacks, etc).', 'Warm up for 3-5 minutes.', 'Perform the chosen activity at a sustainable pace.', 'Maintain movement for set time or rounds.', 'Cool down and stretch afterwards.']::text[], 'Breathe rhythmically; exhale on exertion, inhale during lower intensity.', ARRAY['Overexerting too soon', 'Neglecting form', 'Ignoring proper warm-up or cool-down']::text[], 'beginner'::difficulty_level, 'cardiovascular_system', ARRAY['varies_by_movement']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/cardio-exercises.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/cardio-exercises.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
