INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('cardio-machine-exercise-drv-cardio-exercises-machine', 'Cardio Machine Exercise', 'Any sustained aerobic activity using a cardio machine to increase heart rate and endurance.', 'Select an appropriate cardio machine, adjust resistance and settings for your fitness level, and perform steady-state or interval training maintaining proper form. Focus on continuous movement and controlled breathing for the session.', ARRAY['Choose your preferred cardio machine (treadmill, bike, etc).', 'Adjust resistance, incline, and settings as desired.', 'Begin with a brief warm-up.', 'Perform cardio at steady or variable intensity.', 'Cool down after session.']::text[], 'Breathe rhythmically according to intensity; exhale during exertion, inhale during recovery.', ARRAY['Slouching or poor posture', 'Using excessive resistance or speed', 'Neglecting warm-up or cool-down']::text[], 'beginner'::difficulty_level, 'cardiovascular_system', ARRAY['varies_by_machine']::text[], ARRAY['machine']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/cardio-exercises-machine.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/cardio-exercises-machine.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
