INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('cardio-machine-workouts-drv-cardio-exercises-machines', 'Cardio Machine Workouts', 'Cardio exercises on machines like treadmills, bikes, ellipticals, or rowers improve cardiovascular fitness and endurance.', 'Choose a cardio machine such as a treadmill, stationary bike, elliptical, or rowing machine. Adjust the settings for your comfort and fitness level. Begin the workout, maintaining steady pace and form as you monitor your exertion and duration.', ARRAY['Select a cardio machine suitable for your fitness level.', 'Adjust settings such as resistance, speed, and incline as desired.', 'Begin movement, focusing on steady pace and good posture.', 'Continue for your planned duration, monitoring intensity.', 'Cool down gradually and safely exit the machine.']::text[], 'Breathe steadily throughout the workout.', ARRAY['Poor posture', 'Jumping on or off quickly', 'Overexerting too quickly']::text[], 'beginner'::difficulty_level, 'cardiovascular_system', ARRAY['varies_by_machine_legs_glutes_arms_']::text[], ARRAY['machine']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/cardio-exercises-machines.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/cardio-exercises-machines.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('chest-dips-drv-chest-dips', 'Chest Dips', 'A compound bodyweight exercise performed on parallel bars to target the chest, shoulders, and triceps.', 'Grasp parallel bars and lift yourself to starting position with arms locked. Lean the torso slightly forward and lower your body by bending the elbows until your upper arms are parallel to the floor. Push yourself back to the start, emphasizing the chest contraction.', ARRAY['Grip parallel bars and lift to start.', 'Lean torso forward and bend elbows.', 'Lower until upper arms are parallel to floor.', 'Pause at the bottom, feeling the stretch.', 'Push up through palms, returning to start.']::text[], 'Inhale as you lower, exhale as you press up.', ARRAY['Staying too upright (triceps focus)', 'Going too deep', 'Flaring elbows excessively']::text[], 'intermediate'::difficulty_level, 'pectoralis_major', ARRAY['triceps', 'anterior_deltoid']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'chest'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/chest-dips.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/chest-dips.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
