INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('chest-lift-with-rotation-drv-chest-lift-with-rotation', 'Chest Lift with Rotation', 'An abdominal exercise that combines a chest lift with torso rotation to target the obliques.', 'Lie on your back with knees bent and feet flat. Engage your core, lift your chest off the mat while simultaneously rotating your torso to one side, then return to start. Alternate rotations with each rep.', ARRAY['Lie on your back, knees bent, feet flat on floor.', 'Place hands behind head, elbows wide.', 'Engage core and lift head, neck, and shoulders off mat.', 'Rotate torso to one side while lifting.', 'Return to center and lower down; repeat on alternate side.']::text[], 'Exhale as you lift and rotate, inhale as you lower.', ARRAY['Pulling on neck', 'Using arms to assist', 'Lifting too high', 'Not engaging core']::text[], 'beginner'::difficulty_level, 'rectus_abdominis', ARRAY['obliques', 'hip_flexors']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/chest-lift-with-rotation.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/chest-lift-with-rotation.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
