INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('chin-to-chest-stretch-drv-stretching-chin-to-chest-stretch', 'Chin-to-Chest Stretch', 'A gentle static stretch to release tension in the neck flexors by tilting the chin toward the chest.', 'Sit or stand upright. Slowly lower your chin towards your chest until you feel a gentle stretch along the back of your neck, holding the position for 15-30 seconds before releasing.', ARRAY['Sit or stand with a straight back.', 'Gently lower your chin toward your chest.', 'Relax your shoulders and feel the stretch along your neck.', 'Hold the position for 15-30 seconds.', 'Slowly return to neutral.']::text[], 'Breathe deeply and evenly throughout the stretch.', ARRAY['Bouncing the stretch', 'Tensing shoulders', 'Overstretching the neck']::text[], 'beginner'::difficulty_level, 'neck_flexors', ARRAY['traps']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'shoulders'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-chin-to-chest-stretch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-chin-to-chest-stretch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('chin-ups-narrow-parallel-grip-0253', 'Chin-ups (narrow parallel grip)', 'A bodyweight vertical pull using a narrow parallel grip to train the upper back, biceps, and forearms.', 'Hang from a pull-up bar with a narrow parallel grip, palms facing towards you. Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body. Continue pulling until your chin is above the bar. Pause for a moment at the top, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', ARRAY['Grab the parallel handles with a narrow neutral grip and hang with your arms straight.', 'Cross your ankles or keep your legs still, then brace your midline and pull your shoulders down away from your ears.', 'Pull your elbows down and back to lift your chest toward your hands.', 'Keep pulling until your chin rises above your hands or handles.', 'Lower yourself under control until your arms are straight again.', 'Pause briefly at the bottom without relaxing your shoulders, then repeat.']::text[], 'Inhale at the bottom before you pull, exhale as you lift yourself up, and inhale again as you lower under control.', ARRAY['Shrugging the shoulders up toward the ears while pulling.', 'Swinging the legs or kipping to get upward.', 'Stopping short with the chin below the hands.', 'Dropping quickly to the bottom without control.']::text[], 'intermediate'::difficulty_level, 'upper_back', ARRAY['biceps', 'forearms']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/chin-ups-narrow-parallel-grip.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/chin-ups-narrow-parallel-grip.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('close-feet-leg-press-drv-close-feet-leg-press', 'Close Feet Leg Press', 'A leg press using a narrow foot placement to emphasize the quadriceps.', 'Sit in a leg press machine and place your feet hip-width or closer at the center of the platform. Press the platform away by extending your knees while keeping your back flat, then lower under control.', ARRAY['Sit in the leg press machine with feet close together on the platform.', 'Adjust seat and foot placement for comfort and safety.', 'Release safety handles and grip the handles for support.', 'Extend your knees to press the weight upward.', 'Lower platform slowly back to starting position.']::text[], 'Exhale as you press up, inhale as you lower down.', ARRAY['Letting knees collapse inward', 'Allowing heels to lift', 'Shortening range of motion']::text[], 'intermediate'::difficulty_level, 'quadriceps', ARRAY['glutes', 'adductors', 'hamstrings']::text[], ARRAY['machine']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'quads'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/close-feet-leg-press.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/close-feet-leg-press.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('close-grip-chin-up-2987', 'Close Grip Chin-Up', 'A vertical pulling exercise emphasizing the lats and biceps using a supinated close grip.', 'Hang from a pull-up bar with hands shoulder-width or closer using a supinated (underhand) grip. Pull your chin over the bar by driving your elbows down and back, then lower under control.', ARRAY['Grab the pull-up bar with an underhand grip, hands shoulder-width or slightly closer.', 'Hang at full arm extension, engage your core and back.', 'Pull your chest towards the bar by driving your elbows down and back.', 'Clear the bar with your chin, pause briefly at the top.', 'Lower yourself with control until arms are fully extended.']::text[], 'Exhale as you pull up, inhale as you lower down.', ARRAY['Using momentum', 'Flaring elbows out', 'Partial range of motion']::text[], 'intermediate'::difficulty_level, 'lats', ARRAY['biceps', 'rhomboids', 'brachialis']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/close-grip-chin-up.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/close-grip-chin-up.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('close-grip-push-up-0259', 'Close-Grip Push-Up', 'A push-up variation with hands close together to emphasize triceps involvement.', 'Assume a plank position with hands placed close together under your chest. Lower your body, keeping elbows near your sides, and push back up to the top position.', ARRAY['Begin in a plank position with hands close together under your chest.', 'Keep your core tight and body in a straight line.', 'Lower your chest toward the hands, elbows tucked by your sides.', 'Pause briefly at the bottom without touching the floor.', 'Press up to the starting position.']::text[], 'Inhale as you lower down, exhale as you push up.', ARRAY['Letting elbows flare', 'Sagging hips', 'Hands too wide']::text[], 'beginner'::difficulty_level, 'triceps', ARRAY['pectoralis_major', 'anterior_deltoid', 'core']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'triceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/close-grip-push-ups.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/close-grip-push-ups.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('commando-pull-up-drv-commando-pull-up', 'Commando Pull-Up', 'A challenging pull-up variation using a parallel grip over the bar, emphasizing back, biceps, and grip strength.', 'Grasp a pull-up bar with hands facing each other and step sideways under the bar so your head faces parallel along the bar. Pull your chest toward one side of the bar, passing your head to one side, then lower and repeat on the opposite side. Maintain strict control and avoid swinging.', ARRAY['Stand under a pull-up bar and grip it with hands facing each other, one in front of the other.', 'Hang with your body turned so the bar is directly in front of your face.', 'Brace your core and pull up, bringing your head to one side of the bar.', 'Lower yourself under control back to the starting position.', 'Repeat, bringing your head to the opposite side on the next rep.']::text[], 'Exhale as you pull up, inhale as you lower down.', ARRAY['Losing control at bottom', 'Letting body swing', 'Not clearing chin to side', 'Uneven pull strength']::text[], 'advanced'::difficulty_level, 'lats', ARRAY['biceps', 'rhomboids', 'forearms', 'obliques', 'traps']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/commando-pull-up.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/commando-pull-up.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('crossover-kneeling-hip-flexor-stretch-drv-stretching-crossover-kneeling-hip-flexor-stretch', 'Crossover Kneeling Hip Flexor Stretch', 'A kneeling stretch targeting hip flexors with the trunk rotated across the body.', 'Begin in a lunge position with your back knee on the ground and front foot forward. Gently shift your hips forward and rotate your torso away from the back leg to deepen the stretch. Hold the position and switch sides.', ARRAY['Start in a kneeling lunge with one knee on the ground and the opposite foot forward.', 'Tuck the pelvis under and shift your weight forward, feeling a stretch in the hip flexor of the rear leg.', 'Rotate your torso across the body, away from the back leg.', 'Hold for 20-30 seconds, breathing steadily.', 'Release and repeat on the other side.']::text[], 'Inhale to prepare, exhale as you rotate and deepen stretch.', ARRAY['Arching the back', 'Letting front knee collapse inward', 'Leaning forward excessively']::text[], 'beginner'::difficulty_level, 'hip_flexors', ARRAY['quadriceps', 'glutes']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-crossover-kneeling-hip-flexor-stretch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-crossover-kneeling-hip-flexor-stretch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('decline-dumbbell-bench-press-0301', 'Decline Dumbbell Bench Press', 'A chest pressing exercise performed on a 45-degree decline bench using dumbbells.', 'Secure your feet in the decline bench and lie back holding a dumbbell in each hand at chest level. Press the weights up until arms are extended, then lower them until elbows are at about 90 degrees.', ARRAY['Set a bench to a 45-degree decline angle.', 'Secure feet, lie back holding dumbbells over chest.', 'Lower dumbbells to the sides of your chest.', 'Pause at the bottom.', 'Press weights back to starting position.']::text[], 'Inhale as you lower the dumbbells, exhale as you press up.', ARRAY['Dropping elbows too low', 'Using uneven range', 'Arching lower back', 'Rushed reps']::text[], 'intermediate'::difficulty_level, 'pectoralis_major', ARRAY['triceps', 'anterior_deltoid']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'chest'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/decline-dumbbell-bench-press-45-degree.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/decline-dumbbell-bench-press-45-degree.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('decline-dumbbell-fly-0302', 'Decline Dumbbell Fly', 'A fly movement on a 45-degree decline bench to isolate the lower chest with dumbbells.', 'Lay back on a 45-degree decline bench holding a dumbbell in each hand above chest. Lower the weights in an arc to sides until a stretch is felt, then bring them back together, squeezing the chest.', ARRAY['Set bench to 45-degree decline, secure feet.', 'Lie back, arms extended above chest, slight bend in elbows.', 'Lower dumbbells in a wide arc to sides.', 'Pause at bottom for a stretch.', 'Return dumbbells to starting position, squeezing chest.']::text[], 'Inhale as you open arms, exhale as you bring weights together.', ARRAY['Straightening arms', 'Dropping dumbbells too low', 'Using too much weight', 'Rushing the rep']::text[], 'intermediate'::difficulty_level, 'pectoralis_major', ARRAY['anterior_deltoid', 'biceps']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'chest'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-decline-fly-45-degree-1.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-decline-fly-45-degree-1.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('deep-push-up-1274', 'Deep Push-Up', 'A push-up performed with hands elevated for a greater range of motion to emphasize lower chest activation.', 'Assume a push-up position with hands on raised platforms or handles to allow your chest to go deeper than standard push-ups. Lower your chest below hand level, then press back up powerfully to full arm extension.', ARRAY['Place hands on elevated surfaces shoulder-width apart.', 'Assume a plank position with tight core and straight body.', 'Lower your chest between your hands, dipping below hand level.', 'Pause at the bottom, feeling a deep stretch in the chest.', 'Push up powerfully until arms are extended.']::text[], 'Inhale as you lower down, exhale as you push up.', ARRAY['Sagging hips', 'Flaring elbows', 'Not going deep enough', 'Letting shoulders round']::text[], 'intermediate'::difficulty_level, 'pectoralis_major', ARRAY['triceps', 'anterior_deltoid', 'core']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'chest'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/deep-push-ups.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/deep-push-ups.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('donkey-calf-raise-0284', 'Donkey Calf Raise', 'A bent-over calf raise on a step that trains the calves through a full heel drop and strong lift.', 'Stand with your toes on an elevated surface, such as a step or block. Place your hands on a stable support, such as a wall or railing, for balance. Raise your heels as high as possible, lifting your body weight onto the balls of your feet. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', ARRAY['Stand with the balls of your feet on the edge of a step or block and let your heels hang off.', 'Hinge forward at your hips and place your hands on a stable support for balance.', 'Keep your knees slightly bent and lower your heels until you feel a stretch in your calves.', 'Press through the balls of your feet and lift your heels as high as you can.', 'Pause briefly at the top while staying balanced.', 'Lower your heels back down with control and repeat.']::text[], 'Inhale as you lower your heels, and exhale as you press up onto the balls of your feet.', ARRAY['Bouncing at the bottom instead of lowering under control', 'Rolling the ankles inward or outward', 'Using the hands to push the body up', 'Cutting the range short and not dropping the heels']::text[], 'beginner'::difficulty_level, 'calves', ARRAY['hamstrings', 'glutes']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/donkey-calf-raise.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/donkey-calf-raise.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-alternating-shoulder-press-0361', 'Dumbbell Alternating Shoulder Press', 'A shoulder press using dumbbells, pressing one arm at a time to target the deltoids and stabilizers.', 'Sit or stand with a dumbbell in each hand at shoulder height. Press one dumbbell overhead while keeping the other stationary, then alternate arms for each repetition.', ARRAY['Hold dumbbells at shoulder level, palms facing forward.', 'Brace your core and press one dumbbell overhead until arm is fully extended.', 'Lower to shoulder height as you press the opposite dumbbell overhead.', 'Continue alternating arms with each rep.', 'Maintain upright posture and avoid arching back.']::text[], 'Exhale pressing up, inhale lowering down.', ARRAY['Leaning to side', 'Pressing both at once', 'Shrugging shoulders']::text[], 'beginner'::difficulty_level, 'deltoids', ARRAY['triceps', 'upper_pectoralis', 'traps']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'shoulders'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-alternate-shoulder-press.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-alternate-shoulder-press.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
