INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-arnold-press-2137', 'Dumbbell Arnold Press', 'A seated dumbbell shoulder press that rotates from palms-in at the bottom to palms-forward overhead.', 'Sit on a bench with back support and hold a dumbbell in each hand at shoulder level, palms facing your body and elbows bent. Press the dumbbells upward until your arms are fully extended and your palms are facing forward. Rotate your wrists as you lift, so that your palms are facing forward at the top of the movement. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', ARRAY['Sit tall on a bench with back support and plant your feet on the floor.', 'Hold a dumbbell in each hand in front of your shoulders with palms facing you and elbows bent.', 'Brace your midline and press the dumbbells upward while rotating your palms outward.', 'Finish overhead with arms straight and palms facing forward.', 'Lower the dumbbells under control while rotating your palms back toward you.', 'Return to the start with dumbbells in front of your shoulders and repeat.']::text[], 'Inhale at the bottom, exhale as you press and rotate overhead, then inhale as you lower back down.', ARRAY['Arching the lower back as the dumbbells go overhead', 'Letting the elbows flare straight out at the bottom', 'Pressing the dumbbells up without rotating the hands', 'Lowering the dumbbells too fast and losing control']::text[], 'intermediate'::difficulty_level, 'deltoids', ARRAY['triceps', 'upper_pectoralis']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-arnold-press.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-arnold-press.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
