INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-behind-the-back-wrist-curl-0364', 'Dumbbell Behind-the-Back Wrist Curl', 'A forearm isolation exercise curling a dumbbell behind the back to emphasize forearm flexors.', 'Stand holding a dumbbell behind your back with your palm facing back. Curl the dumbbell by flexing your wrist, then return to the starting position under control.', ARRAY['Stand with dumbbell held behind your back, arm straight, palm facing backward.', 'Allow the dumbbell to roll down your fingers slightly.', 'Flex your wrist to curl the dumbbell up.', 'Squeeze at the top of the movement.', 'Lower the weight back down slowly.']::text[], 'Exhale during curl, inhale lowering down.', ARRAY['Using arm instead of wrist', 'Incomplete range', 'Jerking movement']::text[], 'beginner'::difficulty_level, 'forearms', '{}'::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'triceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-behind-back-wrist-curl.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-behind-back-wrist-curl.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
