INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-bent-over-row-0293', 'Dumbbell Bent-Over Row', 'A rowing movement that targets the back muscles while bracing the core in a bent-over position.', 'Hold a dumbbell in each hand with feet shoulder-width apart, hinge at the hips while keeping your back flat. Row the weights to your sides by pulling elbows back, then lower the weights slowly.', ARRAY['Stand with feet shoulder-width apart holding dumbbells.', 'Hinge at hips, keeping back flat and chest up.', 'Let arms hang straight down, palms facing each other.', 'Pull dumbbells to your sides, elbows close to body.', 'Lower the weights under control to starting position.']::text[], 'Exhale as you row up, inhale as you lower down.', ARRAY['Rounding the back', 'Jerking the weights', 'Not fully extending arms', 'Using biceps too much']::text[], 'beginner'::difficulty_level, 'lats', ARRAY['rhomboids', 'traps', 'posterior_deltoid', 'biceps']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-bent-over-row.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-bent-over-row.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
