INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-biceps-curl-0294', 'Dumbbell Biceps Curl', 'A standing arm exercise where you curl dumbbells from your sides to your shoulders to train the biceps.', 'Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', ARRAY['Stand tall with a dumbbell in each hand, arms at your sides, and palms facing forward.', 'Brace your torso and keep your elbows close to your ribs.', 'Curl both dumbbells up toward your shoulders without letting your upper arms swing forward.', 'Pause briefly at the top and squeeze your biceps.', 'Lower the dumbbells back down under control until your arms are straight.']::text[], 'Exhale as you curl the dumbbells up, and inhale as you lower them back down.', ARRAY['Swinging the torso to start the curl', 'Letting the elbows drift forward as the weights rise', 'Using partial range and not lowering fully', 'Bending the wrists back instead of keeping them neutral']::text[], 'beginner'::difficulty_level, 'biceps', ARRAY['forearms']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'biceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-biceps-curl.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-biceps-curl.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
