INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-close-grip-press-0296', 'Dumbbell Close-Grip Press', 'A pressing movement with dumbbells held close together to emphasize triceps activation.', 'Lie on a bench holding dumbbells together above your chest, palms facing each other. Lower the weights while keeping elbows close to your sides, then press back up by extending the arms.', ARRAY['Lie flat on a bench with a dumbbell in each hand.', 'Hold dumbbells together above chest, palms in.', 'Lower dumbbells toward sternum, elbows tight to torso.', 'Pause when elbows reach 90 degrees.', 'Press dumbbells back up by extending arms.']::text[], 'Inhale as you lower the dumbbells, exhale as you press up.', ARRAY['Flaring elbows out', 'Letting dumbbells drift apart', 'Arching back excessively', 'Lowering weights too far']::text[], 'intermediate'::difficulty_level, 'triceps', ARRAY['pectoralis_major', 'anterior_deltoid']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'triceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-close-grip-press.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-close-grip-press.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-concentration-curl-0297', 'Dumbbell Concentration Curl', 'A seated single-arm biceps curl with the upper arm braced against the inner thigh to isolate the biceps.', 'Sit on a bench with your legs spread apart and a dumbbell in one hand, resting your elbow on the inside of your thigh. Fully extend your arm and hold the dumbbell with an underhand grip. Keeping your upper arm stationary, exhale and curl the weight up towards your shoulder while contracting your biceps. Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', ARRAY['Sit on a bench with your feet flat and knees apart, holding a dumbbell in one hand.', 'Lean forward slightly and brace the back of your upper arm against the inside of your same-side thigh near the knee.', 'Let your arm hang straight down with your palm facing up and your wrist neutral.', 'Curl the dumbbell toward your same-side shoulder without moving your upper arm.', 'Squeeze your biceps at the top when your forearm is nearly vertical.', 'Lower the dumbbell slowly until your elbow is fully extended, then repeat and switch sides.']::text[], 'Inhale as you lower the dumbbell and exhale as you curl it up.', ARRAY['Lifting the elbow off the thigh during the curl', 'Swinging the torso to help raise the dumbbell', 'Cutting the rep short and not fully lowering', 'Bending the wrist back instead of keeping it neutral']::text[], 'beginner'::difficulty_level, 'biceps', ARRAY['forearms']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'biceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-concentration-curl.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-concentration-curl.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-cross-body-hammer-curl-0298', 'Dumbbell Cross Body Hammer Curl', 'A dumbbell curl variation where each hand travels across the body to the opposite shoulder with a neutral grip.', 'Stand up straight with a dumbbell in each hand, palms facing your body. Keep your elbows close to your torso and your upper arms stationary. Exhale and curl the weights while contracting your biceps, bringing the dumbbells across your body towards your opposite shoulder. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', ARRAY['Stand tall holding a dumbbell in each hand at your sides with your palms facing inward.', 'Brace your torso and keep your elbows pinned close to your ribs.', 'Curl one dumbbell diagonally across your body toward the opposite shoulder without swinging.', 'Pause briefly near shoulder height while keeping your wrist straight and palm facing inward.', 'Lower the dumbbell back to your side under control.', 'Repeat on the other arm, alternating sides.']::text[], 'Exhale as you curl the dumbbell across your body, and inhale as you lower it back down.', ARRAY['Swinging the torso or leaning back to lift the dumbbell', 'Letting the elbow drift forward away from the ribs', 'Twisting the wrist so the palm turns up at the top', 'Dropping the dumbbell quickly instead of lowering with control']::text[], 'beginner'::difficulty_level, 'biceps', ARRAY['forearms']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'biceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-cross-body-hammer-curl.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-cross-body-hammer-curl.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-deadlift-0300', 'Dumbbell Deadlift', 'A hip-hinge lift with two dumbbells that trains the glutes, hamstrings, and lower back while lifting from standing to lockout.', 'Stand with your feet shoulder-width apart, toes pointing forward. Hold a dumbbell in each hand, palms facing your body, arms extended downwards. Bend at your hips and knees, lowering the dumbbells towards the ground while keeping your back straight. Push through your heels and extend your hips and knees, lifting the dumbbells back up to the starting position. Repeat for the desired number of repetitions.', ARRAY['Stand tall with your feet hip- to shoulder-width apart, holding a dumbbell in each hand in front of your thighs.', 'Brace your midsection, pull your shoulders back, and keep your arms straight.', 'Push your hips back and bend your knees slightly as you slide the dumbbells down close to your legs.', 'Lower until the dumbbells reach around mid-shin or just below your knees while keeping your back flat.', 'Drive through your feet and push your hips forward to stand back up with the dumbbells at your thighs.', 'Finish tall with your hips and knees straight, then repeat the hinge.']::text[], 'Inhale as you lower the dumbbells with control, and exhale as you drive through your feet to stand up.', ARRAY['Rounding the lower back as the dumbbells lower', 'Letting the dumbbells drift far in front of the legs', 'Squatting straight down instead of hinging the hips back', 'Locking the knees rigid or overbending them']::text[], 'beginner'::difficulty_level, 'glutes', ARRAY['hamstrings', 'lower_back']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'glutes'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-deadlift.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-deadlift.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-fly-0308', 'Dumbbell Fly', 'A lying chest isolation exercise where you open the arms wide with dumbbells, then bring them together in an arc over the chest.', 'Lie flat on a bench with a dumbbell in each hand, palms facing each other. Extend your arms straight up over your chest, with a slight bend in your elbows. Keeping a slight bend in your elbows, lower your arms out to the sides in a wide arc until you feel a stretch in your chest. Pause for a moment, then reverse the movement and bring the dumbbells back up to the starting position. Repeat for the desired number of repetitions.', ARRAY['Lie flat on a bench holding a dumbbell in each hand, and plant your feet on the floor.', 'Press the dumbbells above your chest with your palms facing each other and soften your elbows slightly.', 'Lower both arms out to the sides in a wide arc until your elbows reach about chest level.', 'Pause briefly at the bottom while keeping the same elbow bend.', 'Squeeze your chest and bring the dumbbells back together over your chest along the same arc.']::text[], 'Inhale as you lower the dumbbells out to the sides, and exhale as you bring them back together over your chest.', ARRAY['Bending and straightening the elbows like a press', 'Lowering the dumbbells too far below chest level', 'Bringing the dumbbells together by shrugging the shoulders forward', 'Dropping the arms quickly instead of controlling the arc']::text[], 'beginner'::difficulty_level, 'pectoralis_major', ARRAY['shoulders']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'chest'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-fly.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-fly.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-fly-on-exercise-ball-1277', 'Dumbbell Fly On Exercise Ball', 'A chest isolation move done on an exercise ball, lowering dumbbells in a wide arc and bringing them back together over the chest.', 'Sit on an exercise ball and hold a dumbbell in each hand. Walk your feet forward and roll your body down until your head, neck, and upper back are supported by the ball. Extend your arms straight up above your chest, palms facing each other. Bend your elbows slightly and lower your arms out to the sides in a wide arc until you feel a stretch in your chest. Pause for a moment, then reverse the movement and squeeze your chest muscles as you bring the dumbbells back to the starting position. Repeat for the desired number of repetitions.', ARRAY['Sit on the exercise ball holding a dumbbell in each hand at your thighs.', 'Walk your feet forward and roll down until your head, neck, and upper back rest on the ball, then lift your hips so your torso is level.', 'Press the dumbbells above your chest with your palms facing each other and your elbows slightly bent.', 'Lower your arms out to the sides in a wide arc while keeping the same small bend in your elbows.', 'Stop when your upper arms are roughly in line with your torso and your chest feels stretched.', 'Bring the dumbbells back together over your chest along the same arc and squeeze your chest at the top.']::text[], 'Inhale as you lower the dumbbells out to the sides, and exhale as you bring them back together over your chest.', ARRAY['Letting the hips sag below the torso', 'Turning the movement into a press by bending the elbows too much', 'Lowering the dumbbells far below chest level', 'Shrugging the shoulders up toward the ears']::text[], 'intermediate'::difficulty_level, 'pectoralis_major', ARRAY['shoulders', 'triceps']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'chest'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-fly-on-exercise-ball.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-fly-on-exercise-ball.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
