INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-front-raise-0310', 'Dumbbell Front Raise', 'A shoulder isolation exercise where you lift dumbbells straight forward from your thighs to shoulder height.', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs. Keeping your arms straight, exhale and lift the dumbbells in front of you until they are at shoulder level. Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', ARRAY['Stand tall with a dumbbell in each hand at your thighs, palms facing your legs.', 'Brace your torso and keep a soft bend in your elbows.', 'Raise both dumbbells straight in front of you until your hands reach about shoulder height.', 'Pause briefly without shrugging your shoulders.', 'Lower the dumbbells back to your thighs with control.', 'Repeat from a still, upright stance.']::text[], 'Exhale as you raise the dumbbells, and inhale as you lower them back down with control.', ARRAY['Swinging the dumbbells up with the hips or torso.', 'Lifting the weights higher than shoulder level.', 'Shrugging the shoulders toward the ears.', 'Bending the elbows more as the weights rise.']::text[], 'beginner'::difficulty_level, 'deltoids', ARRAY['biceps', 'traps']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-front-raise.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-front-raise.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
