INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-goblet-squat-1760', 'Dumbbell Goblet Squat', 'A front-loaded squat holding one dumbbell at the chest to train the quads, glutes, and legs through a controlled deep squat.', 'Stand with your feet shoulder-width apart, holding a dumbbell vertically against your chest with both hands. Keeping your chest up and core engaged, lower your body down into a squat position by pushing your hips back and bending your knees. Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go. Pause for a moment at the bottom, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', ARRAY['Stand tall with your feet about shoulder-width apart and hold one dumbbell vertically at your chest with both hands.', 'Brace your midsection and keep your elbows pointed down close to your body.', 'Sit your hips down and back while bending your knees, and lower until your thighs are parallel to the floor or slightly lower.', 'Keep the dumbbell tight to your chest and your feet flat as your knees track over your toes.', 'Drive through your whole foot to stand back up until your hips and knees are fully extended.', 'Reset your stance and repeat the next rep.']::text[], 'Inhale as you lower into the squat, and exhale as you stand back up.', ARRAY['Letting the dumbbell drift away from the chest', 'Heels lifting off the floor at the bottom', 'Knees collapsing inward during the squat', 'Folding the chest forward instead of staying upright']::text[], 'beginner'::difficulty_level, 'quadriceps', ARRAY['glutes', 'hamstrings', 'calves']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-goblet-squat.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-goblet-squat.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-hammer-grip-incline-bench-row-1330', 'Dumbbell Hammer Grip Incline Bench Row', 'A back-focused row performed chest-down on an incline bench with dumbbells and a neutral (hammer) grip.', 'Lie face down on an incline bench with a dumbbell in each hand, neutral grip. Row the weights up toward your hips, squeezing your lats, then lower with control.', ARRAY['Set an incline bench to 30-45 degrees and lie facedown with dumbbells.', 'Hold the dumbbells with palms facing each other (neutral/hammer grip).', 'Pull the dumbbells up toward your hips, elbows close to your body.', 'Pause and contract your back muscles at the top.', 'Lower the weights slowly with control.']::text[], 'Exhale pulling up, inhale lowering down.', ARRAY['Letting chest leave bench', 'Over-rowing with biceps', 'Shrugging shoulders']::text[], 'intermediate'::difficulty_level, 'lats', ARRAY['rhomboids', 'traps', 'posterior_deltoid', 'biceps']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-hammer-grip-incline-bench-row.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-hammer-grip-incline-bench-row.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
