INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-incline-bench-press-0314', 'Dumbbell Incline Bench Press', 'A pressing exercise on an incline bench using dumbbells to train the upper chest, shoulders, and triceps.', 'Set up an incline bench at a 45-degree angle. Sit on the bench with your feet flat on the ground and your back pressed firmly against the bench. Hold a dumbbell in each hand, palms facing forward, and lift them to shoulder height. Slowly lower the dumbbells to the sides of your chest, keeping your elbows at a 90-degree angle. Push the dumbbells back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', ARRAY['Set an incline bench and sit back with a dumbbell in each hand resting on your thighs.', 'Lie back on the bench and bring the dumbbells to chest level with your palms facing forward.', 'Plant your feet on the floor and position your elbows slightly below shoulder height.', 'Press the dumbbells up over your upper chest until your arms are straight.', 'Lower the dumbbells under control to the sides of your upper chest.', 'Repeat by pressing back up along the same path.']::text[], 'Inhale as you lower the dumbbells, and exhale as you press them up.', ARRAY['Flaring the elbows straight out to the sides', 'Letting the dumbbells drift toward the face', 'Bouncing the dumbbells off the chest position', 'Arching the lower back off the bench']::text[], 'intermediate'::difficulty_level, 'pectoralis_major', ARRAY['shoulders', 'triceps']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'chest'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-incline-bench-press.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-incline-bench-press.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
