INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-incline-biceps-curl-0322', 'Dumbbell Incline Biceps Curl', 'An arm isolating curl performed seated on an incline bench to maximize stretch and activation of the biceps.', 'Sit back against an incline bench, holding a dumbbell in each hand with arms hanging straight down. Keeping your upper arms stationary, curl the weights up while contracting your biceps, then lower back to the start.', ARRAY['Set the bench to a 45-60 degree incline and sit back with a dumbbell in each hand.', 'Let your arms hang fully extended at your sides, elbows near your body.', 'Curl the dumbbells up by flexing your elbows, keeping upper arms stationary.', 'Pause and squeeze your biceps at the top of the movement.', 'Lower the weights under control to the starting position.']::text[], 'Exhale as you curl up, inhale as you lower down.', ARRAY['Swinging arms for momentum', 'Elbows drifting forward', 'Partial range of motion']::text[], 'intermediate'::difficulty_level, 'biceps', ARRAY['brachialis', 'forearms']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'biceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-incline-biceps-curl.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-incline-biceps-curl.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-incline-curl-0318', 'Dumbbell Incline Curl', 'A seated biceps curl on an incline bench that trains the biceps through a long range with dumbbells.', 'Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing forward. Rest your upper arms on the incline bench and let your elbows hang down, fully extending your arms. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', ARRAY['Set an incline bench and sit back with a dumbbell in each hand.', 'Let your arms hang straight down under your shoulders with your palms facing forward.', 'Keep your upper arms still and curl the dumbbells toward your shoulders.', 'Pause briefly at the top and squeeze your biceps.', 'Lower the dumbbells slowly until your elbows are fully straight again.']::text[], 'Inhale as you lower the dumbbells and exhale as you curl them up.', ARRAY['Swinging the dumbbells to start the curl', 'Letting the elbows drift forward as the weights rise', 'Stopping short instead of fully lowering the dumbbells', 'Bending the wrists back while curling']::text[], 'beginner'::difficulty_level, 'biceps', ARRAY['forearms']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'biceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-incline-curl.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-incline-curl.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-incline-fly-0319', 'Dumbbell Incline Fly', 'A chest isolation exercise done on an incline bench by opening the arms wide with dumbbells and squeezing them back together.', 'Set an incline bench to a 45-degree angle. Sit on the bench with a dumbbell in each hand, palms facing each other. Lie back on the bench and press the dumbbells up to the starting position, directly above your chest. Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest. Pause for a moment, then squeeze your chest muscles to bring the dumbbells back up to the starting position. Repeat for the desired number of repetitions.', ARRAY['Set an incline bench and sit with a dumbbell in each hand on your thighs.', 'Lie back and press the dumbbells above your upper chest with your palms facing each other.', 'Bend your elbows slightly and keep that bend locked in.', 'Lower the dumbbells out to your sides in a wide arc until they reach chest level or a gentle chest stretch.', 'Squeeze your chest to bring the dumbbells back together over your upper chest along the same arc.', 'Stop with the dumbbells nearly touching and repeat.']::text[], 'Inhale as you lower the dumbbells out to the sides, and exhale as you bring them back together over your chest.', ARRAY['Bending and straightening the elbows like a press', 'Lowering the dumbbells far below chest level', 'Letting the dumbbells drift behind the shoulders', 'Clanging the dumbbells together at the top']::text[], 'beginner'::difficulty_level, 'pectoralis_major', ARRAY['shoulders']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'chest'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-incline-fly.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-incline-fly.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-incline-fly-on-exercise-ball-1278', 'Dumbbell Incline Fly On Exercise Ball', 'A chest isolation exercise done with dumbbells while supported on an exercise ball at an incline angle.', 'Set up an incline bench at a 45-degree angle. Sit on an exercise ball and roll forward until your upper back is resting on the incline bench. Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest. Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest. Pause for a moment, then squeeze your chest muscles to bring the dumbbells back to the starting position. Repeat for the desired number of repetitions.', ARRAY['Hold a dumbbell in each hand and position your upper back on the exercise ball so your torso is angled upward.', 'Plant your feet firmly on the floor and raise the dumbbells above your upper chest with your palms facing each other.', 'Keep a soft bend in your elbows and lower your arms out to the sides in a wide arc.', 'Stop when your elbows are roughly level with your chest and you feel your chest stretch.', 'Squeeze your chest and bring the dumbbells back up along the same arc until they meet above your chest.']::text[], 'Inhale as you lower the dumbbells out to the sides, and exhale as you bring them back together above your chest.', ARRAY['Straightening the elbows and turning the move into a press', 'Lowering the dumbbells too far below chest level', 'Bouncing the hips or letting the ball roll around', 'Bringing the dumbbells up unevenly or clanking them together']::text[], 'intermediate'::difficulty_level, 'pectoralis_major', ARRAY['shoulders']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'chest'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-incline-fly-on-exercise-ball.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-incline-fly-on-exercise-ball.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-incline-hammer-curl-0320', 'Dumbbell Incline Hammer Curl', 'A seated incline curl with a neutral grip that targets the biceps and forearms while limiting body swing.', 'Sit on an incline bench with a dumbbell in each hand, palms facing your torso and arms fully extended. Keep your back against the bench and your feet flat on the floor. While keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', ARRAY['Set an incline bench and sit back with a dumbbell in each hand.', 'Let your arms hang straight down by your sides with your palms facing each other.', 'Keep your upper arms still and curl both dumbbells toward your shoulders.', 'Stop when your forearms are nearly vertical and squeeze your biceps.', 'Lower the dumbbells slowly until your elbows are fully straight again.', 'Repeat without swinging your torso or letting your shoulders roll forward.']::text[], 'Exhale as you curl the dumbbells up, and inhale as you lower them back down.', ARRAY['Swinging the dumbbells up with the torso', 'Letting the elbows drift forward during the curl', 'Turning the palms up at the top', 'Cutting the lowering phase short']::text[], 'beginner'::difficulty_level, 'biceps', ARRAY['forearms']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'biceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-incline-hammer-curl.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-incline-hammer-curl.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-incline-hammer-press-0321', 'Dumbbell Incline Hammer Press', 'An incline dumbbell press with a neutral grip that trains the upper chest, shoulders, and triceps.', 'Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, resting on your thighs. Lie back on the bench and position the dumbbells at shoulder level with your palms facing each other. Press the dumbbells up and away from your body until your arms are fully extended. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', ARRAY['Set an incline bench and sit with a dumbbell in each hand on your thighs.', 'Lie back on the bench and bring the dumbbells to chest height with your palms facing each other.', 'Plant your feet, pull your shoulder blades back into the bench, and keep your wrists stacked over your elbows.', 'Press the dumbbells upward until your arms are straight above your upper chest.', 'Lower the dumbbells under control until they return to chest level with your palms still facing in.', 'Repeat the press without bouncing the dumbbells off your chest or shoulders.']::text[], 'Inhale as you lower the dumbbells to chest level, and exhale as you press them up.', ARRAY['Flaring the elbows straight out to the sides', 'Letting the dumbbells drift back over the face', 'Banging the dumbbells together at the top', 'Arching the lower back and lifting the hips']::text[], 'beginner'::difficulty_level, 'pectoralis_major', ARRAY['shoulders', 'triceps']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'chest'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-incline-hammer-press.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-incline-hammer-press.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
