INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-incline-rear-lateral-raise-0326', 'Dumbbell Incline Rear Lateral Raise', 'A chest-supported dumbbell raise that targets the rear delts by lifting the arms out to the sides on an incline bench.', 'Set up an incline bench at a 45-degree angle. Sit on the bench with your chest against the backrest and hold a dumbbell in each hand. Extend your arms straight down with your palms facing each other. Keeping a slight bend in your elbows, raise your arms out to the sides until they are parallel to the ground. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', ARRAY['Set an incline bench to about 45 degrees and hold a dumbbell in each hand.', 'Lie face down with your chest supported on the bench and let your arms hang straight below your shoulders.', 'Turn your palms to face each other and keep a soft bend in your elbows.', 'Raise both arms out and slightly back until they reach shoulder height.', 'Squeeze your rear shoulders and upper back at the top.', 'Lower the dumbbells with control back to the starting position.']::text[], 'Inhale as you lower the dumbbells, and exhale as you raise them out to the sides.', ARRAY['Swinging the dumbbells up with momentum', 'Shrugging the shoulders toward the ears', 'Straightening the elbows into a wide row', 'Lifting the arms far past shoulder height']::text[], 'beginner'::difficulty_level, 'deltoids', ARRAY['traps', 'rhomboids']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-incline-rear-lateral-raise.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-incline-rear-lateral-raise.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
