INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-incline-row-0327', 'Dumbbell Incline Row', 'A chest-supported dumbbell row on an incline bench that targets the upper back while limiting body momentum.', 'Set up an incline bench at a 45-degree angle. Grab a dumbbell in each hand and sit on the bench with your chest against the incline. Extend your arms fully, allowing the dumbbells to hang straight down from your shoulders. Pull the dumbbells up towards your chest, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', ARRAY['Set an incline bench to a moderate angle and lie face down with your chest supported and feet planted on the floor.', 'Hold a dumbbell in each hand with your arms hanging straight down and palms facing each other.', 'Brace your midline and pull your shoulders down and back.', 'Row the dumbbells up toward your lower ribs by bending your elbows and driving them back.', 'Squeeze your upper back at the top without lifting your chest off the bench.', 'Lower the dumbbells under control until your arms are fully extended again.']::text[], 'Inhale as you lower the dumbbells, and exhale as you row them up toward your ribs.', ARRAY['Shrugging the shoulders up toward the ears', 'Yanking the dumbbells with body momentum', 'Flaring the elbows straight out to the sides', 'Lifting the chest off the bench at the top']::text[], 'beginner'::difficulty_level, 'upper_back', ARRAY['biceps', 'shoulders']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-incline-row.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-incline-row.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-incline-shrug-0329', 'Dumbbell Incline Shrug', 'A chest-supported shrug on an incline bench using dumbbells to target the upper traps with minimal body momentum.', 'Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand. Place your feet flat on the ground and let your arms hang straight down with your palms facing your body. Keeping your arms straight, shrug your shoulders up towards your ears as high as possible. Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position. Repeat for the desired number of repetitions.', ARRAY['Set an incline bench to about 45 degrees and sit with your chest supported against the pad.', 'Hold a dumbbell in each hand and let your arms hang straight down at your sides with your palms facing in.', 'Plant your feet firmly on the floor and keep your chest against the bench.', 'Lift your shoulders straight up toward your ears without bending your elbows.', 'Pause briefly at the top, then lower your shoulders back down under control.', 'Repeat from a dead hang each rep.']::text[], 'Inhale at the bottom, exhale as you shrug your shoulders up, then inhale as you lower back down.', ARRAY['Bending the elbows and turning the rep into a row', 'Rolling the shoulders forward or backward at the top', 'Lifting the chest off the bench to move the weight', 'Using momentum and dropping quickly between reps']::text[], 'beginner'::difficulty_level, 'traps', ARRAY['shoulders']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-incline-shrug.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-incline-shrug.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
