INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-incline-triceps-extension-0330', 'Dumbbell Incline Triceps Extension', 'A seated incline dumbbell triceps exercise where you bend and straighten the elbows to move the weights behind and above the head.', 'Sit on an incline bench with a dumbbell in each hand, palms facing inwards. Extend your arms fully overhead, keeping your elbows close to your head. Lower the dumbbells behind your head by bending your elbows, keeping your upper arms stationary. Pause for a moment, then raise the dumbbells back to the starting position by extending your arms. Repeat for the desired number of repetitions.', ARRAY['Sit back on an incline bench holding a dumbbell in each hand.', 'Press the dumbbells overhead with your palms facing each other.', 'Keep your elbows pointed up and close to your head.', 'Lower the dumbbells behind your head by bending only your elbows.', 'Pause briefly when your forearms are below parallel to the floor.', 'Straighten your elbows to raise the dumbbells back overhead.']::text[], 'Inhale as you lower the dumbbells behind your head, and exhale as you extend your elbows to bring them overhead.', ARRAY['Elbows flare wide out to the sides.', 'Upper arms drift backward and turn it into a press.', 'Lowering only a few inches behind the head.', 'Arching the low back off the bench.']::text[], 'beginner'::difficulty_level, 'triceps', ARRAY['shoulders']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'triceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-incline-triceps-extension.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-incline-triceps-extension.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
