INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-iron-cross-0332', 'Dumbbell Iron Cross', 'A shoulder isolation exercise where you raise dumbbells out to the sides to train the delts.', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides. Raise your arms out to the sides until they are parallel to the ground, forming a T shape with your body. Pause for a moment, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', ARRAY['Stand tall with a dumbbell in each hand at your sides and your feet about hip-width apart.', 'Hold a slight bend in your elbows and turn your palms toward your sides.', 'Raise both arms out to the sides until your hands reach shoulder height.', 'Pause briefly with your shoulders level and your wrists in line with your elbows.', 'Lower the dumbbells back to your sides with control.', 'Repeat without swinging your torso or bouncing the weights.']::text[], 'Inhale as you lower the dumbbells and exhale as you raise them out to the sides.', ARRAY['Swinging the torso to start each rep', 'Shrugging the shoulders toward the ears', 'Lifting the dumbbells higher than shoulder level', 'Straightening the elbows completely and locking the arms']::text[], 'beginner'::difficulty_level, 'deltoids', ARRAY['triceps', 'chest']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-iron-cross.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-iron-cross.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
