INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-kickback-0333', 'Dumbbell Kickback', 'A bent-over triceps isolation exercise where you extend dumbbells behind you while keeping the upper arms still.', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Bring your upper arms close to your sides, with your elbows bent at a 90-degree angle. Extend your arms straight back, squeezing your triceps at the top of the movement. Pause for a moment, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', ARRAY['Stand with a dumbbell in each hand and hinge forward at the hips with a flat back.', 'Bend your elbows to about 90 degrees and pin your upper arms alongside your torso.', 'Brace your torso and keep your elbows still.', 'Straighten your arms by driving the dumbbells back until your elbows are fully extended.', 'Squeeze your triceps at the back of the movement.', 'Bend your elbows under control to return to the start position.']::text[], 'Inhale as you bend the elbows to the start position, and exhale as you straighten the arms back.', ARRAY['Swinging the dumbbells with the shoulders or torso', 'Letting the elbows drift away from the ribs', 'Dropping the upper arms during the set', 'Snapping the weights down instead of lowering slowly']::text[], 'beginner'::difficulty_level, 'triceps', ARRAY['shoulders']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'triceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-kickback.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-kickback.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-lateral-raise-0334', 'Dumbbell Lateral Raise', 'A shoulder isolation exercise where you lift dumbbells out to the sides to target the lateral delts.', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body. Keep your back straight and engage your core. Raise your arms out to the sides until they are parallel to the floor, keeping a slight bend in your elbows. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', ARRAY['Stand tall with a dumbbell in each hand at your sides, palms facing in.', 'Set your shoulders down and brace your midsection.', 'Raise both arms out to the sides until your hands reach about shoulder height, keeping a soft bend in your elbows.', 'Pause briefly at the top without shrugging your shoulders.', 'Lower the dumbbells back to your sides with control.']::text[], 'Exhale as you raise the dumbbells to the sides, and inhale as you lower them back down under control.', ARRAY['Shrugging the shoulders up toward the ears', 'Swinging the torso to heave the dumbbells upward', 'Lifting the hands well above shoulder height', 'Straightening the elbows and turning it into a front swing']::text[], 'beginner'::difficulty_level, 'deltoids', ARRAY['traps']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-lateral-raise.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-lateral-raise.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-lunge-0336', 'Dumbbell Lunge', 'A lower-body exercise where you hold dumbbells and step into alternating lunges to train the glutes, quads, and legs.', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand. Take a step forward with your right foot, lowering your body into a lunge position. Keep your back straight and your chest up as you lower your body. Push through your right heel to return to the starting position. Repeat with your left leg. Alternate legs for the desired number of repetitions.', ARRAY['Stand tall with a dumbbell in each hand at your sides and your feet hip-width apart.', 'Step one foot forward far enough that both knees can bend comfortably.', 'Lower your body until your front thigh is nearly parallel to the floor and your back knee drops toward the floor.', 'Keep your torso upright and your front foot flat as you pause briefly at the bottom.', 'Push through your front heel to return to standing.', 'Repeat on the other side, alternating legs each rep.']::text[], 'Inhale as you lower into the lunge, and exhale as you push back to standing.', ARRAY['Taking too short a step so the front knee shoots far past the toes.', 'Leaning the torso forward as you lower into the lunge.', 'Letting the front heel lift off the floor.', 'Pushing off the back foot instead of driving through the front leg.']::text[], 'beginner'::difficulty_level, 'glutes', ARRAY['quadriceps', 'hamstrings', 'calves']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'glutes'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-lunge.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-lunge.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-lying-alternate-extension-1729', 'Dumbbell Lying Alternate Extension', 'A lying triceps isolation exercise where you lower one dumbbell at a time toward your forehead and extend the elbow back to the top.', 'Lie flat on a bench with a dumbbell in each hand, palms facing each other. Extend your arms straight up over your chest, keeping a slight bend in your elbows. Lower one dumbbell down towards your head, bending at the elbow, while keeping the other arm extended. Pause for a moment at the bottom, then raise the dumbbell back up to the starting position. Repeat with the other arm, alternating sides for the desired number of repetitions.', ARRAY['Lie flat on a bench holding a dumbbell in each hand, and press both arms straight up over your chest with palms facing each other.', 'Keep one arm still above your chest as you bend the other elbow and lower that dumbbell beside your forehead.', 'Stop when your forearm points down and your upper arm stays mostly vertical.', 'Straighten the bent arm to bring the dumbbell back above your chest.', 'Repeat on the other side while keeping the first arm locked out.', 'Continue alternating sides with both shoulders and head resting on the bench.']::text[], 'Inhale as you lower each dumbbell and exhale as you straighten the elbow to bring it back up.', ARRAY['Elbows flare wide as the dumbbell lowers', 'Upper arms drift backward instead of staying upright', 'The non-working arm drops or bends', 'Turning it into a press from the chest']::text[], 'beginner'::difficulty_level, 'triceps', ARRAY['shoulders']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'triceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-lying-alternate-extension.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-lying-alternate-extension.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-lying-hammer-press-0340', 'Dumbbell Lying Hammer Press', 'A flat bench dumbbell press done with a neutral grip to train the chest, triceps, and shoulders.', 'Lie flat on a bench with a dumbbell in each hand, palms facing each other and arms extended straight up. Lower the dumbbells to the sides of your chest, keeping your elbows at a 90-degree angle. Press the dumbbells back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', ARRAY['Lie flat on a bench holding a dumbbell in each hand, and press the dumbbells above your chest with your palms facing each other.', 'Plant your feet on the floor and brace your torso while keeping your wrists stacked over your elbows.', 'Lower the dumbbells under control to either side of your chest, keeping your elbows slightly tucked from your shoulders.', 'Pause briefly when your upper arms reach bench level or the dumbbells lightly touch your chest line.', 'Press the dumbbells straight up until your arms are extended above your chest, keeping the palms facing each other throughout.', 'Bring the dumbbells back together over your chest and repeat.']::text[], 'Inhale as you lower the dumbbells to your chest and exhale as you press them back up.', ARRAY['Elbows flare straight out to the sides.', 'Dumbbells drift toward the face instead of staying over the chest.', 'Wrists bend back under the dumbbells.', 'Lowering too fast and bouncing at the bottom.']::text[], 'beginner'::difficulty_level, 'pectoralis_major', ARRAY['triceps', 'shoulders']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'chest'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-lying-hammer-press.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-lying-hammer-press.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
