INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-lying-leg-curl-0343', 'Dumbbell Lying Leg Curl', 'A hamstring isolation exercise where a dumbbell is held between the feet during leg curls.', 'Lie face down on a flat bench with a dumbbell held securely between your feet. Flex your knees to bring the dumbbell up toward your glutes, then lower with control.', ARRAY['Lie face down on a bench, legs straight, dumbbell held between your feet.', 'Hold onto the bench for stability.', 'Contract your hamstrings to curl the dumbbell upward toward your glutes.', 'Pause at the top of the movement.', 'Lower the dumbbell in a controlled motion to the starting position.']::text[], 'Exhale as you curl up, inhale as you lower down.', ARRAY['Allowing hips to lift', 'Letting dumbbell slip', 'Using momentum']::text[], 'intermediate'::difficulty_level, 'hamstrings', ARRAY['gastrocnemius', 'glutes']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'hamstrings'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-lying-femoral.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-lying-femoral.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
