INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-lying-rear-delt-row-1328', 'Dumbbell Lying Rear Delt Row', 'A chest-supported dumbbell row variation that targets the rear delts and upper back by pulling the elbows out wide.', 'Lie face down on a flat bench with a dumbbell in each hand, palms facing inwards. Extend your arms straight down towards the floor, keeping a slight bend in your elbows. Engaging your back muscles, lift the dumbbells up towards your chest, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', ARRAY['Lie face down on a flat bench holding a dumbbell in each hand, with your chest supported and arms hanging straight down.', 'Set your feet firmly on the floor and turn your palms to face each other.', 'Pull your elbows out to the sides and row the dumbbells up toward your upper chest.', 'Squeeze your upper back at the top while keeping your chest on the bench.', 'Lower the dumbbells back down under control until your arms are straight again.', 'Repeat without swinging the weights or shrugging your shoulders.']::text[], 'Inhale as you lower the dumbbells, and exhale as you row them up toward your upper chest.', ARRAY['Pulling the elbows close to the ribs like a regular row', 'Shrugging the shoulders up toward the ears', 'Lifting the chest off the bench to move the weights', 'Swinging the dumbbells instead of lowering them with control']::text[], 'beginner'::difficulty_level, 'upper_back', ARRAY['shoulders', 'biceps']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-lying-rear-delt-row.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-lying-rear-delt-row.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
