INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-lying-triceps-extension-0351', 'Dumbbell Lying Triceps Extension', 'A lying dumbbell triceps exercise where you bend and straighten the elbows to lower the weights toward the forehead and press them back up.', 'Lie flat on a bench with a dumbbell in each hand, palms facing each other. Extend your arms straight up over your chest, keeping your elbows close to your body. Lower the dumbbells down towards your forehead, bending your elbows. Pause for a moment, then extend your arms back up to the starting position. Repeat for the desired number of repetitions.', ARRAY['Lie flat on a bench holding a dumbbell in each hand, and press the dumbbells above your chest with your palms facing each other.', 'Pull your shoulders down into the bench and straighten your wrists so the dumbbells stay stacked over your elbows.', 'Bend your elbows and lower the dumbbells toward the sides of your forehead while keeping your upper arms mostly still.', 'Stop when your elbows are fully bent and the dumbbells are close to your head.', 'Straighten your elbows to drive the dumbbells back to the start position above your chest.', 'Repeat each rep without letting your elbows flare wide.']::text[], 'Inhale as you lower the dumbbells toward your forehead, and exhale as you extend your elbows to raise them back up.', ARRAY['Elbows flare out wide as the dumbbells lower.', 'Upper arms drift backward or forward during the rep.', 'Dumbbells drop too low behind the head instead of beside the forehead.', 'Wrists bend back instead of staying straight.']::text[], 'beginner'::difficulty_level, 'triceps', ARRAY['shoulders']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'triceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-lying-triceps-extension.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-lying-triceps-extension.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
