INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-one-arm-lateral-raise-0355', 'Dumbbell One Arm Lateral Raise', 'A single-arm shoulder isolation exercise where you raise a dumbbell out to the side to train the lateral delts.', 'Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing your body. Keep your back straight and your core engaged throughout the exercise. Raise the dumbbell to the side, keeping your arm straight and your palm facing down. Continue lifting until your arm is parallel to the ground. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', ARRAY['Stand tall with feet about hip-width apart and hold a dumbbell at one side with a slight bend in your elbow.', 'Brace your core and keep your shoulders level as your free arm stays relaxed by your side or on your hip.', 'Lift the dumbbell out to the side until your hand reaches about shoulder height.', 'Pause briefly at the top without shrugging your shoulder toward your ear.', 'Lower the dumbbell back to your side with control.', 'Complete all reps on one arm, then switch sides.']::text[], 'Inhale as you lower the dumbbell, and exhale as you lift it out to the side.', ARRAY['Shrugging the working shoulder up toward the ear', 'Swinging the torso or leaning to start the lift', 'Raising the dumbbell higher than shoulder height', 'Locking the elbow completely straight']::text[], 'beginner'::difficulty_level, 'deltoids', ARRAY['traps', 'triceps']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-one-arm-lateral-raise.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-one-arm-lateral-raise.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-one-arm-zottman-preacher-curl-1672', 'Dumbbell One Arm Zottman Preacher Curl', 'A single-arm preacher curl variation that adds a wrist rotation to train the biceps and forearms through both the lift and lowering phase.', 'Sit on a preacher curl bench and hold a dumbbell in one hand with an underhand grip. Rest your upper arm on the preacher bench pad, allowing your arm to fully extend. Curl the dumbbell up towards your shoulder, keeping your upper arm stationary. At the top of the curl, rotate your wrist so that your palm faces up. Slowly lower the dumbbell back down to the starting position, rotating your wrist back to the starting position. Repeat for the desired number of repetitions, then switch arms.', ARRAY['Sit at a preacher bench and plant your feet on the floor.', 'Hold a dumbbell in one hand and place the back of your upper arm flat against the pad with your arm nearly straight.', 'Start with your palm facing up and curl the dumbbell toward your shoulder without lifting your upper arm off the pad.', 'Pause near the top and rotate your wrist until your palm faces down.', 'Lower the dumbbell slowly until your arm is nearly straight while keeping your palm facing down.', 'Rotate your wrist back to palm-up at the bottom and repeat before switching arms.']::text[], 'Exhale as you curl the dumbbell up, then inhale as you rotate and lower it back down.', ARRAY['Upper arm lifting off the preacher pad', 'Swinging the dumbbell instead of curling it', 'Dropping the weight quickly on the lowering phase', 'Rotating the wrist too early before reaching the top']::text[], 'intermediate'::difficulty_level, 'biceps', ARRAY['forearms']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'biceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-one-arm-zottman-preacher-curl.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-one-arm-zottman-preacher-curl.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-one-arm-triceps-extension-0306', 'Dumbbell One-Arm Triceps Extension', 'An isolation exercise for the triceps performed one arm at a time, with a dumbbell overhead.', 'Stand or sit holding a dumbbell overhead with one arm fully extended. Lower the dumbbell by bending the elbow, then extend the arm back up to starting position, keeping upper arm still.', ARRAY['Hold dumbbell in one hand, arm extended overhead.', 'Support upper arm with free hand if needed.', 'Lower dumbbell behind head by bending the elbow.', 'Pause when forearm is parallel to ground.', 'Extend arm fully to return to starting position.']::text[], 'Inhale as you lower the dumbbell, exhale as you press up.', ARRAY['Moving upper arm', 'Dropping weight too far', 'Allowing elbow to flare', 'Rushing movement']::text[], 'intermediate'::difficulty_level, 'triceps', ARRAY['anconeus', 'forearms']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'triceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-one-arm-triceps-extension.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-one-arm-triceps-extension.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-over-bench-wrist-curl-0369', 'Dumbbell Over Bench Wrist Curl', 'A seated forearm isolation exercise where the wrists curl dumbbells upward with the forearms supported on a bench.', 'Sit on a bench with your forearms resting on the bench and your palms facing up, holding a dumbbell in each hand. Allow your wrists to hang over the edge of the bench. Slowly curl your wrists upward, squeezing your forearms at the top of the movement. Pause for a moment, then slowly lower your wrists back down to the starting position. Repeat for the desired number of repetitions.', ARRAY['Sit at a bench and place your forearms on top with your palms facing up.', 'Hold a dumbbell in each hand and slide forward until your wrists hang just past the bench edge.', 'Let your hands lower to gently stretch your wrists at the bottom.', 'Curl your wrists up by lifting your knuckles toward your forearms.', 'Squeeze your forearms briefly at the top.', 'Lower the dumbbells back down under control until your wrists extend again.']::text[], 'Inhale as you lower your wrists and exhale as you curl them up.', ARRAY['Lifting the forearms off the bench during the curl.', 'Swinging the dumbbells instead of moving only the wrists.', 'Using partial range and stopping before the wrists fully lower.', 'Bending the elbows to help raise the weight.']::text[], 'beginner'::difficulty_level, 'forearms', ARRAY['biceps', 'brachialis']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'triceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-over-bench-wrist-curl.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-over-bench-wrist-curl.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-palm-rotational-bent-over-row-1329', 'Dumbbell Palm Rotational Bent Over Row', 'A bent-over dumbbell row where you rotate your palms during the pull to train the upper back, biceps, and forearms.', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip. Bend forward at the hips, keeping your back straight and your knees slightly bent. Let your arms hang straight down, palms facing your body. Engage your core and pull the dumbbells up towards your chest, keeping your elbows close to your body. As you pull the dumbbells up, rotate your palms so they face away from your body. Squeeze your shoulder blades together at the top of the movement. Slowly lower the dumbbells back down to the starting position, rotating your palms back to the starting position. Repeat for the desired number of repetitions.', ARRAY['Stand with your feet hip-width apart, holding a dumbbell in each hand with your arms straight and palms facing each other.', 'Hinge at your hips until your torso is leaned forward, soften your knees, and keep your back flat.', 'Let the dumbbells hang below your shoulders and brace your core.', 'Row both dumbbells toward your lower ribs by driving your elbows back.', 'Rotate your palms as you lift until they face more backward or away from your body at the top.', 'Pause and squeeze your upper back, then lower the dumbbells with control as you rotate your palms back to neutral.']::text[], 'Inhale at the bottom, exhale as you row and rotate the dumbbells up, then inhale as you lower them back down.', ARRAY['Rounding the lower back as you hinge forward', 'Standing up taller to swing the dumbbells', 'Shrugging the shoulders toward the ears', 'Letting the wrists curl instead of rotating the forearms']::text[], 'intermediate'::difficulty_level, 'upper_back', ARRAY['biceps', 'forearms']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-palm-rotational-bent-over-row.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-palm-rotational-bent-over-row.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-preacher-curl-over-exercise-ball-1673', 'Dumbbell Preacher Curl Over Exercise Ball', 'A single-arm biceps curl done with the upper arm braced against an exercise ball to limit cheating and isolate the elbow flexors.', 'Sit on an exercise ball with your feet flat on the ground and your back straight. Hold a dumbbell in one hand with an underhand grip, resting your elbow on the exercise ball. Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder. Pause for a moment at the top, then inhale and slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', ARRAY['Sit tall on the exercise ball with both feet flat and spread for balance.', 'Hold a dumbbell in one hand with your palm facing up and brace the back of your upper arm against the ball.', 'Let the arm straighten almost fully so the dumbbell hangs below your elbow.', 'Curl the dumbbell toward your shoulder without lifting your elbow off the ball.', 'Squeeze your biceps at the top while keeping your wrist straight.', 'Lower the dumbbell slowly until your arm is almost straight, then repeat and switch sides.']::text[], 'Inhale as you lower the dumbbell and exhale as you curl it up.', ARRAY['Elbow slides or lifts off the ball during the curl.', 'Shoulder rolls forward to help raise the dumbbell.', 'Wrist bends back or curls inward at the top.', 'Body rocks on the ball to create momentum.']::text[], 'beginner'::difficulty_level, 'biceps', ARRAY['forearms']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'biceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-preacher-curl-over-exercise-ball.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-preacher-curl-over-exercise-ball.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-pronate-grip-triceps-extension-0373', 'Dumbbell Pronate-grip Triceps Extension', 'A seated overhead triceps exercise using one dumbbell held with both hands to bend and straighten the elbows.', 'Sit on a bench or chair with your back straight and feet flat on the ground. Hold a dumbbell with both hands, palms facing down, and extend your arms straight up overhead. Keeping your upper arms close to your head and elbows pointing forward, slowly lower the dumbbell behind your head by bending your elbows. Pause for a moment, then extend your arms back up to the starting position. Repeat for the desired number of repetitions.', ARRAY['Sit tall on a bench or chair with both feet flat on the floor.', 'Hold one dumbbell with both hands by the handle using an overhand grip and press it straight overhead.', 'Bring your upper arms close to your ears and point your elbows forward.', 'Lower the dumbbell behind your head by bending only your elbows.', 'Stop when your forearms are below parallel and your upper arms stay mostly still.', 'Straighten your elbows to raise the dumbbell back to the overhead start position.']::text[], 'Inhale as you lower the dumbbell behind your head, and exhale as you straighten your elbows to lift it overhead.', ARRAY['Elbows flare wide out to the sides.', 'Upper arms drift backward and move during the rep.', 'Lower back arches as the weight goes overhead.', 'The dumbbell drops too low and bumps the upper back.']::text[], 'beginner'::difficulty_level, 'triceps', ARRAY['forearms']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'triceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-pronate-grip-triceps-extension.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-pronate-grip-triceps-extension.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
