INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-prone-incline-curl-0374', 'Dumbbell Prone Incline Curl', 'A chest-supported biceps curl on an incline bench that limits body swing and keeps tension on the arms.', 'Adjust the bench to a 45-degree incline. Lie face down on the bench with your chest and stomach resting against it. Hold a dumbbell in each hand with your palms facing down and your arms fully extended. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', ARRAY['Set an incline bench to about 45 degrees and lie face down with your chest supported.', 'Hold a dumbbell in each hand with your arms hanging straight down and palms facing forward.', 'Keep your upper arms still and curl both dumbbells up toward your shoulders.', 'Pause briefly at the top and squeeze your biceps.', 'Lower the dumbbells slowly until your arms are fully extended again.']::text[], 'Inhale as you lower the dumbbells and exhale as you curl them up.', ARRAY['Lifting the chest off the bench to swing the weights', 'Letting the elbows drift forward during the curl', 'Cutting the rep short and not fully lowering the dumbbells', 'Bending the wrists back instead of keeping them neutral']::text[], 'beginner'::difficulty_level, 'biceps', ARRAY['forearms']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'biceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-prone-incline-curl.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-prone-incline-curl.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
