INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-rear-delt-row-0377', 'Dumbbell Rear Delt Row', 'A bent-over dumbbell row variation that targets the rear delts by pulling the elbows out wide to the sides.', 'Stand with your feet shoulder-width apart and knees slightly bent. Hold a dumbbell in each hand with your palms facing your body. Bend forward at the waist, keeping your back straight and your core engaged. Extend your arms straight down towards the floor, with a slight bend in your elbows. Raise the dumbbells out to the sides, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', ARRAY['Stand with your feet hip- to shoulder-width apart, holding a dumbbell in each hand at your sides.', 'Hinge at your hips until your torso is leaned forward, soften your knees, and let the dumbbells hang below your shoulders with your palms facing each other.', 'Brace your core and keep your back flat as you pull your elbows up and out to the sides.', 'Lift until your upper arms are roughly in line with your shoulders and squeeze your upper back.', 'Lower the dumbbells under control to the start position and repeat.']::text[], 'Inhale as you lower the dumbbells, and exhale as you row them up and out to the sides.', ARRAY['Rounding the lower back as you hinge forward.', 'Shrugging the shoulders up toward the ears.', 'Pulling the dumbbells straight back close to the ribs.', 'Swinging the torso to start each rep.']::text[], 'beginner'::difficulty_level, 'deltoids', ARRAY['traps', 'rhomboids']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-rear-delt-row.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-rear-delt-row.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
