INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-seated-calf-raise-1379', 'Dumbbell Seated Calf Raise', 'A seated calf exercise using a dumbbell on the thighs to train ankle plantarflexion through a full range of motion.', 'Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your thighs. Place the balls of your feet on a raised surface such as a step or block, with your heels hanging off the edge. Hold onto the dumbbell for stability. Raise your heels as high as possible, lifting your body weight onto the balls of your feet. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', ARRAY['Sit on a bench or chair with your knees bent and place the balls of your feet on a small raised surface with your heels hanging off.', 'Set a dumbbell across the tops of your thighs just above your knees and hold it steady with both hands.', 'Let your heels drop down until you feel a stretch through your calves.', 'Press through the balls of your feet and raise your heels as high as you can.', 'Pause briefly at the top while keeping the dumbbell steady.', 'Lower your heels back down under control and repeat.']::text[], 'Inhale as you lower your heels, and exhale as you press up onto the balls of your feet.', ARRAY['Bouncing the heels at the bottom instead of lowering under control.', 'Rolling the ankles inward or outward as the heels rise.', 'Placing the dumbbell too close to the knees so it slides during the set.', 'Using a very short range of motion and not dropping the heels below the step.']::text[], 'beginner'::difficulty_level, 'calves', ARRAY['hamstrings']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-seated-calf-raise.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-seated-calf-raise.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
