INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-seated-front-raise-0392', 'Dumbbell Seated Front Raise', 'A seated shoulder isolation exercise where you lift dumbbells straight in front to shoulder height to train the front delts.', 'Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs. Keep your back straight and core engaged. Raise the dumbbells in front of you, with your palms facing down, until they are at shoulder level. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', ARRAY['Sit tall on a bench with your feet flat on the floor and a dumbbell in each hand at your sides.', 'Hold the dumbbells with your palms facing down or slightly toward each other, and brace your midsection.', 'Raise both arms straight forward until the dumbbells reach shoulder height.', 'Pause briefly at the top without leaning back or shrugging your shoulders.', 'Lower the dumbbells under control back to the starting position by your thighs.', 'Repeat each rep with the same seated posture and arm path.']::text[], 'Exhale as you raise the dumbbells, and inhale as you lower them back down under control.', ARRAY['Leaning the torso back to swing the dumbbells up', 'Raising the dumbbells above shoulder height', 'Shrugging the shoulders toward the ears', 'Dropping the weights quickly on the way down']::text[], 'beginner'::difficulty_level, 'deltoids', ARRAY['traps', 'biceps']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-seated-front-raise.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-seated-front-raise.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
