INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-seated-kickback-0394', 'Dumbbell Seated Kickback', 'A seated triceps isolation exercise where you hinge forward and extend dumbbells back by straightening the elbows.', 'Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand. Bend your knees slightly and lean forward from your hips, keeping your back straight. Bring your upper arms close to your sides and keep your elbows bent at a 90-degree angle. Extend your arms straight back, squeezing your triceps at the top of the movement. Pause for a moment, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', ARRAY['Sit on a bench holding a dumbbell in each hand with your feet flat on the floor.', 'Hinge forward from your hips and keep your back flat with your chest angled toward your thighs.', 'Pull your elbows up beside your torso and bend them to about 90 degrees.', 'Keep your upper arms still and straighten your elbows to kick the dumbbells back behind you.', 'Squeeze your triceps with your arms fully extended.', 'Bend your elbows slowly to return the dumbbells to the start position.']::text[], 'Inhale as you bend your elbows to lower the dumbbells, and exhale as you straighten your arms back.', ARRAY['Swinging the dumbbells with the shoulders', 'Letting the elbows drift away from the torso', 'Dropping the upper arms during the rep', 'Rounding the back while leaning forward']::text[], 'beginner'::difficulty_level, 'triceps', ARRAY['shoulders']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'triceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-seated-kickback.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-seated-kickback.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
