INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-seated-lateral-raise-0396', 'Dumbbell Seated Lateral Raise', 'A seated shoulder isolation exercise where you raise dumbbells out to the sides to target the delts.', 'Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs. Keep your back straight and core engaged. Raise the dumbbells to your sides with a slight bend in your elbows, until your arms are parallel to the ground. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', ARRAY['Sit upright on a bench with your feet flat on the floor and a dumbbell in each hand at your sides.', 'Set your shoulders down and keep a soft bend in your elbows.', 'Raise both arms out to your sides until the dumbbells reach about shoulder height.', 'Pause briefly at the top without shrugging your shoulders.', 'Lower the dumbbells back to your sides with control and repeat.']::text[], 'Exhale as you raise the dumbbells out to the sides, and inhale as you lower them back down.', ARRAY['Swinging the torso to start the lift', 'Shrugging the shoulders up toward the ears', 'Lifting the dumbbells higher than shoulder level', 'Straightening the elbows into a stiff arm']::text[], 'beginner'::difficulty_level, 'deltoids', ARRAY['traps', 'upper_back']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-seated-lateral-raise.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-seated-lateral-raise.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
