INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-seated-neutral-wrist-curl-0397', 'Dumbbell Seated Neutral Wrist Curl', 'A seated forearm isolation exercise where you curl dumbbells by bending at the wrists with a neutral grip.', 'Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing each other. Rest your forearms on your thighs, allowing the dumbbells to hang down. Keeping your wrists in a neutral position, curl the dumbbells up towards your shoulders. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', ARRAY['Sit on a bench with your feet flat and hold a dumbbell in each hand with your palms facing each other.', 'Rest your forearms on your thighs near your knees and let your wrists hang just past your knees.', 'Start with your wrists straight and your hands hanging down under control.', 'Curl the dumbbells upward by bending only at your wrists while keeping your forearms pressed into your thighs.', 'Squeeze briefly at the top without turning your palms up or down.', 'Lower the dumbbells slowly back to the start until your wrists are fully extended.']::text[], 'Exhale as you curl your wrists up, and inhale as you lower the dumbbells back down.', ARRAY['Lifting the forearms off the thighs to swing the dumbbells up', 'Turning the palms up or down during the curl', 'Bouncing the dumbbells at the bottom', 'Using the shoulders or elbows to help the movement']::text[], 'beginner'::difficulty_level, 'biceps', ARRAY['forearms']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'biceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-seated-neutral-wrist-curl.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-seated-neutral-wrist-curl.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
