INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-seated-preacher-curl-0402', 'Dumbbell Seated Preacher Curl', 'A seated single-arm biceps curl done against a preacher pad to isolate the elbow flexors and limit body momentum.', 'Sit on a preacher curl bench with your feet flat on the floor. Hold a dumbbell in one hand with an underhand grip, resting your upper arm against the preacher pad. Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder. Pause for a moment at the top, then inhale and slowly lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch arms.', ARRAY['Sit on the preacher bench and plant your feet flat on the floor.', 'Hold a dumbbell with your palm facing up and place the back of your upper arm firmly against the pad.', 'Start with your arm nearly straight and let the dumbbell hang just above the bottom of the pad.', 'Curl the dumbbell upward by bending your elbow while keeping your upper arm pressed into the pad.', 'Lift until the dumbbell nears your shoulder and briefly squeeze your biceps.', 'Lower the dumbbell slowly until your arm is nearly straight again, then repeat before switching sides.']::text[], 'Exhale as you curl the dumbbell up, and inhale as you lower it back down under control.', ARRAY['Upper arm lifting off the pad during the curl', 'Swinging the dumbbell instead of moving smoothly', 'Stopping short and not lowering near full extension', 'Bending the wrist back as the dumbbell rises']::text[], 'beginner'::difficulty_level, 'biceps', ARRAY['forearms']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'biceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-seated-preacher-curl.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-seated-preacher-curl.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
