INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-seated-triceps-extension-2188', 'Dumbbell Seated Triceps Extension', 'A seated overhead dumbbell triceps exercise where you lower the weight behind your head and extend your elbows to press it back up.', 'Sit on a bench with your back straight and feet flat on the ground. Hold a dumbbell with both hands and extend your arms straight up overhead. Bend your elbows and lower the dumbbell behind your head, keeping your upper arms close to your ears. Pause for a moment, then straighten your arms and return to the starting position. Repeat for the desired number of repetitions.', ARRAY['Sit tall on a bench with both feet flat on the floor.', 'Hold one dumbbell by the top end with both hands and press it straight overhead.', 'Keep your upper arms close to your head and brace your torso.', 'Bend your elbows to lower the dumbbell behind your head under control.', 'Stop when your forearms are below parallel and your elbows stay pointed up.', 'Straighten your elbows to raise the dumbbell back to the overhead start position.']::text[], 'Inhale as you lower the dumbbell behind your head, and exhale as you extend your elbows to raise it overhead.', ARRAY['Elbows flare wide out to the sides.', 'Lower back arches as the weight goes overhead.', 'Upper arms drift backward and forward during the rep.', 'The dumbbell drops too low with no control behind the head.']::text[], 'beginner'::difficulty_level, 'triceps', ARRAY['shoulders']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'triceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-seated-triceps-extension.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-seated-triceps-extension.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-shrug-0406', 'Dumbbell Shrug', 'An isolation exercise where you hold dumbbells at your sides and lift your shoulders up to train the trapezius muscles.', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand with your palms facing your body. Keep your arms straight and let the dumbbells hang by your sides. Raise your shoulders as high as possible, as if you are trying to touch your ears with your shoulders. Hold the contraction for a second, then slowly lower your shoulders back down to the starting position. Repeat for the desired number of repetitions.', ARRAY['Stand tall with a dumbbell in each hand at your sides and your feet about hip-width apart.', 'Let your arms hang straight with your palms facing your body.', 'Lift your shoulders straight up toward your ears without bending your elbows.', 'Pause briefly at the top while keeping your torso still.', 'Lower your shoulders back down under control to the start position and repeat.']::text[], 'Exhale as you shrug your shoulders up, and inhale as you lower them back down.', ARRAY['Rolling the shoulders in circles instead of lifting straight up and down.', 'Bending the elbows and turning the move into an upright row.', 'Leaning the torso back or forward to swing the dumbbells.', 'Jutting the head forward as the shoulders rise.']::text[], 'beginner'::difficulty_level, 'traps', ARRAY['shoulders']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-shrug.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-shrug.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
