INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-side-bend-0407', 'Dumbbell Side Bend', 'A standing oblique exercise where you hold one dumbbell and bend your torso sideways under control.', 'Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand, letting it hang down by your side. Keeping your back straight and your core engaged, slowly bend sideways at the waist towards the opposite side of the dumbbell, lowering the weight as far as you comfortably can. Pause for a moment, then slowly return to the starting position. Repeat for the desired number of repetitions, then switch sides and repeat.', ARRAY['Stand tall with your feet about hip-width apart and hold a dumbbell in one hand at your side.', 'Place your other hand on your hip or behind your head and brace your stomach.', 'Keep your chest up and slowly bend your torso sideways away from the dumbbell.', 'Lower the dumbbell down the side of your leg as far as you can without twisting or leaning forward.', 'Squeeze your obliques and return to standing tall.', 'Complete all reps on one side, then switch hands and repeat.']::text[], 'Inhale as you bend sideways, then exhale as you return to standing.', ARRAY['Twisting the torso as you bend', 'Leaning forward instead of sideways', 'Shrugging the weighted shoulder up', 'Using momentum to swing back up']::text[], 'beginner'::difficulty_level, 'abdominals', ARRAY['obliques']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-side-bend.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-side-bend.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
