INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-single-leg-calf-raise-0409', 'Dumbbell Single Leg Calf Raise', 'A single-leg calf exercise using a dumbbell and step to strengthen the calves through a full ankle range of motion.', 'Stand on the edge of a step or platform with your heels hanging off and your toes on the step. Hold a dumbbell in one hand and place your other hand on a wall or railing for support. Raise your heel as high as possible, lifting your body up onto your toes. Pause for a moment at the top, then slowly lower your heel back down below the step. Repeat for the desired number of repetitions, then switch to the other leg.', ARRAY['Stand on the edge of a step with one foot, placing the ball of your foot on the step and letting your heel hang off.', 'Hold a dumbbell in one hand and lightly brace your other hand on a wall or rail.', 'Lift your nonworking foot off the step and straighten your standing leg.', 'Press through the ball of your foot to raise your heel as high as you can.', 'Pause briefly at the top while keeping your ankle stacked over your toes.', 'Lower your heel slowly below the step until you feel a stretch in your calf.', 'Complete all reps on one side, then switch legs.']::text[], 'Inhale as you lower your heel, and exhale as you press up onto your toes.', ARRAY['Bouncing out of the bottom instead of lowering under control', 'Rolling the ankle inward or outward during the raise', 'Bending the standing knee to help drive up', 'Using the support hand to pull the body upward']::text[], 'beginner'::difficulty_level, 'calves', ARRAY['ankles']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-single-leg-calf-raise.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-single-leg-calf-raise.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
