INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-single-leg-squat-0411', 'Dumbbell Single Leg Squat', 'A one-leg squat holding dumbbells that challenges the glutes, quads, balance, and lower-body control.', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand. Extend one leg forward and keep it off the ground throughout the exercise. Bend your standing leg and lower your body down as if sitting back into a chair. Keep your chest up and your back straight. Pause for a moment at the bottom, then push through your heel to return to the starting position. Repeat for the desired number of repetitions, then switch legs.', ARRAY['Stand tall holding a dumbbell in each hand at your sides.', 'Shift your weight onto one foot and lift the other leg straight in front of you.', 'Brace your torso and bend your standing knee and hip to lower under control.', 'Keep the lifted leg off the floor and lower as far as you can while staying balanced.', 'Drive through the standing foot to rise back to the starting position.', 'Complete all reps on one leg, then switch sides.']::text[], 'Inhale as you lower down, and exhale as you drive back up to standing.', ARRAY['Letting the lifted foot touch the floor between reps', 'Rounding the back at the bottom', 'Standing knee collapsing inward', 'Dropping too fast and losing balance']::text[], 'advanced'::difficulty_level, 'glutes', ARRAY['quadriceps', 'hamstrings', 'calves']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'glutes'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-single-leg-squat.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-single-leg-squat.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
