INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-squat-0413', 'Dumbbell Squat', 'A squat holding a dumbbell in each hand at your sides to train the glutes, quads, and legs.', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides. Keeping your chest up and core engaged, lower your body down by bending at the knees and hips, as if sitting back into a chair. Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go. Pause for a moment at the bottom, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', ARRAY['Stand tall with a dumbbell in each hand at your sides and place your feet about shoulder-width apart.', 'Brace your core, keep your chest up, and let your arms hang straight.', 'Bend your hips and knees together to sit down and slightly back.', 'Lower until your thighs are at least parallel to the floor or as low as you can while keeping your heels down.', 'Drive through your midfoot and heels to stand back up.', 'Finish tall with your hips and knees fully straight before the next rep.']::text[], 'Inhale as you lower into the squat, then exhale as you stand back up.', ARRAY['Letting the knees cave inward on the way down or up.', 'Rising onto the toes and lifting the heels off the floor.', 'Rounding the upper or lower back at the bottom.', 'Dropping the chest forward so the dumbbells swing ahead of the legs.']::text[], 'beginner'::difficulty_level, 'glutes', ARRAY['quadriceps', 'hamstrings', 'calves']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'glutes'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-squat.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-squat.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
