INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-standing-calf-raise-0417', 'Dumbbell Standing Calf Raise', 'A standing calf exercise where you hold dumbbells at your sides and raise your heels to train the calves and ankles.', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand. Raise your heels off the ground as high as possible, using your calves. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', ARRAY['Stand upright with a dumbbell in each hand and place your feet about hip-width apart.', 'Let your arms hang by your sides and keep your knees softly bent.', 'Press through the balls of your feet and lift your heels as high as you can.', 'Pause briefly at the top while staying tall through your torso.', 'Lower your heels back to the floor with control and repeat.']::text[], 'Inhale as you lower your heels, and exhale as you press up onto your toes.', ARRAY['Bouncing at the bottom instead of lowering under control', 'Rolling the ankles outward or inward', 'Bending the knees to turn it into a squat', 'Leaning the torso forward as the heels lift']::text[], 'beginner'::difficulty_level, 'calves', ARRAY['ankles']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-standing-calf-raise.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-standing-calf-raise.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-stiff-leg-deadlift-0432', 'Dumbbell Stiff Leg Deadlift', 'A hip-hinge deadlift with dumbbells that emphasizes the hamstrings and glutes while keeping only a slight knee bend.', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip. Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing a slight bend in your knees. Lower the dumbbells until you feel a stretch in your hamstrings, then squeeze your glutes and push through your heels to return to the starting position. Repeat for the desired number of repetitions.', ARRAY['Stand tall with your feet hip-width apart, holding a dumbbell in each hand in front of your thighs.', 'Soften your knees slightly and brace your midsection.', 'Push your hips straight back and slide the dumbbells down the front of your legs.', 'Lower until the dumbbells reach mid-shin or you feel a strong hamstring stretch while keeping your back flat.', 'Drive your feet into the floor and extend your hips to stand back up.', 'Finish tall with the dumbbells at your thighs and repeat.']::text[], 'Inhale as you hinge and lower the dumbbells, then exhale as you drive your hips forward to stand tall.', ARRAY['Bending the knees too much and turning it into a squat', 'Letting the dumbbells drift away from the legs', 'Rounding the lower back on the way down', 'Looking up and cranking the neck']::text[], 'intermediate'::difficulty_level, 'glutes', ARRAY['hamstrings', 'lower_back']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'glutes'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-stiff-leg-deadlift.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-stiff-leg-deadlift.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-sumo-squat-new-dumbbell-sumo-squat', 'Dumbbell Sumo Squat', 'A lower body exercise using a dumbbell in a sumo stance to target the glutes, quads, and adductors.', 'Stand with feet wider than shoulder-width, toes pointed out, holding a dumbbell vertically with both hands. Squat down by pushing hips back and knees out, then return to standing.', ARRAY['Stand with feet wide apart, toes angled outward.', 'Grip the dumbbell vertically between your legs.', 'Keep chest up and core braced.', 'Squat down, pushing knees outward.', 'Drive through heels to stand up.']::text[], 'Inhale as you lower down, exhale as you stand up.', ARRAY['Letting knees cave in', 'Rounding the back', 'Shallow squats']::text[], 'beginner'::difficulty_level, 'glutes', ARRAY['quadriceps', 'adductors', 'hamstrings']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'glutes'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-bar-grip-sumo-squat.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-bar-grip-sumo-squat.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dumbbell-upright-row-0437', 'Dumbbell Upright Row', 'A standing shoulder and upper-trap exercise where you pull dumbbells up the front of your body with elbows leading.', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip. Let the dumbbells hang in front of your thighs, with your arms fully extended. Keeping your back straight and your core engaged, exhale and lift the dumbbells straight up towards your chin, leading with your elbows. Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', ARRAY['Stand tall with a dumbbell in each hand in front of your thighs, palms facing your body.', 'Brace your midsection and keep your chest lifted.', 'Pull the dumbbells straight up along the front of your body by driving your elbows up and out.', 'Raise until the dumbbells reach about upper-chest height and your elbows stay higher than your hands.', 'Pause briefly, then lower the dumbbells back to your thighs with control.']::text[], 'Exhale as you pull the dumbbells up, and inhale as you lower them back down.', ARRAY['Pulling the dumbbells all the way to the chin', 'Letting the wrists bend sharply at the top', 'Swinging the torso to start the lift', 'Hands rising higher than the elbows']::text[], 'beginner'::difficulty_level, 'deltoids', ARRAY['traps', 'biceps']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-upright-row.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-upright-row.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
