INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('dynamic-chest-stretch-1167', 'Dynamic Chest Stretch', 'A rhythmic arm movement to increase chest mobility and warm up the pectoral muscles.', 'Stand tall with feet shoulder-width apart and arms extended at shoulder height. Swing your arms in a controlled, hugging motion across your chest and then open wide, repeating rhythmically to stretch and activate the chest.', ARRAY['Stand with your feet shoulder-width apart.', 'Extend both arms out to your sides at shoulder height.', 'Swing your arms forward, crossing them in front of your chest.', 'Open your arms wide, stretching your chest as you do.', 'Repeat the swinging motion for the desired number of repetitions.']::text[], 'Breathe naturally throughout the movement.', ARRAY['Swinging arms too forcefully', 'Allowing shoulders to shrug', 'Rotating the torso excessively']::text[], 'beginner'::difficulty_level, 'pectoralis_major', ARRAY['anterior_deltoid', 'biceps']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'chest'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-dynamic-chest-stretch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-dynamic-chest-stretch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
