INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('elliptical-trainer-2141', 'Elliptical Trainer', 'A low-impact cardio exercise using a standing elliptical machine for total body endurance and aerobic gains.', 'Step onto the elliptical machine and grasp the moving handles. Begin moving feet in an elliptical motion, engaging both the lower and upper body by pushing and pulling the handles as you stride.', ARRAY['Step onto the pedals and hold the handles.', 'Select desired resistance and incline.', 'Begin moving feet in a smooth, elliptical pattern.', 'Push and pull the handles with your arms in sync with your strides.', 'Maintain a steady cadence and upright posture.']::text[], 'Maintain rhythmic, deep breathing throughout the workout.', ARRAY['Leaning too far forward or backward', 'Relying only on legs or arms', 'Choppy, fast movements']::text[], 'beginner'::difficulty_level, 'cardiovascular_system', ARRAY['quadriceps', 'hamstrings', 'glutes', 'calves', 'pectoralis_major', 'deltoids']::text[], ARRAY['machine']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/elliptical.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/elliptical.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('exercise-ball-sit-up-1338', 'Exercise Ball Sit-Up', 'A core exercise where sit-ups are performed while stabilizing on a Swiss ball, increasing abdominal activation.', 'Sit on a stability ball and walk your feet forward until the ball is under your lower back. Cross your arms over your chest or place hands behind your head, then contract your abs to lift your torso, performing a sit-up. Lower yourself back down slowly and repeat.', ARRAY['Sit on the exercise ball with feet flat on the floor.', 'Walk feet forward, rolling until the ball supports your lower back.', 'Cross arms over your chest or position hands behind your head.', 'Engage your core and sit up, lifting your upper body.', 'Lower back down under control to starting position.']::text[], 'Exhale as you lift, inhale as you lower.', ARRAY['Using momentum', 'Feet lifting off the ground', 'Ball not positioned under lower back']::text[], 'beginner'::difficulty_level, 'abdominals', ARRAY['hip_flexors', 'obliques']::text[], ARRAY['bench']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'abs'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/sit-up-on-exercise-ball.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/sit-up-on-exercise-ball.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
