INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('exercise-ball-spinal-stretch-1339', 'Exercise Ball Spinal Stretch', 'A gentle back extension and stretch performed by draping the body over an exercise ball to mobilize the spine.', 'Sit on a stability ball and carefully roll down until your back is resting on the ball. Extend your arms overhead and allow your spine to gently arch over the ball, stretching the entire length of your back. Hold the stretch, breathing deeply.', ARRAY['Sit on the exercise ball with feet hip-width apart.', 'Slowly walk your feet forward, rolling until your back is draped over the ball.', 'Let your arms extend overhead or rest beside you for support.', 'Relax into the stretch, allowing your spine to gently extend.', 'Hold for the desired duration, then carefully return to a seated position.']::text[], 'Breathe deeply and steadily throughout the stretch.', ARRAY['Arching excessively', 'Letting hips sag too low', 'Losing balance on the ball']::text[], 'beginner'::difficulty_level, 'erector_spinae', ARRAY['rectus_abdominis', 'hip_flexors']::text[], ARRAY['bench']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-spinal-stretch-on-exercise-ball.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-spinal-stretch-on-exercise-ball.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
