INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('ez-bar-biceps-curl-2407', 'EZ Bar Biceps Curl', 'Classic biceps curl using an EZ barbell to build arm mass with ergonomic grip.', 'Stand upright holding an EZ bar with hands on the angled grips, arms fully extended. Curl the bar up toward your shoulders, keeping elbows close to your torso. Squeeze the biceps at the top, then slowly lower to the starting position.', ARRAY['Grip the EZ bar at angled sections, palms facing up.', 'Stand tall with arms fully extended and elbows anchored.', 'Curl the bar upward, contracting the biceps.', 'Pause and squeeze at the top.', 'Lower the bar down slowly.']::text[], 'Exhale as you lift, inhale lowering the bar.', ARRAY['Using momentum', 'Letting elbows move forward', 'Partial reps']::text[], 'beginner'::difficulty_level, 'biceps', ARRAY['brachialis', 'forearms']::text[], ARRAY['barbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'biceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/ez-barbell-biceps-curl.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/ez-barbell-biceps-curl.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
