INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('ez-bar-lying-triceps-extension-0061', 'EZ Bar Lying Triceps Extension', 'Lying triceps extension using EZ bar to target triceps with reduced wrist strain.', 'Lie on a flat bench holding the EZ bar with arms extended above your chest. Bend elbows to lower the bar toward your forehead, upper arms stationary. Extend arms back up, focusing on triceps contraction, and repeat for desired reps.', ARRAY['Lie on bench, grip EZ bar with medium width.', 'Extend arms fully above chest.', 'Bend elbows, lowering bar toward forehead.', 'Keep upper arms stationary.', 'Extend to starting position, repeat.']::text[], 'Inhale lowering bar, exhale extending arms.', ARRAY['Flaring elbows', 'Moving upper arms', 'Lowering bar too far past head']::text[], 'intermediate'::difficulty_level, 'triceps', ARRAY['anconeus', 'forearms']::text[], ARRAY['barbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'triceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/ez-barbell-lying-triceps-extension.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/ez-barbell-lying-triceps-extension.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
