INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('ez-barbell-anti-gravity-press-0445', 'EZ Barbell Anti Gravity Press', 'A standing overhead press using an EZ bar to train the delts, triceps, and upper chest through a full pressing range.', 'Start by standing with your feet shoulder-width apart and holding the ez barbell with an overhand grip. Raise the barbell to shoulder height, keeping your elbows slightly bent and your palms facing forward. Press the barbell overhead, extending your arms fully. Lower the barbell back to shoulder height and repeat for the desired number of repetitions.', ARRAY['Stand tall with your feet about hip- to shoulder-width apart and hold the EZ bar at shoulder height with an overhand grip.', 'Brace your core and keep your wrists stacked over your elbows.', 'Press the bar straight overhead until your arms are fully extended above your shoulders.', 'Move your head slightly back as the bar passes your face, then bring your head through under the bar at the top.', 'Lower the bar under control back to shoulder height.', 'Repeat each rep from a stable standing position.']::text[], 'Inhale and brace at shoulder height, exhale as you press overhead, and inhale again as you lower the bar back down.', ARRAY['Leaning back hard and turning it into an incline press', 'Pressing the bar out in front instead of overhead', 'Flaring the elbows too far out from the start', 'Lowering the bar too fast and bouncing at the shoulders']::text[], 'intermediate'::difficulty_level, 'deltoids', ARRAY['triceps', 'chest']::text[], ARRAY['barbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/ez-barbell-anti-gravity-press.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/ez-barbell-anti-gravity-press.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
