INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('feet-and-ankles-rotation-stretch-drv-stretching-feet-and-ankles-rotation-stretch', 'Feet and Ankles Rotation Stretch', 'A mobility exercise involving circular ankle movements that target the calves and improve ankle flexibility.', 'Sit or stand with one leg lifted and rotate your foot at the ankle in slow, controlled circles, first one direction and then the other. Focus on full range of motion to stretch and warm up lower leg muscles and joints.', ARRAY['Sit or stand and lift one foot off the ground.', 'Point your toes and slowly rotate your ankle in circles.', 'Make several circles clockwise, then reverse to counterclockwise.', 'Repeat for the other ankle.', 'Maintain steady breathing and controlled motion.']::text[], 'Breathe normally throughout the stretch.', ARRAY['Rushed movements', 'Small circles', 'Not changing direction']::text[], 'beginner'::difficulty_level, 'calves', ARRAY['soleus', 'tibialis_anterior', 'peroneals']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-feet-and-ankles-rotation-stretch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-feet-and-ankles-rotation-stretch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('feet-and-ankles-stretch-drv-stretching-feet-and-ankles-stretch', 'Feet and Ankles Stretch', 'A stretch to increase flexibility and mobility in the feet and ankle muscles.', 'Sit on the floor with your legs extended. Point and flex your toes to stretch the ankle and foot muscles. Hold the stretch for several seconds and repeat as needed.', ARRAY['Sit or stand with legs extended or positioned comfortably.', 'Point your toes downward to stretch the top of your feet and fronts of your ankles.', 'Flex your toes upward toward your shins to stretch the calves and back of the ankles.', 'Hold each position for 15-30 seconds.', 'Repeat the sequence for several reps.']::text[], 'Breathe normally throughout, or exhale as you relax into each stretch.', ARRAY['Bouncing during the stretch', 'Overstretching or forcing range of motion', 'Holding breath']::text[], 'beginner'::difficulty_level, 'calves', ARRAY['tibialis_anterior', 'peroneals']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-feet-and-ankles-stretch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-feet-and-ankles-stretch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('flat-bench-cable-fly-0620', 'Flat Bench Cable Fly', 'A chest isolation exercise using cables while lying on a flat bench for continuous tension.', 'Lie on a flat bench positioned between two low cable pulleys. Grab the handles with arms extended and a slight bend in the elbows, then bring your hands together in a wide arc before returning to the start position.', ARRAY['Set a flat bench between two cable pulleys and attach handles.', 'Lie back and grip each handle with arms extended.', 'With elbows slightly bent, bring handles together above your chest.', 'Squeeze your chest at the top.', 'Slowly return to the starting position with control.']::text[], 'Exhale as you bring hands together, inhale as you return.', ARRAY['Locking elbows', 'Letting the cables slam back', 'Using too much weight']::text[], 'intermediate'::difficulty_level, 'pectoralis_major', ARRAY['anterior_deltoid', 'biceps']::text[], ARRAY['cable']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'chest'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/cable-lying-fly-flat-bench-cable-fly.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/cable-lying-fly-flat-bench-cable-fly.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('flexion-leg-sit-up-stretch-drv-stretching-flexion-leg-sit-up', 'Flexion Leg Sit-Up Stretch', 'A stretch that combines trunk flexion with leg movement to lengthen the abdominals and hip flexors.', 'Start lying on your back with knees bent. Flex your spine as you perform a sit-up, reaching toward your knees. Pause in the top position for a stretch before lowering back down.', ARRAY['Lie on your back with knees bent and feet flat on the floor.', 'Cross arms over chest or reach toward knees.', 'Contract abdominal muscles to sit up, curling your spine.', 'Reach for your knees at the top to enhance the stretch.', 'Lower back to starting position with control.']::text[], 'Exhale as you sit up, inhale as you lower down.', ARRAY['Jerking the movement', 'Using momentum instead of muscle', 'Straining the neck']::text[], 'beginner'::difficulty_level, 'abdominals', ARRAY['hip_flexors']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'abs'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-flexion-leg-sit-up.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-flexion-leg-sit-up.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
