INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('floor-crunch-0274', 'Floor Crunch', 'A basic abdominal crunch performed lying on the floor to strengthen the rectus abdominis.', 'Lie flat on your back with knees bent and feet flat on the floor. Place your hands behind your head or across your chest, engage your core, and curl your shoulders up toward your knees.', ARRAY['Lie on your back with knees bent and feet hip-width apart.', 'Place hands lightly behind head or cross over chest.', 'Engage core and lift shoulders off the floor.', 'Pause briefly at the top of the movement.', 'Slowly return to the starting position.']::text[], 'Exhale as you crunch up, inhale as you lower down.', ARRAY['Pulling on neck', 'Not engaging core', 'Using momentum', 'Not breathing properly']::text[], 'beginner'::difficulty_level, 'rectus_abdominis', ARRAY['obliques']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/crunch-floor-female.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/crunch-floor-female.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
