INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('front-plank-0464', 'Front Plank', 'An isometric core stability exercise performed in a prone position to strengthen the abdominals and stabilize the entire body.', 'Start in a prone position with forearms and toes on the ground. Engage your core, keep your body in a straight line from head to heels, and hold the position for the desired amount of time without allowing hips to rise or sag.', ARRAY['Lie face down, placing forearms on the ground and elbows under shoulders.', 'Lift your body off the floor, supporting weight on forearms and toes.', 'Keep your body in a straight line from head to heels.', 'Engage your core and glutes for stability.', 'Hold the position for the prescribed time, then lower to the ground.']::text[], 'Breathe slowly and steadily during the hold.', ARRAY['Letting hips drop or rise', 'Arched back', 'Not engaging the core']::text[], 'beginner'::difficulty_level, 'abdominals', ARRAY['transverse_abdominis', 'obliques', 'glutes', 'shoulders']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'abs'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/front-plank-female.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/front-plank-female.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
