INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('front-toe-touch-stretch-drv-stretching-front-toe-touch', 'Front Toe Touch Stretch', 'A classic stretch where you bend forward to touch your toes, lengthening the hamstrings and lower back.', 'Stand or sit with legs straight. Hinge at the hips and reach forward toward your toes, keeping your spine long. Hold at your end range, feeling a stretch in the back of your legs.', ARRAY['Stand (or sit) with legs straight.', 'Bend slowly forward from the hips, keeping a flat back.', 'Reach towards or touch your toes with your hands.', 'Keep knees straight but not locked.', 'Hold stretch, then return to starting position.']::text[], 'Exhale as you bend forward, inhale as you return upright.', ARRAY['Rounding the back excessively', 'Bouncing or forcing the stretch', 'Locking the knees']::text[], 'beginner'::difficulty_level, 'hamstrings', ARRAY['lower_back', 'calves']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'hamstrings'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-front-toe-touch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-front-toe-touch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
