INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('glute-bridge-drv-hip-raise-bridge', 'Glute Bridge', 'A floor-based exercise that strengthens the glutes and hamstrings by lifting the hips.', 'Lie on your back, knees bent and feet flat on the floor hip-width apart. Drive through your heels to lift hips off the ground, squeezing the glutes at the top, then lower back down with control.', ARRAY['Start lying on back with knees bent, feet hip-width apart.', 'Arms rest at sides, palms down.', 'Push through heels, lifting hips toward ceiling.', 'Pause and squeeze glutes at top.', 'Lower hips back to floor.']::text[], 'Exhale as you lift hips, inhale as you lower down.', ARRAY['Pushing through toes', 'Flaring ribs', 'Rushing movement']::text[], 'beginner'::difficulty_level, 'glutes', ARRAY['hamstrings', 'lower_back']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'glutes'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/hip-raise-bridge.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/hip-raise-bridge.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('hanging-leg-hip-raise-1764', 'Hanging Leg Hip Raise', 'A hanging core exercise where you raise your knees and curl your hips upward to train the abs and hip flexors.', 'Hang from a pull-up bar with your arms fully extended and your palms facing away from you. Engage your core and lift your legs up by flexing your hips and knees until your thighs are parallel to the ground. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', ARRAY['Hang from the bar with both hands and let your body settle into a dead hang.', 'Pull your ribs down and brace your midsection to stop excess swinging.', 'Bend your knees and lift them toward your chest by curling your hips upward.', 'Raise until your thighs are at least parallel to the floor or your knees reach hip height.', 'Pause briefly at the top while keeping your torso steady.', 'Lower your legs with control until you return to a full hang.']::text[], 'Exhale as you raise your knees and curl your hips up; inhale as you lower back to the hang.', ARRAY['Swinging the body to start each rep', 'Shrugging the shoulders up toward the ears', 'Dropping the legs quickly on the way down', 'Only lifting the knees halfway with no hip curl']::text[], 'intermediate'::difficulty_level, 'abdominals', ARRAY['hip_flexors', 'lower_back']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/hanging-leg-hip-raise.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/hanging-leg-hip-raise.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
