INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('hanging-straight-leg-raise-0474', 'Hanging Straight Leg Raise', 'A core exercise performed while hanging, lifting straight legs to target the abdominals and hip flexors.', 'Hang from a pull-up bar with an overhand grip, keeping your body steady. Contract your core and raise your legs, keeping them straight, until they''re parallel to the ground or higher. Lower your legs with control and repeat.', ARRAY['Hang from a pull-up bar with arms fully extended.', 'Keep legs together and straight.', 'Engage core and lift legs up to parallel or higher.', 'Pause briefly at the top.', 'Lower legs under control to starting position.']::text[], 'Exhale as you lift legs, inhale as you lower.', ARRAY['Swinging the body', 'Using momentum', 'Bending knees or arching back']::text[], 'intermediate'::difficulty_level, 'abdominals', ARRAY['hip_flexors', 'obliques', 'forearms']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'abs'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/hanging-straight-leg-raise.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/hanging-straight-leg-raise.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
