INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('hip-circles-stretch-0257', 'Hip Circles Stretch', 'A dynamic stretch to increase mobility in the hips by performing circular leg movements.', 'Stand upright and place your hands on your hips. Lift one knee and move your leg in a controlled circular motion from the hip joint, reversing direction as needed; repeat with the other leg.', ARRAY['Stand tall with feet shoulder-width apart, hands on hips.', 'Lift one knee up in front of you.', 'Move your knee and thigh in a circular motion outward.', 'Reverse and perform circles inward after the set.', 'Switch legs and repeat.']::text[], 'Inhale and exhale naturally during the stretch.', ARRAY['Rushing the circles', 'Swinging the whole body', 'Holding breath']::text[], 'beginner'::difficulty_level, 'hip_flexors', ARRAY['tensor_fasciae_latae', 'glutes', 'adductors', 'piriformis']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-hip-circles-stretch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-hip-circles-stretch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
