INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('hip-extension-stretch-drv-stretching-hip-extension-stretch', 'Hip Extension Stretch', 'A stretch focused on extending the hip to target tight hip flexors and anterior hips.', 'Lie on your stomach with legs outstretched and hands placed underneath your shoulders. Gently press up through your palms, extending the hips and lifting your torso without overextending the low back. Maintain a gentle stretch and hold.', ARRAY['Lie face down with legs extended.', 'Place hands beneath shoulders, elbows bent.', 'Press palms into floor, lifting chest and gently extending hips.', 'Hold the stretch at a comfortable tension.', 'Slowly lower back down.']::text[], 'Inhale while preparing, exhale as you press up into stretch.', ARRAY['Overarching the lower back', 'Forcing the stretch', 'Holding breath']::text[], 'beginner'::difficulty_level, 'hip_flexors', ARRAY['quadriceps', 'lower_back']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-hip-extension-stretch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-hip-extension-stretch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
