INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('hip-flexor-and-quadriceps-stretch-1564', 'Hip Flexor and Quadriceps Stretch', 'A stretch that lengthens the hip flexors and quadriceps by using a kneeling or lunge position.', 'Start in a half-kneeling (lunge) position with one knee on the floor and the other foot planted in front. Gently shift hips forward while keeping torso upright, feeling the stretch in the front of the rear leg and thigh. Hold, then switch sides.', ARRAY['Begin in a half-kneeling position, one knee down, one foot forward.', 'Keep torso upright with hands on hips or front knee.', 'Push hips forward slightly to increase the stretch.', 'Feel the stretch in the hip flexor and thigh of the back leg.', 'Hold for desired time, then switch legs.']::text[], 'Breathe deeply and steadily throughout the stretch.', ARRAY['Leaning forward', 'Arching lower back', 'Letting front knee go past toes']::text[], 'beginner'::difficulty_level, 'quadriceps', ARRAY['hip_flexors', 'glutes']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'quads'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-hip-flexor-and-quad-stretch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-hip-flexor-and-quad-stretch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('incline-leg-hip-raise-0325', 'Incline Leg Hip Raise', 'A core exercise where legs and hips are raised while lying on an incline, targeting the lower abdominals.', 'Lie on your back on an incline bench and hold the handles or bench for stability. Keeping legs straight, lift them until your hips come off the bench, then lower slowly.', ARRAY['Lie face up on an incline bench and grip the handles behind your head.', 'Extend your legs straight and keep them together.', 'Raise your legs towards your chest, lifting your hips off the bench.', 'Pause at the top, focusing on contracting your abs.', 'Lower your legs under control to the starting position.']::text[], 'Exhale as you lift hips, inhale as you lower legs.', ARRAY['Swinging legs', 'Arching lower back excessively', 'Not performing full hip lift']::text[], 'intermediate'::difficulty_level, 'abdominals', ARRAY['hip_flexors', 'obliques']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'abs'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/incline-leg-hip-raise.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/incline-leg-hip-raise.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('incline-push-up-0493', 'Incline Push-Up', 'A push-up variation with hands elevated, reducing resistance on the chest and triceps.', 'Place your hands on an elevated surface like a bench, stand with feet extended behind you and body straight. Lower your chest toward the surface, keeping elbows at a 45-degree angle, then press up to starting position.', ARRAY['Place hands shoulder-width apart on elevated surface.', 'Extend legs back with feet together, forming a straight line.', 'Lower chest toward the surface, elbows at 45 degrees.', 'Pause when chest is just above the surface.', 'Push back up to starting position.']::text[], 'Inhale as you lower, exhale as you push up.', ARRAY['Sagging hips', 'Flaring elbows out', 'Incomplete range of motion']::text[], 'beginner'::difficulty_level, 'pectoralis_major', ARRAY['anterior_deltoid', 'triceps']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'chest'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/incline-push-ups.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/incline-push-ups.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('inverted-row-between-chairs-0499', 'Inverted Row Between Chairs', 'A bodyweight pulling exercise performed using a bar or sturdy broomstick supported between two chairs.', 'Set up a sturdy bar or stick horizontally between two secure chairs. Lie on your back underneath the bar, grasp it with an overhand, shoulder-width grip, and keep your body straight from head to heels. Pull your chest toward the bar, squeezing your shoulder blades together, then lower yourself back down with control.', ARRAY['Set up a sturdy bar between two heavy chairs.', 'Lie underneath with your chest directly below the bar.', 'Grip the bar with an overhand, shoulder-width grip.', 'Brace your body, keeping a straight line from head to heels.', 'Pull your chest to the bar, pause, then lower yourself slowly.']::text[], 'Exhale as you pull up, inhale as you lower down.', ARRAY['Allowing hips to drop', 'Flared elbows', 'Not lowering all the way', 'Not squeezing shoulder blades']::text[], 'beginner'::difficulty_level, 'lats', ARRAY['biceps', 'rhomboids', 'traps', 'posterior_deltoid']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/inverted-row-between-chairs.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/inverted-row-between-chairs.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('inverted-row-with-straps-0498', 'Inverted Row With Straps', 'A bodyweight upper-back row using suspension straps, pulling your chest toward the handles while keeping your body straight.', 'Set up a suspension trainer or straps at chest height. Stand facing the anchor point and grab the handles with an overhand grip. Walk your feet forward, leaning back until your body is at an angle. Keep your body straight and engage your core. Pull your chest towards the handles, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower yourself back to the starting position. Repeat for the desired number of repetitions.', ARRAY['Set the straps to about chest height and stand facing the anchor point.', 'Grab the handles with an overhand grip and walk your feet forward until your body leans back in a straight line.', 'Brace your core and keep your heels planted with your arms fully extended.', 'Pull your chest toward the handles by driving your elbows back and squeezing your shoulder blades together.', 'Pause briefly when your hands reach your ribs or chest.', 'Lower yourself with control until your arms are straight again.']::text[], 'Inhale as you lower yourself away from the handles, and exhale as you pull your chest toward them.', ARRAY['Hips sag or pike instead of staying straight', 'Shrugging the shoulders up toward the ears', 'Pulling with bent wrists and loose handles', 'Letting the body drop quickly on the way down']::text[], 'beginner'::difficulty_level, 'upper_back', ARRAY['biceps', 'forearms']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/inverted-row-with-straps.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/inverted-row-with-straps.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('iron-cross-stretch-1419', 'Iron Cross Stretch', 'A lying rotational stretch that improves spinal mobility and stretches the obliques and lower back.', 'Lie on your back with arms spread out in a ''T'' position. Lift one leg straight up and sweep it across your body to the opposite side, letting it fall toward the floor while keeping your shoulders flat. Hold the position, feeling a stretch through your torso and hip.', ARRAY['Lie on your back with arms extended out to the sides.', 'Lift one leg straight up towards the ceiling.', 'Sweep the raised leg across your body to the opposite side.', 'Allow your foot to touch or lower towards the floor.', 'Hold the stretch, then switch legs.']::text[], 'Exhale as you move into the twist, inhale as you return to center.', ARRAY['Lifting shoulders off the floor', 'Twisting too quickly', 'Holding breath', 'Allowing hips to pop up']::text[], 'beginner'::difficulty_level, 'obliques', ARRAY['erector_spinae', 'gluteus_medius', 'glutes', 'pectoralis_major']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'abs'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-iron-cross-stretch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-iron-cross-stretch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('jackknife-drv-jackknife-pilates', 'Jackknife', 'A Pilates core exercise involving lifting hips and legs up and overhead to strengthen the abdominals.', 'Lie flat on your back with arms by your sides and legs together. Lift your legs towards the ceiling and roll your hips off the mat, supporting your back lightly with your hands if needed, then lower with control.', ARRAY['Lie on your back with arms at your sides and legs extended.', 'Engage your core and lift legs towards the ceiling.', 'Continue lifting hips off the mat, reaching feet upward.', 'Pause at the top with hips elevated.', 'Slowly roll back down vertebra by vertebra.']::text[], 'Exhale while lifting up, inhale while lowering down.', ARRAY['Letting legs fall too quickly', 'Arching the back excessively', 'Pushing with arms']::text[], 'intermediate'::difficulty_level, 'rectus_abdominis', ARRAY['hip_flexors', 'lower_back', 'glutes']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/jackknife-pilates.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/jackknife-pilates.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
