INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('jackknife-floor-0981', 'Jackknife Floor', 'A dynamic ab exercise where you simultaneously raise legs and torso to touch in a ''V'' position.', 'Lie flat on your back with arms and legs extended. Simultaneously lift your arms, head, and legs, bringing your hands to meet your shins or feet at the top, then lower back down with control.', ARRAY['Lie flat with arms extended overhead and legs straight.', 'Engage your core, lift arms and legs toward each other.', 'Reach hands toward feet, forming a ''V'' at the top.', 'Pause briefly, squeezing at the top.', 'Lower back down slowly to starting position.']::text[], 'Exhale as you lift, inhale as you lower.', ARRAY['Bending knees or elbows too much', 'Heaving with momentum', 'Letting lower back arch']::text[], 'intermediate'::difficulty_level, 'rectus_abdominis', ARRAY['hip_flexors', 'obliques']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/jack-knife-floor.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/jack-knife-floor.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
