INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('jackknife-split-crunch-drv-jack-split-crunches', 'Jackknife Split Crunch', 'A crunch variation combining a V-up with a leg split to target the abs and hip flexors.', 'Lie flat on your back with legs extended and arms overhead. Simultaneously lift your torso and legs while spreading your feet apart (splitting legs) and reaching your hands towards your feet. Lower back to the starting position with control.', ARRAY['Lie on your back with arms extended overhead and legs straight.', 'Engage your core and simultaneously lift your torso and legs off the ground.', 'As you rise, spread your legs into a split while reaching your hands toward your feet.', 'Pause at the top, squeezing your abs.', 'Lower your legs and torso back to the ground with control, bringing feet together.']::text[], 'Exhale when crunching up, inhale when lowering down.', ARRAY['Swinging the legs', 'Using momentum', 'Arching the lower back']::text[], 'intermediate'::difficulty_level, 'rectus_abdominis', ARRAY['hip_flexors', 'obliques', 'adductors']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/jack-split-crunches.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/jack-split-crunches.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('jump-rope-2612', 'Jump Rope', 'A cardio exercise where you turn a rope with your hands and perform repeated small jumps as it passes under your feet.', 'Hold the handles of the jump rope with your hands, palms facing inward. Stand with your feet shoulder-width apart and knees slightly bent. Swing the rope over your head and jump over it as it comes towards your feet. Land softly on the balls of your feet and repeat the jump as the rope comes around again. Continue jumping for the desired duration or number of repetitions.', ARRAY['Hold a handle in each hand with the rope behind your heels.', 'Stand tall with feet close together and elbows tucked by your sides.', 'Turn the rope with your wrists and swing it up overhead.', 'Hop just high enough to clear the rope as it passes under your feet.', 'Land softly on the balls of your feet with knees slightly bent.', 'Keep the rope moving in a smooth rhythm and repeat each jump.']::text[], 'Breathe steadily and naturally, exhaling softly every few jumps while keeping a relaxed rhythm.', ARRAY['Swinging the arms in big circles instead of using the wrists', 'Jumping too high off the floor on each rep', 'Landing flat-footed or with stiff knees', 'Letting the hands drift wide away from the hips']::text[], 'beginner'::difficulty_level, 'cardiovascular_system', ARRAY['calves', 'quadriceps', 'hamstrings', 'glutes']::text[], ARRAY['band']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/jump-rope.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/jump-rope.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
