INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('jump-step-up-drv-jump-step-up', 'Jump Step-Up', 'A plyometric exercise involving stepping and jumping onto a raised surface to build leg power and coordination.', 'Stand in front of a box or platform. Step onto the box with one foot, then explosively jump up, driving through the working leg. Land softly and return to the starting position, alternating legs if desired.', ARRAY['Stand facing a sturdy box or platform.', 'Place one foot firmly on top of the box.', 'Drive through the heel and explode upward, lifting your other knee high.', 'Land softly on the box with both feet.', 'Step or jump down with control and repeat.']::text[], 'Exhale during the jump, inhale as you land and reset.', ARRAY['Letting the knee cave inward', 'Landing hard or flat-footed', 'Not using full range of motion']::text[], 'intermediate'::difficulty_level, 'quadriceps', ARRAY['glutes', 'hamstrings', 'calves']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'quads'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/jump-step-up.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/jump-step-up.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
