INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('jumping-jack-new-low-impact-jumping-jack', 'Jumping Jack', 'A dynamic total-body movement for cardiovascular and muscular endurance.', 'Begin standing with feet together and arms at sides. Jump feet outward while raising arms overhead, then reverse to starting position in a single fluid motion.', ARRAY['Start with feet together and arms relaxed at your sides.', 'Jump feet out to shoulder-width as you raise arms overhead.', 'Briefly touch hands or keep arms straight above head.', 'Jump feet back together and arms down to sides.', 'Repeat at a brisk pace.']::text[], 'Breathe evenly throughout the movement.', ARRAY['Slapping feet', 'Incomplete arm raise', 'Landing hard on heels']::text[], 'beginner'::difficulty_level, 'full_body', ARRAY['deltoids', 'adductors', 'calves', 'gluteus_medius']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/jumping-jack.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/jumping-jack.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
