INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('kettlebell-deadlift-drv-kettlebell-deadlift', 'Kettlebell Deadlift', 'A hip hinge movement using a kettlebell from the floor to standing, building posterior chain and grip strength.', 'Stand with feet hip-width apart, kettlebell between your feet. Hinge at the hips, bend knees and keep your back flat as you grip the kettlebell handle with both hands. Drive through your heels, extend hips and stand tall with the kettlebell, then reverse the movement to return to start.', ARRAY['Place kettlebell between your feet; stand with feet hip-width apart.', 'Hinge at hips and bend knees, keeping back flat and chest up.', 'Grip the kettlebell handle with both hands.', 'Drive through your heels to stand up, fully extending hips and knees.', 'Lower the kettlebell to the floor under control by hinging at the hips.']::text[], 'Exhale as you stand up, inhale as you lower down.', ARRAY['Rounding the lower back', 'Letting kettlebell drift from body', 'Locking knees early', 'Shrugging shoulders']::text[], 'beginner'::difficulty_level, 'glutes', ARRAY['hamstrings', 'erector_spinae', 'quadriceps', 'forearms']::text[], ARRAY['kettlebell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'glutes'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/kettlebell-deadlift.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/kettlebell-deadlift.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('kneeling-back-rotation-stretch-drv-stretching-kneeling-back-rotation-stretch', 'Kneeling Back Rotation Stretch', 'A mobility stretch that improves thoracic spine rotation while kneeling, also opening the chest and shoulders.', 'Begin in a quadruped or kneeling lunge position. Place one hand behind your head and rotate your torso to open the chest, aiming elbow upward. Hold briefly and return, then repeat on the other side.', ARRAY['Kneel on the floor (all fours or lunge position).', 'Place one hand behind your head or neck.', 'Rotate elbow and upper body upward, opening chest.', 'Hold for a moment at top of rotation.', 'Return to start and repeat; switch sides.']::text[], 'Exhale as you rotate, inhale returning to start.', ARRAY['Rotating through lower back', 'Forcing the stretch', 'Letting hips move']::text[], 'beginner'::difficulty_level, 'thoracic_spine', ARRAY['obliques', 'pectoralis_major', 'lats']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-kneeling-back-rotation-stretch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-kneeling-back-rotation-stretch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('kneeling-lat-stretch-1346', 'Kneeling Lat Stretch', 'A floor stretch to lengthen the latissimus dorsi and improve shoulder mobility.', 'Kneel on the ground, sit your hips back towards your heels, and reach both arms straight out in front of you on the floor. Push your chest down and feel the stretch along each side of your back. Hold, then optionally move hands to each side to target one lat more intensely.', ARRAY['Kneel and sit hips back on heels.', 'Reach both arms forward, palms on floor.', 'Push chest toward the ground.', 'Hold the stretch, focusing on the long side body.', 'Optionally shift hands to each side for more stretch.']::text[], 'Inhale deeply as you reach forward, exhale as you sink deeper into the stretch.', ARRAY['Arching lower back excessively', 'Bending elbows too much', 'Letting hips lift off heels', 'Tensing shoulders']::text[], 'beginner'::difficulty_level, 'lats', ARRAY['teres_major', 'triceps', 'erector_spinae']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-kneeling-lat-stretch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-kneeling-lat-stretch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('kneeling-triceps-stretch-1771', 'Kneeling Triceps Stretch', 'A static stretch targeting the triceps and lats by flexing the elbow overhead while kneeling.', 'Kneel on the floor and reach one arm overhead, bending the elbow to let your hand touch your upper back. With the opposite hand, gently press on the bent elbow to increase the stretch.', ARRAY['Kneel on the floor or mat.', 'Raise one arm overhead then bend the elbow so your hand touches your upper back.', 'Use your other hand to gently push on the bent elbow.', 'Hold the stretch.', 'Switch arms and repeat.']::text[], 'Breathe deeply and steadily throughout the stretch.', ARRAY['Arching the back', 'Pushing too hard', 'Letting elbow flare out']::text[], 'beginner'::difficulty_level, 'triceps', ARRAY['lats', 'deltoids']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'triceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-kneeling-triceps-extension.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-kneeling-triceps-extension.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('landmine-180-0562', 'Landmine 180', 'A rotating landmine core exercise where you swing the barbell side to side using your hips, shoulders, and obliques.', 'Stand with your feet shoulder-width apart and hold the barbell with both hands in front of your chest. Bend your knees slightly and rotate your torso to the right, swinging the barbell down towards your right hip. As you reach the bottom of the movement, quickly reverse the motion and rotate your torso to the left, swinging the barbell up and across your body towards your left shoulder. Continue this twisting motion, alternating sides, for the desired number of repetitions.', ARRAY['Stand facing the free end of the barbell with your feet about shoulder-width apart, and hold the barbell sleeve with both hands in front of your chest.', 'Bend your knees slightly, brace your midsection, and keep your arms long but not locked.', 'Rotate your shoulders and hips together to lower the barbell toward one hip.', 'Drive through your feet and rotate across your body to sweep the barbell in an arc toward the opposite side.', 'Control the barbell as it changes direction, and continue rotating side to side with your chest facing the barbell.', 'Keep the movement smooth and balanced on both sides until the set is complete.']::text[], 'Inhale as the barbell moves to one side, and exhale as you rotate it across to the other side.', ARRAY['Twisting only the arms while the torso stays still', 'Letting the lower back arch as the bar moves', 'Locking the knees and staying flat-footed', 'Jerking the bar instead of controlling the arc']::text[], 'intermediate'::difficulty_level, 'abdominals', ARRAY['obliques', 'quadriceps']::text[], ARRAY['barbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/landmine-180.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/landmine-180.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
