INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('leg-raise-crunch-0600', 'Leg Raise Crunch', 'An ab exercise combining a crunch with a leg raise to emphasize upper and lower abdominals.', 'Lie on your back with your arms at your sides and legs extended. Raise your legs and torso together, crunching your upper body forward as you lift your legs off the floor, then slowly return to starting position.', ARRAY['Lie on your back and extend your legs.', 'Place your hands by your sides or behind your head.', 'Simultaneously lift your legs and upper torso toward each other.', 'Squeeze at the top of the movement.', 'Lower your legs and upper body back down under control.']::text[], 'Exhale during the crunch, inhale as you return.', ARRAY['Arching the lower back', 'Using momentum', 'Neck strain from pulling']::text[], 'beginner'::difficulty_level, 'rectus_abdominis', ARRAY['hip_flexors', 'obliques']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/crunch-leg-raise.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/crunch-leg-raise.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
