INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('leg-raise-with-hip-lift-drv-leg-raise-hip-lift', 'Leg Raise with Hip Lift', 'A core exercise combining a leg raise with a hip lift to target the lower abdominals.', 'Lie on your back with your arms by your sides. Raise your legs until they are perpendicular to the floor, then lift your hips off the ground by contracting your lower abs. Lower back slowly with control.', ARRAY['Lie flat with arms at your sides and legs straight.', 'Raise your legs up together towards the ceiling.', 'At the top of the movement, press your legs up by lifting your hips off the ground.', 'Pause, squeezing your abs.', 'Lower your hips and legs back to the starting position slowly.']::text[], 'Exhale during hip lift, inhale during the descent.', ARRAY['Using momentum', 'Arching lower back', 'Not controlling the descent']::text[], 'intermediate'::difficulty_level, 'rectus_abdominis', ARRAY['hip_flexors', 'lower_back']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/leg-raise-hip-lift.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/leg-raise-hip-lift.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('lever-back-extension-0573', 'Lever Back Extension', 'A machine-based trunk extension that trains the lower back, glutes, and hamstrings by moving your torso against resistance.', 'Adjust the machine to fit your body size and range of motion. Sit on the machine with your back against the pad and your feet secured. Place your hands on the handles or grip bars. Engage your core and slowly lean forward, allowing your back to round slightly. Pause for a moment at the bottom position, feeling a stretch in your lower back. Using your back muscles, slowly raise your torso back to the starting position. Repeat for the desired number of repetitions.', ARRAY['Adjust the machine so the back pad sits comfortably against your upper back and your feet are secured on the platform.', 'Sit tall against the pad and grip the handles or side bars.', 'Brace your core and lean your torso forward under control through the machine''s range.', 'Stop at the bottom when you feel a comfortable stretch and keep your feet pressed into the platform.', 'Drive your torso back against the pad until you return to an upright position.', 'Repeat smoothly without bouncing or jerking the pad.']::text[], 'Inhale as you lean forward, then exhale as you extend back to an upright position.', ARRAY['Using momentum and bouncing out of the bottom position', 'Pushing through a short, rushed range of motion', 'Letting the feet lift or shift on the platform', 'Hyperextending far past upright at the top']::text[], 'beginner'::difficulty_level, 'erector_spinae', ARRAY['glutes', 'hamstrings']::text[], ARRAY['machine']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/lever-back-extension.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/lever-back-extension.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
