INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('lever-horizontal-leg-press-2611', 'Lever Horizontal Leg Press', 'A horizontal plate-loaded machine exercise targeting the entire thigh, especially the quadriceps.', 'Sit on the leg press machine with your feet hip-width apart on the platform. Press the platform away by extending your legs, but avoid locking your knees, then lower slowly back to the starting position.', ARRAY['Sit on the leg press and adjust seat as needed.', 'Place feet shoulder-width apart on platform.', 'Push platform away by extending legs.', 'Do not lock knees at the top position.', 'Lower platform under control to start position.']::text[], 'Exhale as you press up, inhale as you lower down.', ARRAY['Letting knees cave in/out', 'Lifting hips off seat', 'Locking out knees', 'Using too much weight']::text[], 'beginner'::difficulty_level, 'quadriceps', ARRAY['glutes', 'hamstrings', 'adductors']::text[], ARRAY['machine']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'quads'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/lever-horizontal-leg-press.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/lever-horizontal-leg-press.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
