INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('lever-incline-hammer-chest-press-1299', 'Lever Incline Hammer Chest Press', 'A machine-based incline chest press emphasizing the upper chest and shoulders.', 'Adjust the seat so the handles are level with your upper chest when seated. Grip the handles firmly and press them up and slightly forward, focusing on squeezing your upper chest. Return to the starting position under control after a brief pause.', ARRAY['Adjust seat height for optimal handle position.', 'Sit and grip handles with elbows bent.', 'Press handles up and forward above chest.', 'Avoid locking elbows completely.', 'Lower handles slowly to starting position.']::text[], 'Exhale as you press up, inhale as you lower down.', ARRAY['Letting elbows flare too wide', 'Locking out elbows', 'Arching back off seat', 'Gripping handles unevenly']::text[], 'beginner'::difficulty_level, 'upper_pectoralis', ARRAY['anterior_deltoid', 'triceps']::text[], ARRAY['machine']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'chest'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/lever-incline-hammer-chest-press.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/lever-incline-hammer-chest-press.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('lever-kneeling-leg-curl-0582', 'Lever Kneeling Leg Curl', 'A machine hamstring exercise done kneeling, curling the lower legs toward the glutes by bending the knees.', 'Adjust the machine to fit your body and select the desired weight. Kneel on the machine facing downwards, with your knees resting on the pad and your feet secured under the footpads. Grasp the handles or the sides of the machine for stability. Keeping your upper body stationary, exhale and curl your legs up towards your glutes by flexing your knees. Pause for a moment at the top of the movement, squeezing your hamstrings. Inhale and slowly lower your legs back to the starting position, fully extending your knees. Repeat for the desired number of repetitions.', ARRAY['Adjust the machine so your knees line up with the machine''s pivot point and your ankles sit securely under the pads.', 'Kneel on the pad facing the machine, brace your torso against the support, and grip the handles.', 'Start with your legs extended behind you and keep your hips still.', 'Curl your heels up toward your glutes by bending your knees against the pads.', 'Pause briefly at the top and squeeze your hamstrings.', 'Lower the pads under control until your legs are straight again.']::text[], 'Exhale as you curl your heels up, and inhale as you lower back to the start.', ARRAY['Lifting the hips off the pad during the curl', 'Swinging the legs to start each rep', 'Stopping short and not straightening the knees at the bottom', 'Letting the ankles slip out of the pads']::text[], 'beginner'::difficulty_level, 'hamstrings', ARRAY['glutes']::text[], ARRAY['machine']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'hamstrings'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/lever-kneeling-leg-curl.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/lever-kneeling-leg-curl.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('lever-lateral-raise-0584', 'Lever Lateral Raise', 'A machine shoulder isolation exercise where you lift your arms out to the sides to target the lateral delts.', 'Adjust the seat height and position yourself on the machine with your back against the pad. Grasp the handles with an overhand grip and keep your arms straight. Exhale and raise your arms out to the sides until they are parallel to the floor. Pause for a moment at the top, then inhale and slowly lower your arms back to the starting position. Repeat for the desired number of repetitions.', ARRAY['Adjust the seat so the machine arms line up with your shoulders when you sit down.', 'Sit with your back against the pad and place your forearms or hands on the machine pads or handles.', 'Start with your arms down at your sides and keep a soft bend in your elbows.', 'Raise the machine arms out to your sides until your upper arms reach shoulder height.', 'Pause briefly at the top without shrugging your shoulders.', 'Lower the arms back down under control to the starting position.']::text[], 'Exhale as you raise the arms out to the sides, and inhale as you lower them back down.', ARRAY['Shrugging the shoulders up toward the ears', 'Swinging or bouncing the weight at the bottom', 'Lifting the arms far above shoulder height', 'Letting the back come off the pad']::text[], 'beginner'::difficulty_level, 'deltoids', ARRAY['traps', 'upper_back']::text[], ARRAY['machine']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/lever-lateral-raise.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/lever-lateral-raise.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('lever-leg-extension-0585', 'Lever Leg Extension', 'A seated machine exercise that strengthens the quadriceps by extending the knees against a padded lever.', 'Adjust the seat height and backrest of the machine to fit your body. Sit on the machine with your back against the backrest and your feet on the footpad. Grasp the handles or sidebars for stability. Extend your legs forward by straightening your knees, lifting the weight. Pause for a moment at the top, then slowly lower the weight back to the starting position. Repeat for the desired number of repetitions.', ARRAY['Adjust the seat and backrest so your knees line up with the machine''s pivot point.', 'Sit back against the pad and place your shins behind the lower roller pad.', 'Grip the handles and start with your knees bent and feet pointed forward.', 'Straighten your knees to lift the pad until your legs are nearly straight.', 'Pause briefly while keeping your thighs pressed into the seat.', 'Lower the pad with control until your knees are bent again.']::text[], 'Exhale as you straighten your knees, and inhale as you lower the pad back down.', ARRAY['Knees sit too far forward or behind the machine pivot.', 'Swinging the weight up with momentum.', 'Locking the knees hard at the top.', 'Lifting the hips or lower back off the seat.']::text[], 'beginner'::difficulty_level, 'quadriceps', ARRAY['hamstrings']::text[], ARRAY['machine']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/lever-leg-extension.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/lever-leg-extension.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('lever-lying-chest-press-0577', 'Lever Lying Chest Press', 'A plate-loaded machine press mimicking the bench press to target the entire chest safely.', 'Lie back on the lever chest press machine, gripping the handles just outside shoulder-width. Press the levers forward and upward by extending your arms fully, focusing on squeezing your chest, then return with control to the starting position.', ARRAY['Lie supine on the machine bench.', 'Grip the handles firmly, elbows bent.', 'Engage chest and press handles forward and up.', 'Fully extend arms without locking out elbows.', 'Slowly return to starting position.']::text[], 'Exhale as you press up, inhale as you lower down.', ARRAY['Letting shoulders roll forward', 'Lifting lower back off bench', 'Using too much weight', 'Allowing wrists to bend']::text[], 'beginner'::difficulty_level, 'pectoralis_major', ARRAY['triceps', 'anterior_deltoid']::text[], ARRAY['machine']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'chest'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/lever-lying-chest-press.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/lever-lying-chest-press.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('lever-lying-leg-curl-0586', 'Lever Lying Leg Curl', 'A machine hamstring exercise done face down by bending the knees to curl a padded lever toward the glutes.', 'Adjust the machine to fit your body and select the desired weight. Lie face down on the machine with your legs straight and your heels against the padded lever. Grasp the handles or the sides of the machine for stability. Keeping your upper body stationary, exhale and curl your legs up as far as possible without lifting your hips off the pad. Hold the contracted position for a brief pause as you squeeze your hamstrings. Inhale and slowly lower the lever back to the starting position. Repeat for the desired number of repetitions.', ARRAY['Adjust the machine so your knees line up with the machine''s pivot and the pad rests against the back of your lower legs above your heels.', 'Lie face down on the bench with your legs straight and grab the handles or bench edges for support.', 'Press your hips into the pad and point your toes forward to set your start position.', 'Curl the pad upward by bending your knees until your heels move toward your glutes.', 'Pause briefly at the top while keeping your hips down and thighs on the pad.', 'Lower the pad back down under control until your legs are straight again.']::text[], 'Exhale as you curl the pad up, and inhale as you lower it back down under control.', ARRAY['Lifting the hips off the pad at the top', 'Using momentum to swing the pad upward', 'Stopping short and not fully lowering the pad', 'Feet turning sharply inward or outward during the curl']::text[], 'beginner'::difficulty_level, 'hamstrings', ARRAY['calves']::text[], ARRAY['machine']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'hamstrings'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/lever-lying-leg-curl.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/lever-lying-leg-curl.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('lever-preacher-curl-0592', 'Lever Preacher Curl', 'A machine biceps curl done with the upper arms braced on a preacher pad to isolate elbow flexion.', 'Adjust the seat height and position yourself on the leverage machine. Place your upper arms on the pad and grip the handles with an underhand grip. Keep your back straight and your elbows positioned on the pad. Exhale and curl your forearms towards your upper arms, contracting your biceps. Pause for a moment at the top of the movement, squeezing your biceps. Inhale and slowly lower the handles back to the starting position. Repeat for the desired number of repetitions.', ARRAY['Adjust the seat so your armpits sit close to the top of the preacher pad.', 'Sit down and place the backs of your upper arms flat on the pad.', 'Grip the machine handles with an underhand grip and straighten your arms to the start.', 'Keep your chest up and curl the handles toward your shoulders by bending your elbows.', 'Squeeze your biceps briefly at the top without lifting your upper arms off the pad.', 'Lower the handles under control until your arms are nearly straight again.']::text[], 'Exhale as you curl the handles up, and inhale as you lower them back down under control.', ARRAY['Upper arms lifting off the pad as the handles rise', 'Using the shoulders or rocking the torso to start the curl', 'Letting the weight drop quickly on the way down', 'Bending the wrists back instead of keeping them straight']::text[], 'beginner'::difficulty_level, 'biceps', ARRAY['forearms']::text[], ARRAY['machine']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'biceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/lever-preacher-curl.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/lever-preacher-curl.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
