INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('lever-reverse-hyperextension-0593', 'Lever Reverse Hyperextension', 'A machine glute and hamstring exercise where you raise your legs behind you while lying face down on a pad.', 'Adjust the leverage machine to fit your body and secure your feet in the foot pads. Lie face down on the machine with your upper body hanging off the edge and your hips resting on the pad. Cross your arms over your chest or place them behind your head. Engage your glutes and hamstrings to lift your legs upward until they are parallel to the ground. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', ARRAY['Adjust the machine so your hips rest on the pad and your legs can hang freely.', 'Lie face down with your torso supported and grip the handles or sides for stability.', 'Place your feet against the foot pads and let your legs hang down under control.', 'Brace your midsection and squeeze your glutes to raise your legs behind you.', 'Lift until your legs are about in line with your torso without arching your lower back.', 'Lower your legs slowly to the start position and repeat.']::text[], 'Inhale as you lower your legs, and exhale as you raise them behind you.', ARRAY['Swinging the legs up with momentum', 'Arching the lower back at the top', 'Letting the hips slide off the pad', 'Bending and straightening the knees during each rep']::text[], 'beginner'::difficulty_level, 'glutes', ARRAY['hamstrings', 'lower_back']::text[], ARRAY['machine']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'glutes'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/lever-reverse-hyperextension.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/lever-reverse-hyperextension.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
