INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('lever-reverse-t-bar-row-1349', 'Lever Reverse T-Bar Row', 'A chest-supported leverage machine row using an overhand grip to train the upper back, biceps, and forearms.', 'Adjust the seat height and footplate position on the leverage machine. Sit on the machine with your chest against the pad and your feet flat on the footplate. Grasp the handles with an overhand grip, slightly wider than shoulder-width apart. Keep your back straight and engage your core. Pull the handles towards your chest, squeezing your shoulder blades together. Pause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position. Repeat for the desired number of repetitions.', ARRAY['Adjust the seat or chest pad so the handles line up around mid-chest when you reach forward.', 'Place your chest firmly against the pad and set your feet flat on the platform.', 'Grab the handles with an overhand grip and straighten your arms without rounding your shoulders.', 'Pull the handles toward your chest by driving your elbows back and out slightly.', 'Squeeze your shoulder blades together at the end of the pull.', 'Lower the handles under control until your arms are straight again.']::text[], 'Exhale as you pull the handles toward your chest, and inhale as you lower them back under control.', ARRAY['Shrugging the shoulders up toward the ears', 'Bouncing the chest off the pad to move the handles', 'Letting the upper back round at the start', 'Yanking the weight and dropping it back fast']::text[], 'beginner'::difficulty_level, 'upper_back', ARRAY['biceps', 'forearms']::text[], ARRAY['machine']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/lever-reverse-t-bar-row.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/lever-reverse-t-bar-row.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
