INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('lever-seated-calf-raise-0594', 'Lever Seated Calf Raise', 'A seated machine calf exercise where you raise and lower your heels to train the soleus through ankle plantarflexion.', 'Adjust the seat height so that your knees are slightly bent and your feet are flat on the footplate. Place your toes on the footplate with your heels hanging off the edge. Grasp the handles or the sides of the seat for stability. Push through the balls of your feet to raise your heels as high as possible. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', ARRAY['Adjust the seat so the thigh pad rests securely on your thighs with your knees bent about 90 degrees.', 'Place the balls of your feet on the footplate with your heels hanging off the edge.', 'Grip the handles or seat and lift your heels to take the weight onto your calves.', 'Press through the balls of your feet to raise your heels as high as you can.', 'Pause briefly at the top while keeping your toes planted.', 'Lower your heels slowly until you feel a stretch in your calves, then repeat.']::text[], 'Inhale as you lower your heels, and exhale as you press up onto the balls of your feet.', ARRAY['Bouncing out of the bottom instead of lowering under control.', 'Letting the knees shift up and down during the rep.', 'Rolling the feet outward or inward on the platform.', 'Using only a short top-half range of motion.']::text[], 'beginner'::difficulty_level, 'calves', ARRAY['soleus', 'ankle_stabilizers']::text[], ARRAY['machine']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/lever-seated-calf-raise.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/lever-seated-calf-raise.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
