INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('lever-seated-crunch-1452', 'Lever Seated Crunch', 'A machine exercise that isolates and strengthens the abdominal muscles through spinal flexion.', 'Sit in the lever crunch machine and grasp the handles or position yourself according to machine design. Contract your abs to flex your spine forward, bringing your chest toward your knees, then return slowly to the starting position.', ARRAY['Adjust seat and select appropriate resistance.', 'Sit back and secure feet and handles as designed.', 'Engage abs and flex spine forward in a crunch motion.', 'Bring chest toward knees while exhaling.', 'Control return to start and repeat.']::text[], 'Exhale as you crunch down, inhale as you return up.', ARRAY['Letting hip flexors dominate', 'Using excessive weight', 'Rushing reps', 'Partial range of motion']::text[], 'beginner'::difficulty_level, 'rectus_abdominis', ARRAY['obliques', 'hip_flexors']::text[], ARRAY['machine']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/lever-seated-crunch-1.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/lever-seated-crunch-1.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
