INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('lever-seated-dip-1451', 'Lever Seated Dip', 'A machine-based dip that targets the triceps, chest, and shoulders in a seated position.', 'Sit on the dip machine with your back against the pad, grip the handles, and position your feet flat on the platform. Press the handles downward by extending your arms, keeping your elbows close to your body, then return to the starting position in a controlled motion.', ARRAY['Adjust the seat and select appropriate weight.', 'Sit down and grip the handles firmly.', 'Press the handles downward by extending your arms fully.', 'Pause briefly at lockout.', 'Return to the start position slowly.']::text[], 'Exhale on pressing down, inhale on returning up.', ARRAY['Allowing elbows to flare out', 'Using excessive weight', 'Swinging or jerking movement']::text[], 'beginner'::difficulty_level, 'triceps', ARRAY['pectoralis_major', 'anterior_deltoid']::text[], ARRAY['machine']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'triceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/lever-seated-dips.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/lever-seated-dips.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
