INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('lever-seated-hip-abduction-0597', 'Lever Seated Hip Abduction', 'A seated machine exercise where you press your legs outward against pads to train the hip abductors and outer glutes.', 'Adjust the seat height so that your knees are at a 90-degree angle. Sit on the machine with your back against the backrest and your feet on the footrests. Place your hands on the side handles for stability. Engage your abductors and slowly push your legs apart, away from the midline of your body. Pause for a moment at the end of the movement, then slowly bring your legs back together to the starting position. Repeat for the desired number of repetitions.', ARRAY['Adjust the seat so your knees bend about 90 degrees and the thigh pads rest against the outside of your legs.', 'Sit tall with your back against the pad, place your feet on the footrests, and grip the handles.', 'Start with your legs together and your knees aligned with the machine''s pivot.', 'Drive your knees outward against the pads until your legs are as wide as your comfortable range allows.', 'Pause briefly with your hips still on the seat.', 'Bring your legs back together slowly until the pads nearly touch, then repeat.']::text[], 'Exhale as you press your knees outward, and inhale as you return to the starting position.', ARRAY['Leaning the torso forward or rocking back to move the weight.', 'Letting the legs snap back together on the return.', 'Lifting the hips off the seat at the widest point.', 'Turning the feet excessively to cheat the movement.']::text[], 'beginner'::difficulty_level, 'abductors', ARRAY['glutes', 'hamstrings']::text[], ARRAY['machine']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'mobility'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/lever-seated-hip-abduction.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/lever-seated-hip-abduction.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('lever-seated-hip-adduction-0598', 'Lever Seated Hip Adduction', 'A seated machine exercise that trains the inner thighs by bringing the legs together against resistance.', 'Adjust the seat height and position yourself on the machine with your back against the backrest. Place your feet on the footrests and grasp the handles for stability. Engage your adductor muscles and slowly bring your legs together, squeezing your inner thighs. Pause for a moment at the peak contraction, then slowly return to the starting position. Repeat for the desired number of repetitions.', ARRAY['Adjust the seat and pads so your knees line up with the machine''s pivot point.', 'Sit tall with your back against the pad, place your legs outside the thigh pads, and grab the handles.', 'Set your feet flat on the footrests and start with your legs comfortably apart.', 'Bring your legs together by pressing inward against the pads.', 'Squeeze your inner thighs briefly when the pads come together.', 'Return the pads outward slowly until you reach the start position without letting the weight slam.']::text[], 'Exhale as you press your legs together, and inhale as you return to the starting position.', ARRAY['Leaning forward or lifting the lower back off the pad.', 'Letting the pads fly open on the way back.', 'Using short, bouncing reps instead of controlled motion.', 'Turning the feet and knees excessively to force the movement.']::text[], 'beginner'::difficulty_level, 'adductors', ARRAY['hamstrings', 'glutes']::text[], ARRAY['machine']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'mobility'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/lever-seated-hip-adduction.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/lever-seated-hip-adduction.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('lever-seated-leg-curl-0599', 'Lever Seated Leg Curl', 'A seated machine hamstring exercise where you bend your knees to pull a padded lever downward.', 'Adjust the machine to fit your body and sit on it with your back against the backrest. Place your lower legs under the padded lever, just above your ankles. Grasp the handles on the sides of the machine for support. Keeping your upper legs stationary, exhale and curl your legs up as far as possible. Hold the contracted position for a brief pause as you squeeze your hamstrings. Inhale and slowly lower the lever back to the starting position. Repeat for the desired number of repetitions.', ARRAY['Adjust the seat and pad so your knees line up with the machine’s pivot point.', 'Sit back against the pad and place your lower legs under the roller just above your ankles.', 'Grip the handles and keep your thighs pressed into the seat.', 'Curl the pad down by bending your knees until your heels move toward the floor.', 'Pause briefly and squeeze your hamstrings at the bottom.', 'Lower the pad back up with control until your knees are nearly straight.']::text[], 'Exhale as you curl the pad down, and inhale as you return it to the starting position.', ARRAY['Lifting the hips off the seat during the curl.', 'Using momentum and swinging the pad through the rep.', 'Letting the knees fully lock out at the top.', 'Setting the pad too high on the calves instead of above the ankles.']::text[], 'beginner'::difficulty_level, 'hamstrings', ARRAY['calves']::text[], ARRAY['machine']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'hamstrings'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/lever-seated-leg-curl.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/lever-seated-leg-curl.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
