INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('lever-seated-reverse-fly-0602', 'Lever Seated Reverse Fly', 'A machine rear-delt exercise where you pull the handles out and back while seated with your chest supported.', 'Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor. Grasp the handles with an overhand grip and keep your arms slightly bent. Exhale and squeeze your shoulder blades together as you pull the handles back and outward, away from your body. Pause for a moment at the peak contraction, then inhale and slowly return to the starting position. Repeat for the desired number of repetitions.', ARRAY['Adjust the seat so the handles are about shoulder height when you sit down.', 'Sit with your chest against the pad, feet flat on the floor, and grasp the handles with an overhand grip.', 'Start with your arms in front of you and keep a soft bend in your elbows.', 'Pull the handles out and back in a wide arc until your upper arms line up with your shoulders.', 'Squeeze your rear shoulders and upper back at the end of the movement.', 'Return the handles slowly to the start without letting the weight slam down.']::text[], 'Exhale as you pull the handles back, and inhale as you return to the starting position.', ARRAY['Shrugging the shoulders up toward the ears', 'Straightening the elbows and turning it into a press', 'Letting the chest come off the pad', 'Swinging the handles back with momentum']::text[], 'beginner'::difficulty_level, 'deltoids', ARRAY['traps', 'rhomboids']::text[], ARRAY['machine']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/lever-seated-reverse-fly.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/lever-seated-reverse-fly.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
