INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('lever-shrug-0604', 'Lever Shrug', 'A machine trap exercise where you lift your shoulders straight up against the handles to train the upper trapezius.', 'Adjust the seat height and position yourself on the leverage machine with your back against the pad. Grasp the handles with an overhand grip and keep your arms straight. Keeping your back straight, lift your shoulders up towards your ears as high as possible. Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position. Repeat for the desired number of repetitions.', ARRAY['Adjust the machine so the handles rest at your sides with your shoulders relaxed.', 'Sit or stand against the pad and grasp the handles with a firm overhand grip.', 'Straighten your arms and set your chest tall with your neck neutral.', 'Lift your shoulders straight up toward your ears without bending your elbows.', 'Pause briefly at the top while keeping your torso still.', 'Lower your shoulders under control until they return to the start.']::text[], 'Inhale at the bottom, exhale as you shrug your shoulders up, then inhale as you lower back down.', ARRAY['Bending the elbows and turning it into a row', 'Rolling the shoulders forward or backward', 'Leaning the torso to move the weight', 'Jutting the chin forward as the shoulders rise']::text[], 'beginner'::difficulty_level, 'traps', ARRAY['shoulders']::text[], ARRAY['machine']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/lever-shrug.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/lever-shrug.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
