INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('lever-standing-calf-raise-0605', 'Lever Standing Calf Raise', 'A machine calf exercise where you raise and lower your heels under shoulder pads to train the calves through ankle movement.', 'Adjust the machine to your height and stand with your feet shoulder-width apart. Place your shoulders under the pads and hold onto the handles for stability. Raise your heels as high as possible by extending your ankles. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', ARRAY['Adjust the shoulder pads so they rest comfortably on your shoulders when you stand on the platform.', 'Place the balls of your feet on the edge of the platform with your heels hanging off and grip the handles.', 'Straighten your legs, brace your torso, and let your heels lower until you feel a stretch in your calves.', 'Press through the balls of your feet to raise your heels as high as you can.', 'Pause briefly at the top while staying balanced under the pads.', 'Lower your heels under control back to the stretched start position.']::text[], 'Inhale as you lower your heels, and exhale as you press up onto the balls of your feet.', ARRAY['Bouncing out of the bottom instead of lowering under control.', 'Bending the knees noticeably during the raise.', 'Rolling the ankles inward or outward as the heels lift.', 'Using a short range and stopping before the heels fully lower.']::text[], 'beginner'::difficulty_level, 'calves', ARRAY['soleus', 'ankle_stabilizers']::text[], ARRAY['machine']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/lever-standing-calf-raise.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/lever-standing-calf-raise.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
