INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('lever-standing-hip-extension-2286', 'Lever Standing Hip Extension', 'A machine-based hip extension to isolate and strengthen the glutes.', 'Position yourself on the standing hip extension machine so one foot is on the lever platform. Brace your core and press the platform straight back using your heel, extending your hip fully. Lower under control and repeat for reps before switching legs.', ARRAY['Adjust the machine to your height.', 'Place one foot on platform, chest against pad.', 'Brace core and grasp handles for balance.', 'Extend hip, pressing lever back with heel.', 'Return to starting position and repeat.']::text[], 'Exhale as you extend hip, inhale as you return.', ARRAY['Excessive lower back arch', 'Using momentum', 'Letting knee lock out', 'Not completing full extension']::text[], 'beginner'::difficulty_level, 'glutes', ARRAY['hamstrings', 'erector_spinae']::text[], ARRAY['machine']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'glutes'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/lever-standing-hip-extension.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/lever-standing-hip-extension.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
