INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('lever-standing-rear-kick-drv-lever-standing-rear-kick', 'Lever Standing Rear Kick', 'A leverage machine exercise that isolates the glutes with a hip extension rear kick motion.', 'Set up at the rear kick lever machine with your working foot on the platform and your chest against the pad. Push the lever backward by extending your hip, squeezing your glutes at the top, then return to the starting position.', ARRAY['Adjust the lever machine pad to chest height and select weight.', 'Place working foot on the platform.', 'Hold handles and brace core.', 'Extend hip by pushing foot backward as far as comfortable.', 'Return slowly to starting position and repeat.']::text[], 'Exhale as you kick back, inhale as you return.', ARRAY['Using lower back to lift', 'Swinging leg with momentum', 'Not controlling the negative']::text[], 'beginner'::difficulty_level, 'glutes', ARRAY['hamstrings', 'erector_spinae']::text[], ARRAY['machine']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'glutes'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/lever-standing-rear-kick.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/lever-standing-rear-kick.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
