INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('lever-t-bar-row-drv-lever-t-bar-row', 'Lever T-Bar Row', 'A machine row movement that maximizes mid-back and lat development through a horizontal pulling pattern.', 'Position yourself on the lever T-bar row machine with chest supported and feet braced. Grip the handles, retract your shoulder blades, and pull the handles toward your torso, squeezing your back muscles. Lower the weight under control with full stretch.', ARRAY['Lie prone on the chest pad of the T-bar row machine and grasp the handles.', 'Brace your upper body and retract your shoulder blades.', 'Pull the handles toward your chest or lower ribs.', 'Pause and squeeze your back at the top.', 'Lower the weight under control to a full stretch.']::text[], 'Exhale as you row up, inhale as you lower down.', ARRAY['Arching lower back', 'Not fully extending arms', 'Bouncing weights', 'Letting shoulders round forward']::text[], 'intermediate'::difficulty_level, 'lats', ARRAY['rhomboids', 'posterior_deltoid', 'traps', 'biceps']::text[], ARRAY['machine']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/lever-t-bar-row.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/lever-t-bar-row.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
