INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('lever-triceps-extension-0607', 'Lever Triceps Extension', 'A seated leverage machine exercise where you bend and straighten the elbows to train the triceps.', 'Adjust the seat height and position yourself on the machine with your back against the pad. Grasp the handles with an overhand grip and fully extend your arms in front of you. Keeping your upper arms stationary, slowly lower the handles towards your forehead by bending your elbows. Pause for a moment at the bottom, then push the handles back up to the starting position by extending your arms. Repeat for the desired number of repetitions.', ARRAY['Adjust the seat so the handles line up with about eye or forehead level when you sit down.', 'Sit with your back against the pad and place your feet flat on the floor.', 'Grip the handles with your palms facing down and straighten your arms in front of you.', 'Keep your upper arms still and bend your elbows to lower the handles toward your forehead.', 'Pause briefly when your elbows are fully bent and the handles are close to your head.', 'Press the handles away by straightening your elbows until your arms are extended again.']::text[], 'Inhale as you bend your elbows to lower the handles, and exhale as you straighten your arms to press them away.', ARRAY['Elbows flare wide out to the sides.', 'Shoulders roll forward and the chest collapses.', 'Handles are dropped quickly toward the head.', 'Upper arms swing back and forth during the rep.']::text[], 'beginner'::difficulty_level, 'triceps', ARRAY['shoulders']::text[], ARRAY['machine']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'triceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/lever-triceps-extension.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/lever-triceps-extension.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('lying-hip-lift-on-stability-ball-drv-lying-hip-lift-on-stability-ball', 'Lying Hip Lift on Stability Ball', 'A hip-thrusting exercise using a stability ball to engage glutes, hamstrings, and core.', 'Lie with your upper back and arms on the floor and your feet on a stability ball. Brace your core, drive through your heels, and lift your hips to form a straight line from shoulders to knees, then lower back down with control.', ARRAY['Lie on your back with arms by your sides and feet on the stability ball.', 'Bend knees at 90 degrees and keep feet hip-width apart.', 'Drive through your heels and squeeze your glutes to lift your hips.', 'Pause at the top, keeping your body in a straight line.', 'Lower your hips back down with control.']::text[], 'Exhale when lifting hips, inhale when lowering hips.', ARRAY['Letting knees collapse', 'Overarching lower back', 'Dropping hips too low']::text[], 'intermediate'::difficulty_level, 'glutes', ARRAY['hamstrings', 'lower_back', 'core']::text[], ARRAY['bench']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'glutes'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/lying-hip-lift-on-stability-ball.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/lying-hip-lift-on-stability-ball.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('lying-leg-raise-0865', 'Lying Leg Raise', 'A bodyweight exercise that targets the lower abdominal muscles by lifting the legs while lying flat.', 'Lie flat on your back with your legs extended and arms at your sides or under your hips for support. Keeping legs straight, raise them toward the ceiling until your hips lift slightly off the floor, then lower them back down without touching the ground.', ARRAY['Lie flat on your back, legs straight.', 'Keep arms at your sides or under hips.', 'Lift legs upward, keeping knees straight.', 'Raise legs until hips come up slightly.', 'Lower legs slowly without touching the floor.']::text[], 'Exhale as you raise legs, inhale as you lower.', ARRAY['Arching lower back', 'Using momentum', 'Touching feet to ground between reps']::text[], 'beginner'::difficulty_level, 'rectus_abdominis', ARRAY['hip_flexors', 'obliques']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/lying-floor-leg-raise.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/lying-floor-leg-raise.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
