INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('lying-quadriceps-stretch-drv-stretching-quadriceps-lying-stretch', 'Lying Quadriceps Stretch', 'A stretch for the quadriceps performed lying on the stomach for maximal knee flexion.', 'Lie face down and grasp one ankle behind you, gently pulling the heel toward your glutes while keeping hips down. Feel a stretch in the front thigh and hold without straining the knee.', ARRAY['Lie on your stomach with legs extended.', 'Bend one knee, bringing heel toward glute.', 'Reach back and grasp ankle with hand.', 'Gently pull heel closer to glute until a stretch is felt.', 'Hold, then switch sides.']::text[], 'Exhale as you pull, inhale to release.', ARRAY['Pulling too hard', 'Letting pelvis lift', 'Knee splaying out']::text[], 'beginner'::difficulty_level, 'quadriceps', ARRAY['hip_flexors']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'quads'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-quadriceps-lying-stretch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-quadriceps-lying-stretch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
