INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('lying-scissor-kick-drv-lying-scissor-kick-female', 'Lying Scissor Kick', 'A core and hip flexor exercise performed while lying flat, alternately raising and lowering legs in a scissor-like motion.', 'Lie on your back with arms at your sides, legs extended. Lift both legs slightly off the ground, then alternately move one leg up and the other down in a controlled, fluttering motion.', ARRAY['Lie on your back with legs extended and arms at your sides.', 'Lift both legs a few inches off the ground, keeping them straight.', 'Alternate raising one leg while lowering the other in a scissor motion.', 'Continue to alternate legs in a controlled manner.', 'Keep your head and shoulders relaxed, core engaged.']::text[], 'Exhale as legs rise, inhale as legs lower.', ARRAY['Arching lower back', 'Moving too fast', 'Letting legs touch ground']::text[], 'beginner'::difficulty_level, 'hip_flexors', ARRAY['rectus_abdominis', 'obliques', 'abdominals']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/lying-scissor-kick-female.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/lying-scissor-kick-female.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
