INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('lying-straight-leg-raise-1002', 'Lying Straight Leg Raise', 'An exercise to isolate the hip flexors and lower abdominals from a supine position.', 'Lie flat on your back with legs extended and arms at your sides. Keeping legs straight and together, lift them to about 90 degrees, then lower under control without letting heels touch the ground.', ARRAY['Lie flat on your back, arms at sides.', 'Extend legs fully, feet together.', 'Lift legs straight up to vertical.', 'Pause briefly at the top.', 'Lower legs down slowly but don’t touch floor.']::text[], 'Exhale as you lift legs, inhale as you lower.', ARRAY['Arching lower back', 'Using momentum', 'Separation of legs']::text[], 'beginner'::difficulty_level, 'hip_flexors', ARRAY['rectus_abdominis', 'abdominals']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/lying-straight-leg-raise.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/lying-straight-leg-raise.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
