INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('medicine-ball-wall-sit-up-0640', 'Medicine Ball Wall Sit-Up', 'A dynamic core exercise involving a sit-up while throwing and catching a medicine ball against a wall.', 'Sit facing a wall with your knees bent, holding a medicine ball at your chest. Perform a sit-up and, at the top, throw the medicine ball against the wall, catch it as it rebounds, then lower back down and repeat.', ARRAY['Sit on the floor facing a wall, knees bent.', 'Hold a medicine ball at your chest.', 'Lie back, then perform a sit-up.', 'At the top, throw the ball against the wall.', 'Catch the rebound and lower back down.']::text[], 'Exhale as you sit up/throw, inhale as you lower down.', ARRAY['Leaning too far back', 'Using arms instead of core', 'Missing the ball']::text[], 'intermediate'::difficulty_level, 'rectus_abdominis', ARRAY['hip_flexors', 'obliques', 'shoulders']::text[], ARRAY['bench']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/medicine-ball-sit-up-wall.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/medicine-ball-sit-up-wall.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('middle-back-stretch-1405', 'Middle Back Stretch', 'A static stretch to lengthen the muscles of the thoracic (middle) back region.', 'Sit or stand with arms extended in front. Clasp your hands and round your upper back, reaching forward to feel a gentle stretch along your middle back. Hold the position without bouncing.', ARRAY['Sit or stand with feet hip-width apart.', 'Extend your arms straight in front and clasp your hands.', 'Round your upper back and push your hands forward.', 'Tuck your chin slightly toward your chest.', 'Hold the stretch for 20–30 seconds and release.']::text[], 'Breathe slowly and evenly throughout the stretch.', ARRAY['Arching the lower back instead of rounding the upper back', 'Holding breath', 'Bouncing during the stretch']::text[], 'beginner'::difficulty_level, 'middle_back', ARRAY['lats', 'rhomboids', 'erector_spinae']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-middle-back-stretch-1.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-middle-back-stretch-1.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
