INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('military-press-0553', 'Military Press', 'A standing barbell press that builds overall shoulder strength and stability.', 'Stand with feet hip-width apart, holding a barbell at shoulder height with an overhand grip. Press the bar overhead by extending your arms fully, keeping your core tight and avoiding excessive lower back arch. Lower the bar to the starting position under control.', ARRAY['Stand with feet hip-width apart and barbell at shoulder height.', 'Grip the bar with hands just outside shoulder-width.', 'Brace your core and squeeze your glutes.', 'Press the barbell overhead to full arm extension.', 'Lower the bar slowly back to shoulders.']::text[], 'Exhale as you press up, inhale as you lower down.', ARRAY['Leaning back excessively', 'Bouncing the bar off shoulders', 'Flaring elbows too wide', 'Not bringing bar below chin']::text[], 'intermediate'::difficulty_level, 'deltoids', ARRAY['triceps', 'traps', 'upper_pectoralis']::text[], ARRAY['barbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'shoulders'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/military-press.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/military-press.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
