INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('neck-side-stretch-1403', 'Neck Side Stretch', 'A gentle static stretch that targets the side muscles of the neck, improving mobility and reducing tension.', 'Sit or stand upright, keeping good posture. Gently tilt your head toward one shoulder until a stretch is felt along the opposite side of the neck, holding for a set duration before switching sides.', ARRAY['Sit or stand with good posture.', 'Slowly tilt your head to one side, ear towards shoulder.', 'Hold the stretch for 15-30 seconds.', 'Return to center.', 'Repeat on the opposite side.']::text[], 'Breathe normally throughout the stretch.', ARRAY['Forcing the stretch', 'Turning the head instead of tilting', 'Using jerky movements']::text[], 'beginner'::difficulty_level, 'sternocleidomastoid', ARRAY['scalenes', 'traps']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-neck-side-stretch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-neck-side-stretch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
