INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('old-school-reverse-extensions-drv-old-school-reverse-extensions', 'Old School Reverse Extensions', 'This bodyweight movement isolates the triceps by extending the elbows while lying face down.', 'Lie face down on the floor or bench with arms bent and hands under shoulders. Extend your arms straight back by pressing your palms into the ground or lifting them off the ground, fully straightening your elbows and contracting your triceps. Lower back down under control.', ARRAY['Lie face down on the floor or bench with elbows bent and hands at your sides.', 'Position elbows by your torso.', 'Straighten your arms fully behind you, contracting your triceps.', 'Pause and squeeze at full extension.', 'Return to the start in a controlled manner.']::text[], 'Exhale as you extend your arms, inhale as you return.', ARRAY['Using body momentum', 'Not achieving full extension', 'Letting elbows flare out']::text[], 'beginner'::difficulty_level, 'triceps', ARRAY['posterior_deltoid', 'lats']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'triceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/old-school-reverse-extensions.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/old-school-reverse-extensions.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
