INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('otis-up-drv-otis-ups', 'Otis-Up', 'A sit-up variation holding a weight at arm’s length overhead to increase abdominal engagement.', 'Lie on your back with knees bent and feet flat, holding a weight plate or dumbbell above your chest with arms extended. Sit up while keeping the weight overhead at arm''s length, then lower back down under control.', ARRAY['Lie on your back with knees bent and feet anchored.', 'Hold a weight with both hands, arms fully extended above your chest.', 'Engage your core and sit up, keeping arms straight and weight overhead.', 'Reach an upright seated position.', 'Lower yourself back down under control with arms extended.']::text[], 'Exhale as you sit up, inhale as you lower down.', ARRAY['Bending arms', 'Dropping weight forward', 'Using momentum to sit up']::text[], 'advanced'::difficulty_level, 'rectus_abdominis', ARRAY['obliques', 'hip_flexors', 'shoulders']::text[], ARRAY['bench']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/otis-ups.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/otis-ups.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
