INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('overhead-chest-stretch-1259', 'Overhead Chest Stretch', 'A static stretch that opens the chest by extending the arms overhead and pulling back.', 'Stand tall with your feet hip-width apart, interlace your fingers and extend your arms overhead. Gently pull your arms back and upward, feeling a stretch in your chest and shoulders.', ARRAY['Stand upright with feet hip-width apart.', 'Interlace fingers and stretch arms straight overhead.', 'Gently pull arms back behind head.', 'Squeeze shoulder blades together.', 'Hold the stretch for 15-30 seconds.']::text[], 'Breathe deeply and steadily throughout the stretch.', ARRAY['Hyperextending lower back', 'Bending elbows', 'Letting shoulders shrug']::text[], 'beginner'::difficulty_level, 'pectoralis_major', ARRAY['anterior_deltoid', 'biceps']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'chest'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-above-head-chest-stretch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-above-head-chest-stretch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
