INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('pec-deck-fly-drv-lever-pec-deck-fly', 'Pec Deck Fly', 'A machine-based isolation exercise focusing on squeezing the chest muscles through a fly motion.', 'Sit on the pec deck machine with forearms against the pads and elbows slightly bent. Bring the arms together by contracting the chest, then slowly return to the starting position while maintaining control.', ARRAY['Adjust seat and sit with back against pad.', 'Place forearms on pads with elbows slightly bent.', 'Bring arms together in a wide arc.', 'Squeeze chest at the end of movement.', 'Return slowly to starting position.']::text[], 'Exhale as you bring arms together, inhale as you open.', ARRAY['Locking elbows', 'Arching lower back', 'Using too much weight']::text[], 'beginner'::difficulty_level, 'pectoralis_major', ARRAY['anterior_deltoid', 'biceps']::text[], ARRAY['machine']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'chest'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/lever-pec-deck-fly.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/lever-pec-deck-fly.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
