INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('peroneals-stretch-1388', 'Peroneals Stretch', 'A static stretch that targets the outside muscles of the lower leg.', 'Sit or stand and cross one leg over the other, gently turning the sole of the foot inwards to feel a stretch along the outside of the lower leg. Hold the stretch, then repeat on the other side.', ARRAY['Sit with one leg crossed over the other.', 'Grasp the foot and gently pull it inward.', 'Turn the sole toward your midline.', 'Hold for 20-30 seconds.', 'Switch sides and repeat.']::text[], 'Breathe normally throughout the stretch.', ARRAY['Stretching too forcefully', 'Not holding long enough', 'Incorrect foot positioning']::text[], 'beginner'::difficulty_level, 'peroneals', ARRAY['gastrocnemius', 'soleus']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-peroneals-stretch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-peroneals-stretch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
