INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('pilates-corkscrew-drv-corkscrew-pilates', 'Pilates Corkscrew', 'A Pilates core exercise where the legs draw a circular motion to challenge abdominal stability.', 'Lie on your back with arms at your sides and legs extended overhead. Lift your hips slightly off the mat, then circle your legs in a controlled motion, using your core to stabilize and reverse the direction after each circle.', ARRAY['Lie on back, arms by side, legs straight up.', 'Engage core, lift hips off mat gently.', 'Circle legs together in a clockwise motion.', 'Lower hips as legs complete the circle.', 'Reverse the circle direction.']::text[], 'Exhale as you circle legs, inhale to prepare.', ARRAY['Arching lower back', 'Swinging legs', 'Holding breath']::text[], 'intermediate'::difficulty_level, 'abdominals', ARRAY['obliques', 'hip_flexors']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'abs'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/corkscrew-pilates.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/corkscrew-pilates.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('pilates-hundred-drv-hundred-pilates', 'Pilates Hundred', 'A classic Pilates exercise involving rhythmic arm pumps and core engagement.', 'Lie on your back with legs extended or in tabletop position. Lift your head, neck, and shoulders off the mat, extend arms, and pulse them up and down in small, quick movements while holding the core contracted for 100 counts.', ARRAY['Lie on back, legs in tabletop or extended.', 'Lift head, neck, shoulders off mat.', 'Extend arms at sides, hovering above floor.', 'Pump arms up and down vigorously.', 'Inhale for 5 pumps, exhale for 5 pumps; repeat to 100.']::text[], 'Inhale for 5 pumps, exhale for 5 pumps, continue cycle.', ARRAY['Neck strain', 'Arching lower back', 'Rapid, shallow breathing']::text[], 'beginner'::difficulty_level, 'abdominals', ARRAY['obliques', 'hip_flexors']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'abs'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/hundred-pilates.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/hundred-pilates.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('plyometric-side-lunge-stretch-drv-stretching-plyo-side-lunge-stretch', 'Plyometric Side Lunge Stretch', 'A dynamic stretch to warm up and mobilize the hips, inner thighs, and legs.', 'Begin standing with feet shoulder-width apart. Step to the side into a deep lunge, keeping the opposite leg straight, and quickly alternate sides in a rhythmic motion.', ARRAY['Stand with feet wider than hip-width apart.', 'Shift your weight to one side, bending the knee and keeping the opposite leg straight.', 'Drop into a deep lunge while maintaining upright posture.', 'Push off the bent leg and return to starting position.', 'Repeat to the opposite side in a dynamic, alternating fashion.']::text[], 'Inhale as you prepare and exhale moving into each lunge.', ARRAY['Letting knee cave inward', 'Lifting heel off the ground', 'Rounding the back']::text[], 'beginner'::difficulty_level, 'adductors', ARRAY['glutes', 'quadriceps', 'hamstrings']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'mobility'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-plyo-side-lunge-stretch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-plyo-side-lunge-stretch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('pull-up-wide-grip-1429', 'Pull-Up (Wide Grip)', 'A pull-up variation performed with a wide, overhand grip to emphasize the upper lats and back.', 'Hang from a pull-up bar with hands wider than shoulders using an overhand grip. Pull yourself up until your chin is over the bar, then lower slowly.', ARRAY['Grip pull-up bar with hands wider than shoulders, palms overhand.', 'Hang with arms fully extended and core tight.', 'Pull chest up to bar, driving elbows down and out.', 'Pause at the top, squeeze back muscles.', 'Lower down slowly to full extension.']::text[], 'Exhale as you pull up, inhale as you lower down.', ARRAY['Partial reps', 'Using momentum', 'Shrugging shoulders']::text[], 'intermediate'::difficulty_level, 'lats', ARRAY['traps', 'rhomboids', 'biceps']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/pull-up-wide-front-grip.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/pull-up-wide-front-grip.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('pull-up-chin-up-drv-chin-ups-pull-ups', 'Pull-Up / Chin-Up', 'A bodyweight pulling exercise that develops lat and upper body strength using a hanging bar.', 'Grab a pull-up bar with either a pronated (overhand, pull-up) or supinated (underhand, chin-up) grip slightly wider or narrower than shoulder width as desired. Start from a dead hang, retract your shoulders, and pull your chin above the bar using your back and arms. Control your descent back to the bottom.', ARRAY['Stand under a pull-up bar and grip it with your chosen grip (overhand for pull-up, underhand for chin-up).', 'Hang at full arm extension with shoulders engaged.', 'Brace your core and pull your chest up toward the bar by driving elbows down.', 'Clear the bar with your chin or chest as you squeeze your lats.', 'Lower yourself under control to the starting hang position.']::text[], 'Exhale as you pull up, inhale as you lower down.', ARRAY['Not going to full hang', 'Using leg kick or swing', 'Chin not over the bar', 'Shrugging shoulders']::text[], 'intermediate'::difficulty_level, 'lats', ARRAY['biceps', 'brachialis', 'rhomboids', 'traps', 'posterior_deltoid']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/chin-ups-pull-ups.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/chin-ups-pull-ups.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('push-up-drv-push-ups', 'Push-Up', 'A bodyweight exercise performed in a prone position, targeting the chest, shoulders, and triceps.', 'Start in a plank position with hands slightly wider than shoulder-width apart. Lower your body by bending elbows until your chest nearly touches the floor, then push back to the starting position while keeping your core engaged.', ARRAY['Begin in a plank with hands under shoulders.', 'Engage core and glutes.', 'Lower chest toward floor, elbows at 45 degrees.', 'Pause briefly when close to ground.', 'Press back up to plank position.']::text[], 'Inhale as you lower, exhale as you push up.', ARRAY['Letting hips sag', 'Flaring elbows too wide', 'Incomplete range of motion']::text[], 'beginner'::difficulty_level, 'pectoralis_major', ARRAY['triceps', 'anterior_deltoid', 'core']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'chest'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/push-ups.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/push-ups.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('rear-decline-bridge-0668', 'Rear Decline Bridge', 'A bodyweight floor bridge that lifts the hips to train the glutes and hamstrings while keeping the shoulders on the ground.', 'Lie on your back with your feet flat on the ground and your knees bent. Place your arms by your sides with your palms facing down. Engage your glutes and hamstrings, and lift your hips off the ground until your body forms a straight line from your knees to your shoulders. Hold this position for a few seconds, then slowly lower your hips back down to the starting position. Repeat for the desired number of repetitions.', ARRAY['Lie on your back with your knees bent and feet flat on the floor, hip-width apart.', 'Place your arms by your sides and press your palms lightly into the floor.', 'Brace your midsection and squeeze your glutes.', 'Drive through your heels and lift your hips until your knees, hips, and shoulders line up.', 'Pause briefly at the top while keeping your ribs down.', 'Lower your hips to the floor with control and reset before the next rep.']::text[], 'Inhale at the bottom, exhale as you lift your hips, and inhale again as you lower with control.', ARRAY['Pushing through the toes so the heels lift', 'Overarching the lower back at the top', 'Letting the knees cave inward', 'Dropping the hips quickly to the floor']::text[], 'beginner'::difficulty_level, 'glutes', ARRAY['hamstrings', 'lower_back']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'glutes'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/rear-decline-bridge.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/rear-decline-bridge.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('rear-deltoid-stretch-0669', 'Rear Deltoid Stretch', 'A stretch that targets the rear shoulder to enhance flexibility and reduce tension.', 'Stand or sit upright, extend one arm across your body at shoulder height and use the opposite hand to pull it closer, feeling a stretch across the back of the shoulder. Hold, then switch sides.', ARRAY['Extend one arm across your chest at shoulder height.', 'Use opposite hand to pull arm towards your body.', 'Hold the stretch for 20-30 seconds.', 'Release and return to start.', 'Repeat on the other side.']::text[], 'Breathe normally throughout the stretch.', ARRAY['Lifting the shoulder', 'Twisting the upper body', 'Forcing the stretch']::text[], 'beginner'::difficulty_level, 'posterior_deltoid', ARRAY['rhomboids', 'traps']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'shoulders'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-rear-deltoid-stretch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-rear-deltoid-stretch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('rear-foot-elevated-hip-flexor-stretch-drv-stretching-hip-flexor-stretch-rear-foot-elevated', 'Rear Foot Elevated Hip Flexor Stretch', 'A deep hip flexor stretch with the rear foot elevated for improved flexibility.', 'Stand facing away from a bench or sturdy platform. Place one foot on the bench behind you and lower into a lunge, feeling a stretch in the hip flexors of the elevated leg. Keep your torso upright and pelvis tucked for maximum benefit.', ARRAY['Stand with your back to a bench; place one foot on the bench.', 'Step the front foot forward and lower into a lunge.', 'Tuck pelvis under, keeping chest tall.', 'Lean gently forward to intensify the stretch.', 'Hold, then switch legs.']::text[], 'Inhale to prepare, exhale as you sink into the stretch.', ARRAY['Overarching lower back', 'Knee traveling past toes', 'Leaning forward']::text[], 'beginner'::difficulty_level, 'hip_flexors', ARRAY['quadriceps']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-hip-flexor-stretch-rear-foot-elevated.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-hip-flexor-stretch-rear-foot-elevated.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
