INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('resistance-band-high-fly-drv-band-high-fly', 'Resistance Band High Fly', 'A chest isolation movement where resistance bands are used to fly arms downward from above shoulder height.', 'Attach bands above head height and hold one handle in each hand. Stand with arms overhead in a wide position, then pull hands down and together in an arc, squeezing the chest. Return slowly to the start.', ARRAY['Anchor resistance band above shoulder height.', 'Grasp handles and step forward for tension.', 'Start with arms raised wide, aligned with shoulders.', 'Pull arms downward and together in a wide arc.', 'Squeeze chest, then return slowly to start.']::text[], 'Exhale as you bring arms together, inhale as you return.', ARRAY['Overextending elbows', 'Letting shoulders shrug', 'Losing tension at top']::text[], 'beginner'::difficulty_level, 'pectoralis_major', ARRAY['anterior_deltoid', 'serratus_anterior', 'biceps']::text[], ARRAY['band']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'chest'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-high-fly.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/band-high-fly.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('reverse-crunch-0872', 'Reverse Crunch', 'A bodyweight abs exercise lifting the hips toward the chest to target the lower abdominals.', 'Lie on your back with your arms by your sides and knees bent at 90 degrees. Engage your core and lift your hips off the floor, bringing your knees toward your chest, then slowly lower back to the starting position without letting your feet touch the floor.', ARRAY['Lie on your back, arms at your sides, knees bent, and feet off the ground.', 'Engage your core and lift your legs, bringing knees toward your chest.', 'Lift hips off the floor in a curling motion.', 'Pause and squeeze your abs at the top.', 'Lower your hips back down slowly, keeping control.']::text[], 'Exhale as you lift hips, inhale as you lower down.', ARRAY['Using momentum to swing legs', 'Not controlling the descent', 'Letting lower back arch off the floor']::text[], 'beginner'::difficulty_level, 'abdominals', ARRAY['obliques', 'hip_flexors']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'abs'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/reverse-crunch-female.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/reverse-crunch-female.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('reverse-dip-stretch-0672', 'Reverse Dip Stretch', 'A stretch targeting the triceps and shoulders by extending the arms behind the body and lowering the torso.', 'Sit on the floor with your legs extended and place your hands behind you with fingers facing forward. Gently press through your palms to lift your chest and feel the stretch across your upper arms and shoulders, holding the position without hyperextending your elbows.', ARRAY['Sit with legs extended and arms behind your hips.', 'Place hands flat on the floor, fingers pointing forward.', 'Press through your palms to lift your chest up.', 'Keep your arms long without locking elbows.', 'Hold for the stretch, then slowly lower and relax.']::text[], 'Breathe deeply and steadily throughout the stretch.', ARRAY['Locking elbows tightly', 'Letting shoulders round forward', 'Overarching lower back']::text[], 'beginner'::difficulty_level, 'triceps', ARRAY['deltoids', 'pectoralis_major']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'triceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-reverse-dip.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-reverse-dip.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('reverse-grip-machine-lat-pulldown-0673', 'Reverse Grip Machine Lat Pulldown', 'A machine pulldown using an underhand grip to train the lats through a vertical pulling motion.', 'Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground. Grasp the handles with an underhand grip, slightly wider than shoulder-width apart. Sit upright with your chest out and shoulders back, maintaining a slight arch in your lower back. Pull the handles down towards your chest, squeezing your shoulder blades together. Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position. Repeat for the desired number of repetitions.', ARRAY['Adjust the seat so your knees fit snugly under the pads and place your feet flat on the floor.', 'Reach up and grab the handles with an underhand grip about shoulder-width apart.', 'Sit tall with your chest up and arms fully extended overhead.', 'Pull the handles down toward your upper chest by driving your elbows down and back.', 'Squeeze your upper back and lats at the bottom without leaning far backward.', 'Slowly let the handles rise until your arms are straight again while keeping control.']::text[], 'Inhale as the handles rise back up, and exhale as you pull them down toward your chest.', ARRAY['Leaning far back and turning it into a row', 'Pulling the handles behind the neck', 'Shrugging the shoulders up toward the ears', 'Letting the weight slam back at the top']::text[], 'beginner'::difficulty_level, 'lats', ARRAY['biceps', 'forearms']::text[], ARRAY['machine']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/reverse-grip-machine-lat-pulldown.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/reverse-grip-machine-lat-pulldown.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
