INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('reverse-grip-pull-up-2327', 'Reverse Grip Pull-Up', 'A vertical bodyweight pulling exercise with palms facing you, emphasizing the lats and biceps.', 'Hang from a pull-up bar with a shoulder-width, underhand (supinated) grip. Pull your chin above the bar by flexing your elbows and squeezing your lats, then lower under control.', ARRAY['Grab the bar with palms facing you (supinated grip), hands shoulder-width apart.', 'Hang with arms fully extended and scapula engaged.', 'Pull your chest up towards the bar, leading with your elbows.', 'Clear your chin above the bar, squeezing at the top.', 'Lower yourself back to the starting position with control.']::text[], 'Exhale pulling up, inhale lowering down.', ARRAY['Not extending arms', 'Using momentum', 'Craning neck over bar']::text[], 'intermediate'::difficulty_level, 'lats', ARRAY['biceps', 'rhomboids', 'forearms']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/reverse-grip-pull-up.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/reverse-grip-pull-up.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('reverse-grip-cable-lat-pulldown-0207', 'Reverse-Grip Cable Lat Pulldown', 'A cable pulldown variation using an underhand (supinated) grip to emphasize the lower lats and biceps.', 'Sit at a lat pulldown station and grasp the bar with a reverse (underhand) grip, hands shoulder-width apart. Pull the bar down to your upper chest, squeezing the shoulder blades together, then slowly return to starting position.', ARRAY['Set the cable bar attachment and sit with knees secured under the pad.', 'Grasp the bar with a reverse (supinated) shoulder-width grip.', 'Lean back slightly, chest up, arms fully extended.', 'Pull the bar down to your upper chest by contracting your lats.', 'Slowly return the bar to the start position with control.']::text[], 'Exhale as you pull down, inhale as you return up.', ARRAY['Using too much momentum', 'Letting shoulders round', 'Leaning too far back']::text[], 'beginner'::difficulty_level, 'lats', ARRAY['biceps', 'teres_major', 'rhomboids', 'traps']::text[], ARRAY['cable']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/cable-bar-lateral-pulldown-reverse-grip.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/cable-bar-lateral-pulldown-reverse-grip.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
