INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('ring-high-row-drv-ring-high-row', 'Ring High Row', 'A suspended horizontal pulling movement using rings set high to target upper back and rear shoulder muscles.', 'Set up rings at an appropriate height and grip handles with palms facing in. Lean back with body rigid, arms extended, and feet forward. Pull your chest up to ring height, squeezing the shoulder blades together, then lower back under control.', ARRAY['Adjust rings to chest height and grip handles with neutral grip.', 'Lean back with feet forward and body straight.', 'Engage core, keep arms extended.', 'Row your chest toward the rings, retracting shoulder blades.', 'Lower body back to start under control.']::text[], 'Exhale as you pull, inhale as you lower.', ARRAY['Sagging hips', 'Shrugging shoulders', 'Elbows flaring excessively', 'Incomplete range']::text[], 'intermediate'::difficulty_level, 'rhomboids', ARRAY['lats', 'biceps', 'posterior_deltoid', 'traps']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/ring-high-row.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/ring-high-row.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
