INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('rotational-push-up-drv-rotate-push-up-female', 'Rotational Push-Up', 'A push-up variation involving a torso rotation to challenge the chest, shoulders, triceps, and core.', 'From a push-up position, lower down as normal. As you press up, rotate your torso and extend one arm toward the ceiling, forming a T with your arms. Return to push-up position and repeat to the other side.', ARRAY['Begin in a standard push-up position.', 'Lower your chest toward the floor.', 'As you press up, rotate your torso and lift one arm toward the ceiling.', 'Hold briefly, keeping hips square.', 'Return to start, repeat on the other side.']::text[], 'Exhale when pushing up and rotating, inhale when lowering.', ARRAY['Letting hips sag', 'Twisting too fast', 'Losing shoulder alignment']::text[], 'intermediate'::difficulty_level, 'pectoralis_major', ARRAY['deltoids', 'triceps', 'obliques', 'serratus_anterior']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'chest'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/rotate-push-up-female.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/rotate-push-up-female.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
