INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('runner-s-stretch-1585', 'Runner''s Stretch', 'A flexibility exercise targeting the hip flexors and hamstrings by stepping one leg forward into a deep lunge.', 'Begin in a lunge position with one foot forward and the other leg extended back, keeping both hands on the floor. Sink your hips low toward the ground while keeping your chest lifted, feeling a stretch in the hip flexor of your rear leg and hamstring of your front leg.', ARRAY['Step one foot forward into a lunge, keeping the rear leg extended.', 'Place both hands on either side of the front foot.', 'Lower your hips gently, keeping back leg straight.', 'Lift your chest for deeper stretch.', 'Hold, then switch legs.']::text[], 'Inhale as you get into position, exhale as you deepen the stretch.', ARRAY['Letting knee go over toes', 'Dropping hips too low', 'Arching the back excessively']::text[], 'beginner'::difficulty_level, 'hip_flexors', ARRAY['hamstrings', 'quadriceps', 'glutes']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-runners-stretch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-runners-stretch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
