INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('running-drv-running', 'Running', 'A repetitive aerobic movement that improves cardiovascular fitness and endurance.', 'Begin at a comfortable pace, maintaining upright posture and relaxed shoulders. Land lightly on your feet and use a natural arm swing for balance, adjusting speed and distance as fitness improves.', ARRAY['Warm up with light walking or dynamic stretches.', 'Begin running at a moderate pace.', 'Maintain a steady breathing rhythm and upright posture.', 'Land lightly with a midfoot or forefoot strike.', 'Cool down with walking and stretching.']::text[], 'Exhale steadily as you push off, inhale as you recover.', ARRAY['Overstriding', 'Hunching shoulders', 'Landing heavily on heels']::text[], 'beginner'::difficulty_level, 'cardiovascular_system', ARRAY['quadriceps', 'hamstrings', 'glutes', 'calves']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/running.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/running.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
