INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('russian-twist-on-stability-ball-arms-straight-0211', 'Russian Twist on Stability Ball (Arms Straight)', 'An advanced core exercise targeting the obliques by rotating the torso while balanced on a stability ball with arms extended.', 'Sit on a stability ball with feet flat on the ground, then walk feet forward to roll down until your upper back is supported. Extend your arms straight in front and rotate your torso side to side, keeping arms aligned and abs engaged throughout.', ARRAY['Sit on a stability ball and walk feet forward until shoulders rest on the ball.', 'Keep knees bent at 90 degrees, hips lifted in a bridge position.', 'Extend arms straight toward the ceiling with hands together.', 'Rotate torso and arms as one unit to the left.', 'Return to center, then rotate to the right, repeating for reps.']::text[], 'Exhale during each rotation, inhale as you return to center.', ARRAY['Letting hips drop', 'Bending arms', 'Rotating too quickly']::text[], 'intermediate'::difficulty_level, 'obliques', ARRAY['rectus_abdominis', 'transverse_abdominis', 'hip_flexors']::text[], ARRAY['bench']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'abs'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/russian-twist-on-stability-ball-arms-straight.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/russian-twist-on-stability-ball-arms-straight.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
