INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('scapula-dips-3012', 'Scapula Dips', 'A bodyweight shoulder-blade dip on straight arms that trains scapular control and shoulder depression in a supported position.', 'Start by standing with your feet shoulder-width apart and your arms extended in front of you. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Lower your body by bending your elbows and retracting your shoulder blades, as if you are trying to squeeze a pencil between them. Pause for a moment at the bottom, then push through your hands to extend your elbows and return to the starting position. Repeat for the desired number of repetitions.', ARRAY['Start in a straight-arm support on parallel bars or dip bars with your elbows locked and shoulders stacked over your hands.', 'Lift your chest and brace your trunk while keeping your legs still under you.', 'Lower your body a few inches by letting your shoulders rise toward your ears without bending your elbows.', 'Press down through your hands to pull your shoulders away from your ears and raise your body back up.', 'Repeat with slow, controlled shoulder movement while keeping your arms straight the whole time.']::text[], 'Inhale as you lower into the shoulder shrug, and exhale as you press down to lift your body back up.', ARRAY['Bending the elbows like a regular dip', 'Swinging the legs or torso to create momentum', 'Shrugging up and never pressing back down', 'Dropping too far and losing shoulder control']::text[], 'intermediate'::difficulty_level, 'traps', ARRAY['rhomboids', 'deltoids']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/scapula-dips.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/scapula-dips.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
