INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('seated-alternating-dumbbell-curl-0285', 'Seated Alternating Dumbbell Curl', 'A seated exercise curling dumbbells alternately to build bicep size and strength.', 'Sit on a bench with back support holding a dumbbell in each hand at your sides. Curl one dumbbell by flexing the elbow, then lower it and repeat with the opposite arm, keeping your torso stable.', ARRAY['Sit with back against support and feet flat.', 'Hold dumbbells at your sides, palms facing in.', 'Curl one dumbbell while rotating palm up.', 'Lower to starting position and alternate arms.', 'Repeat, keeping back straight and elbows close to sides.']::text[], 'Exhale as you curl up, inhale as you lower down.', ARRAY['Using momentum', 'Elbows flaring', 'Rocking the torso', 'Moving both arms together']::text[], 'beginner'::difficulty_level, 'biceps', ARRAY['brachialis', 'forearms']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'biceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-alternate-seated-biceps-curl.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-alternate-seated-biceps-curl.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
