INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('seated-bent-over-back-stretch-drv-stretching-sitting-bent-over-back-stretch', 'Seated Bent Over Back Stretch', 'A static stretch performed while seated, bending forward to lengthen the lower and upper back muscles.', 'Sit on the floor with legs extended or crossed. Hinge at the hips and slowly bend forward, reaching hands toward feet or out in front, keeping the back as relaxed as comfortable. Hold the stretch to gently lengthen the muscles along the spine.', ARRAY['Sit comfortably on the floor, legs extended or crossed.', 'Hinge forward at the hips, keeping back relaxed.', 'Let arms reach forward toward feet or floor.', 'Lower your chest toward your knees, breathing deeply.', 'Hold the stretch and relax into the position.']::text[], 'Inhale before bending, exhale as you fold forward.', ARRAY['Rounding excessively', 'Forcing stretch', 'Holding breath']::text[], 'beginner'::difficulty_level, 'erector_spinae', ARRAY['lats', 'hamstrings', 'traps']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-sitting-bent-over-back-stretch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-sitting-bent-over-back-stretch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('seated-boat-stretch-drv-stretching-boat-stretch', 'Seated Boat Stretch', 'A seated flexibility stretch focusing on the inner thighs and hips.', 'Sit on the floor and bring the soles of your feet together, letting knees fall out to the sides. Hold your feet or ankles and gently pull them in, leaning forward slightly to deepen the stretch through the groin and hips.', ARRAY['Sit on the floor with back straight.', 'Bring soles of feet together and let knees drop out.', 'Hold ankles or feet for support.', 'Gently pull feet closer and lean forward slightly.', 'Hold position without bouncing.']::text[], 'Breathe deeply and regularly while holding the stretch.', ARRAY['Forcing knees down', 'Hunching shoulders', 'Bouncing during stretch']::text[], 'beginner'::difficulty_level, 'adductors', ARRAY['lower_back', 'glutes']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'mobility'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-boat-stretch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-boat-stretch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('seated-cable-row-v-grip-0208', 'Seated Cable Row (V-Grip)', 'A compound cable exercise targeting the mid-back and lats using a V-grip handle.', 'Sit on a cable row station with feet on the platform and grasp the V-grip handle. Keep your back straight and pull the handle towards your torso by retracting your shoulder blades and bending your elbows. Control the return to the starting position.', ARRAY['Sit on the cable row machine and place feet on the foot platform.', 'Grab the V-grip handle with both hands, arms extended.', 'Maintain a straight back and slight knee bend.', 'Pull the handle toward your abdomen, retracting your shoulder blades.', 'Slowly extend arms to return to the starting position.']::text[], 'Exhale as you row back, inhale as you extend forward.', ARRAY['Hunching the back', 'Using momentum', 'Allowing elbows to flare out']::text[], 'beginner'::difficulty_level, 'lats', ARRAY['rhomboids', 'traps', 'biceps', 'posterior_deltoid']::text[], ARRAY['cable']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/cable-straight-back-seated-row-v-grip.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/cable-straight-back-seated-row-v-grip.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
