INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('seated-cable-row-wide-grip-0218', 'Seated Cable Row (Wide-Grip)', 'A cable row variation using a wide grip to target the upper back and rear deltoids.', 'Sit on the cable row machine with feet on the platform and grab the wide grip handle. Pull the bar towards the upper abdomen, retracting the shoulder blades, and return to the starting position with control.', ARRAY['Sit down and place feet against the platform.', 'Grasp the wide grip attachment with both hands.', 'Keep your torso upright, arms fully extended.', 'Pull the handle toward your upper abdomen, squeezing your upper back.', 'Slowly release back to the start position.']::text[], 'Exhale as you pull, inhale as you extend arms.', ARRAY['Leaning back too far', 'Letting elbows drop', 'Rounding the back']::text[], 'beginner'::difficulty_level, 'upper_back', ARRAY['posterior_deltoid', 'biceps', 'teres_major']::text[], ARRAY['cable']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/cable-seated-row-wide-grip.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/cable-seated-row-wide-grip.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
