INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('seated-calf-stretch-1390', 'Seated Calf Stretch', 'A stretch performed while seated, focusing on lengthening the calf muscles.', 'Sit on the floor with your legs extended. Loop a towel or band around the ball of one foot, keeping your knee straight, and gently pull your toes toward you, feeling a stretch in the calf. Hold and repeat on the other side.', ARRAY['Sit with legs extended straight in front.', 'Loop a towel or band around one foot''s ball.', 'Keep knee straight and pull your toes toward you.', 'Hold position, feeling stretch in calf.', 'Repeat on the other leg.']::text[], 'Breathe steadily and deeply throughout the stretch.', ARRAY['Bending the knee', 'Rounding the back', 'Pulling toes too forcefully']::text[], 'beginner'::difficulty_level, 'calves', ARRAY['soleus', 'hamstrings']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-seated-calf-stretch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-seated-calf-stretch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
