INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('seated-dumbbell-shoulder-press-0289', 'Seated Dumbbell Shoulder Press', 'A pressing movement targeting the shoulders, performed seated with dumbbells.', 'Sit upright with back supported and hold dumbbells at shoulder height with palms facing forward. Press the weights up overhead until arms are extended, then lower back down under control.', ARRAY['Sit on a bench with back support and feet flat.', 'Hold dumbbells at shoulder height, elbows bent.', 'Press dumbbells overhead until arms are extended.', 'Pause briefly at the top.', 'Lower dumbbells to starting position.']::text[], 'Exhale as you press up, inhale as you lower down.', ARRAY['Arching back excessively', 'Lowering weights too fast', 'Letting elbows drop too low', 'Pressing weights out in front']::text[], 'beginner'::difficulty_level, 'deltoids', ARRAY['triceps', 'traps', 'upper_pectoralis']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'shoulders'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/dumbbell-bench-seated-press.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/dumbbell-bench-seated-press.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
