INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('seated-lower-back-stretch-0690', 'Seated Lower Back Stretch', 'A gentle forward reaching stretch to relieve tension in the lower back while seated.', 'Sit on the floor or chair with your legs extended or crossed. Reach both arms forward and slowly bend at the hips, lowering your torso and arms toward your feet, feeling the stretch across your lower back. Hold the position, keeping the back relaxed.', ARRAY['Sit with legs extended or crossed.', 'Reach both arms straight in front of you.', 'Slowly bend at your hips to lower your torso forward.', 'Relax your back and shoulders.', 'Hold stretch, then return to upright position.']::text[], 'Inhale deeply before bending, exhale as you reach forward.', ARRAY['Rounding upper back excessively', 'Forcing the stretch', 'Holding breath']::text[], 'beginner'::difficulty_level, 'erector_spinae', ARRAY['glutes', 'hamstrings']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-seated-lower-back-stretch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-seated-lower-back-stretch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
