INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('seated-shoulder-flexor-depressor-retractor-stretch-2203', 'Seated Shoulder Flexor, Depressor, Retractor Stretch', 'A seated stretch focusing on improving flexibility and mobility in the front, lower, and rear shoulder muscles.', 'Sit upright on the floor or a chair with feet flat. Reach one or both arms overhead, then gently pull the shoulders downward and backward to open the chest and lengthen the front and rear deltoids. Maintain a tall posture and breathe deeply.', ARRAY['Sit tall with feet flat.', 'Lift arms overhead, reaching upward.', 'Gently depress the shoulders away from your ears.', 'Retract shoulder blades by pulling them slightly together.', 'Hold for a stretch, breathing evenly.']::text[], 'Inhale to begin, exhale as you stretch deeper.', ARRAY['Shrugging shoulders', 'Hunching forward', 'Holding breath']::text[], 'beginner'::difficulty_level, 'deltoids', ARRAY['traps', 'rhomboids', 'pectoralis_major']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'shoulders'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-seated-shoulder-flexor-depresor-retractor.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-seated-shoulder-flexor-depresor-retractor.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
