INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('seated-straight-arm-twist-1011', 'Seated Straight Arm Twist', 'Seated torso rotation with arms straight to target the obliques and core stability.', 'Sit on the floor with your knees bent and feet elevated or flat. Extend both arms straight out in front of you, clasping your hands together. Rotate your torso to one side, keeping arms straight, then rotate to the other side while engaging your core throughout.', ARRAY['Sit with knees bent, feet either flat or off the ground.', 'Extend arms straight forward, clasping hands.', 'Lean back slightly with a neutral spine.', 'Rotate torso to one side, arms following movement.', 'Return to center and repeat to opposite side.']::text[], 'Exhale as you twist, inhale returning to center.', ARRAY['Using just arms instead of rotating the torso', 'Rounding the spine', 'Moving too quickly or without control']::text[], 'beginner'::difficulty_level, 'obliques', ARRAY['rectus_abdominis', 'transverse_abdominis', 'hip_flexors']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'abs'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/seated-twist-straight-arm.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/seated-twist-straight-arm.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
