INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('seated-twist-on-stability-ball-0849', 'Seated Twist on Stability Ball', 'A rotational core exercise performed while seated on a stability ball to target the obliques.', 'Sit upright on a stability ball, feet flat and hip-width apart. Twist your torso to one side while keeping hips steady, then return to center and repeat on the other side.', ARRAY['Sit on a stability ball with feet flat, core engaged.', 'Hold arms in front or across chest.', 'Rotate your torso to the right, keeping hips stationary.', 'Pause, then twist to the left.', 'Return to center, repeat alternately.']::text[], 'Exhale during the twist, inhale as you return to center.', ARRAY['Slouching', 'Over-rotating hips', 'Forgetting to brace core']::text[], 'beginner'::difficulty_level, 'obliques', ARRAY['rectus_abdominis', 'hip_flexors']::text[], ARRAY['bench']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'abs'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/seated-twist-on-stability-ball.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/seated-twist-on-stability-ball.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
