INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('seated-twist-stretch-straight-arm-drv-stretching-seated-twist-straight-arm', 'Seated Twist Stretch (Straight Arm)', 'A flexibility exercise involving seated trunk rotation to stretch the obliques and lower back.', 'Sit on the floor with your legs extended and back straight. Extend your right arm behind you and twist your torso to the right, keeping your left arm straight across your knee for leverage, hold, and repeat on the other side.', ARRAY['Sit upright with legs extended forward.', 'Cross your left leg over your right if desired for more stretch.', 'Extend your right arm straight behind you for support.', 'Twist your torso toward your right, using the opposite arm for leverage.', 'Hold, then repeat to the other side.']::text[], 'Breathe steadily while holding the stretch.', ARRAY['Slouching the back', 'Over-twisting', 'Holding breath']::text[], 'beginner'::difficulty_level, 'obliques', ARRAY['erector_spinae', 'glutes']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'abs'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-seated-twist-straight-arm.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-seated-twist-straight-arm.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
