INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('seated-wide-angle-pose-sequence-1587', 'Seated Wide Angle Pose Sequence', 'A sequence of stretches performed in a wide-legged seated position to improve hip, hamstring, and lower back flexibility.', 'Sit upright and spread your legs as wide as is comfortable. With a straight back, hinge forward at the hips and walk your hands out in front or toward each leg, deepening the stretch in the inner thighs and lower back. Carefully progress through variations to target various muscle groups.', ARRAY['Sit with legs extended wide apart.', 'Keep knees and toes pointing upward.', 'Sit tall and hinge forward at hips.', 'Walk hands forward, maintaining flat back.', 'Hold stretch or gently move side to side.']::text[], 'Inhale to prepare, exhale as you stretch forward.', ARRAY['Letting knees roll inward', 'Rounding back excessively', 'Pushing too far']::text[], 'beginner'::difficulty_level, 'adductors', ARRAY['hamstrings', 'erector_spinae', 'glutes']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'mobility'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-seated-wide-angle-pose-sequence.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-seated-wide-angle-pose-sequence.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
