INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('shoulder-width-pull-up-0651', 'Shoulder-Width Pull-Up', 'A classic bodyweight exercise targeting the lats and upper back with a shoulder-width overhand grip.', 'Hang from a pull-up bar with hands shoulder-width apart, palms facing away. Initiate movement from the back and pull your chin over the bar, then lower yourself in a controlled manner back to the starting position.', ARRAY['Grip bar shoulder-width, palms away.', 'Hang with arms fully extended.', 'Pull up until chin clears the bar.', 'Pause briefly at the top.', 'Lower down slowly to full extension.']::text[], 'Exhale pulling up, inhale lowering down.', ARRAY['Using momentum', 'Partial reps', 'Shrugging shoulders']::text[], 'intermediate'::difficulty_level, 'lats', ARRAY['biceps', 'rhomboids', 'traps', 'forearms']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/pull-up-shoulder-grip.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/pull-up-shoulder-grip.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
