INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('side-bend-on-stability-ball-0850', 'Side Bend on Stability Ball', 'A lateral flexion movement performed on a stability ball to target the obliques.', 'Lie sideways over a stability ball, feet anchored, and hands behind head. Crunch your torso upward in a side-bending motion, then lower with control.', ARRAY['Position yourself sideways on a stability ball, feet braced.', 'Place top hand behind head, other hand for balance.', 'Lower your torso over the ball for a stretch.', 'Contract your side to lift torso up in a side bend.', 'Lower back down with control, repeat.']::text[], 'Exhale as you crunch up, inhale as you lower.', ARRAY['Using momentum', 'Rotating torso', 'Not stabilizing with lower arm']::text[], 'beginner'::difficulty_level, 'obliques', ARRAY['rectus_abdominis', 'quadratus_lumborum']::text[], ARRAY['bench']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'abs'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/side-bend-on-stability-ball.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/side-bend-on-stability-ball.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
