INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('side-bend-stretch-drv-stretching-slopes-towards-stretch', 'Side Bend Stretch', 'A standing lateral bending stretch focusing on lengthening the obliques and side body muscles.', 'Stand tall with feet hip-width apart or sit upright. Raise one arm overhead and lean to the opposite side, feeling a stretch along your side and back muscles. Hold briefly, then return to start and repeat on the other side.', ARRAY['Stand or sit tall with spine neutral.', 'Raise right arm overhead.', 'Slowly bend torso to the left, keeping hips steady.', 'Hold stretch for time, feeling the pull in your side.', 'Return to start and repeat on the other side.']::text[], 'Exhale as you bend, inhale as you return to upright.', ARRAY['Twisting trunk', 'Tilting forward/backward', 'Dropping shoulder']::text[], 'beginner'::difficulty_level, 'obliques', ARRAY['lats', 'quadratus_lumborum', 'erector_spinae']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'abs'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-slopes-towards-stretch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-slopes-towards-stretch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
