INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('side-plank-0705', 'Side Plank', 'A core-strengthening hold performed on one side, engaging the obliques and stabilizing hip muscles.', 'Lie on one side with your elbow under your shoulder and legs extended. Lift your hips off the ground to form a straight line from head to feet, bracing your abs and holding the position while breathing steadily.', ARRAY['Lie on your side, elbow stacked under shoulder.', 'Stack your feet or place one in front of the other.', 'Raise hips up to create a straight line.', 'Hold body in line, keeping abs and glutes engaged.', 'Lower hips gently to finish; switch sides.']::text[], 'Breathe steadily throughout the hold.', ARRAY['Letting hips drop', 'Shoulder collapsing inward', 'Twisting upper body']::text[], 'beginner'::difficulty_level, 'obliques', ARRAY['gluteus_medius', 'quadratus_lumborum', 'shoulders']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'abs'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/side-bridge-side-plank.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/side-bridge-side-plank.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
