INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('side-wrist-pull-stretch-0721', 'Side Wrist Pull Stretch', 'A standing or seated stretch for the wrist and forearm, involving lateral arm extension and gentle pulling.', 'Stand or sit upright, extend one arm overhead or to the side, and grasp the wrist with your opposite hand. Gently pull the wrist to the side to stretch the forearm and wrist muscles, avoiding excessive force.', ARRAY['Stand or sit tall.', 'Extend one arm overhead or outward.', 'Hold your wrist with the opposite hand.', 'Pull gently toward one side.', 'Hold, then switch sides.']::text[], 'Exhale as you stretch, inhale to reset or switch sides.', ARRAY['Pulling too hard', 'Locking elbow', 'Shrugging shoulder']::text[], 'beginner'::difficulty_level, 'forearms', ARRAY['deltoids', 'lats']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'triceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-side-wrist-pull-stretch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-side-wrist-pull-stretch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
