INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('single-dumbbell-stiff-leg-deadlift-1757', 'Single Dumbbell Stiff-Leg Deadlift', 'A stiff-legged deadlift variation using a single dumbbell to target the hamstrings and lower back.', 'Stand holding a dumbbell with both hands in front of your thighs. With a slight bend at the knees, hinge at the hips to lower the dumbbell until you feel a stretch in your hamstrings and then return to the starting position.', ARRAY['Stand upright holding a dumbbell with both hands at your thighs.', 'Keep a slight bend in your knees and your back flat.', 'Hinge forward at the hips, lowering the dumbbell towards the floor.', 'Pause at the bottom while feeling a stretch in your hamstrings.', 'Return to the upright position by driving hips forward.']::text[], 'Inhale lowering, exhale as you stand back up.', ARRAY['Rounding back', 'Excessive knee bend', 'Bouncing at bottom']::text[], 'beginner'::difficulty_level, 'hamstrings', ARRAY['glutes', 'lower_back', 'erector_spinae']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'hamstrings'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/single-dumbbell-stiff-leg-deadlift.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/single-dumbbell-stiff-leg-deadlift.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
