INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('single-leg-stretch-bent-knee-drv-stretching-single-leg-stretch-bent-knee', 'Single Leg Stretch (Bent Knee)', 'A floor stretch to target hip flexors and hamstrings by pulling one bent leg towards the chest.', 'Lie on your back with both knees bent. Grip one shin and gently pull that knee towards your chest, feeling the stretch in your hip and glutes. Maintain a neutral spine and hold before switching legs.', ARRAY['Lie on your back with both legs bent.', 'Grasp one knee with both hands.', 'Pull the knee toward your chest gently.', 'Hold the stretch, keeping your back flat.', 'Switch sides and repeat.']::text[], 'Exhale as you pull the knee in, inhale as you release.', ARRAY['Overpulling knee', 'Arching lower back', 'Holding breath']::text[], 'beginner'::difficulty_level, 'hip_flexors', ARRAY['quadriceps', 'hamstrings', 'glutes']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-single-leg-stretch-bent-knee.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-single-leg-stretch-bent-knee.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
