INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('single-straight-leg-stretch-drv-stretching-single-straight-leg-stretch', 'Single Straight Leg Stretch', 'A floor stretch focusing on the hamstrings by raising and holding one straight leg toward the body.', 'Lie on your back, legs extended. Lift one leg straight up, keeping it as straight as possible, and hold the calf or thigh to gently pull it closer, feeling a stretch in the hamstrings and calves. Then switch legs.', ARRAY['Lie on your back with both legs straight.', 'Lift one leg up while keeping it straight.', 'Hold the back of your thigh or calf gently.', 'Pull the leg slightly toward your chest.', 'Hold and switch legs.']::text[], 'Exhale as you stretch the leg, inhale as you lower it.', ARRAY['Bending the raised knee', 'Lifting hips off mat', 'Straining neck or back']::text[], 'beginner'::difficulty_level, 'hamstrings', ARRAY['calves', 'glutes', 'lower_back']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'hamstrings'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-single-straight-leg-stretch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-single-straight-leg-stretch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
