INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('sit-up-drv-sit-ups', 'Sit-Up', 'A classic ab exercise involving lifting the torso from the floor to a seated position to build core strength.', 'Lie on your back with knees bent and feet flat on the ground. Place your hands behind your head or across your chest, engage your core, and lift your torso all the way up to your knees, then lower back down with control.', ARRAY['Lie flat on your back with knees bent and feet anchored.', 'Place hands behind your head or across your chest.', 'Engage your core to lift your torso to a seated position.', 'Pause at the top, then slowly lower back to the floor.', 'Repeat for the desired number of repetitions.']::text[], 'Exhale as you rise, inhale as you lower.', ARRAY['Jerking the neck', 'Using momentum', 'Feet lifting off the ground']::text[], 'beginner'::difficulty_level, 'rectus_abdominis', ARRAY['hip_flexors', 'obliques']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/sit-ups.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/sit-ups.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
