INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('sit-up-drv-sit-up', 'Sit-Up', 'A classic abdominal exercise that lifts the torso upward from a lying position.', 'Lie on your back with knees bent and feet flat on the floor. Cross your arms over your chest or place hands behind your head, and use your abdominals to lift your upper body toward your knees, then lower back down with control.', ARRAY['Lie down with knees bent and feet flat.', 'Cross arms over chest or place hands behind head.', 'Engage your core and raise your torso towards your knees.', 'Pause briefly at the top.', 'Slowly lower back to starting position.']::text[], 'Exhale on the ascent, inhale on the descent.', ARRAY['Pulling on neck', 'Arching lower back', 'Using momentum']::text[], 'beginner'::difficulty_level, 'rectus_abdominis', ARRAY['hip_flexors', 'obliques']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/sit-up.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/sit-up.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
