INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('sled-45-degree-calf-press-0738', 'Sled 45 Degree Calf Press', 'A seated calf exercise on a 45-degree sled where you press through the balls of your feet to raise and lower the heels.', 'Adjust the sled machine to a 45-degree angle. Place your feet on the sled platform with your toes pointing forward. Push the sled platform away from you by extending your ankles and calves. Pause for a moment at the top, then slowly lower the sled platform back to the starting position. Repeat for the desired number of repetitions.', ARRAY['Sit in the 45-degree sled machine and place the balls of both feet on the lower edge of the platform with your heels hanging off.', 'Straighten your legs enough to support the sled and keep a small bend in your knees.', 'Let your heels drop down by bending at the ankles until you feel a stretch in your calves.', 'Press through the balls of your feet and raise your heels as high as you can.', 'Pause briefly at the top while keeping your legs steady.', 'Lower your heels under control back to the stretched position and repeat.']::text[], 'Inhale as you lower your heels, and exhale as you press through the balls of your feet to raise them.', ARRAY['Bending and straightening the knees instead of moving only at the ankles', 'Placing the whole foot flat on the platform so the heels cannot drop', 'Bouncing out of the bottom instead of lowering under control', 'Turning the toes excessively in or out during the rep']::text[], 'beginner'::difficulty_level, 'calves', ARRAY['hamstrings']::text[], ARRAY['machine']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/sled-45-degree-calf-press.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/sled-45-degree-calf-press.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
