INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('sled-45-degree-wide-leg-press-0740', 'Sled 45 Degree Wide Leg Press', 'A compound lower body movement targeting the quadriceps with emphasis on glutes and adductors due to a wide foot stance.', 'Sit on a 45-degree leg press machine with feet placed wider than hip-width on the platform. Push the platform up to release the safety handles and slowly lower it toward your chest, then drive through your heels to press the weight back up.', ARRAY['Adjust the seat and load desired weight.', 'Sit with your back and head against the pad, feet flat and wide on the platform.', 'Release the safety handles and grasp the side handles.', 'Bend your knees to lower the platform until your thighs reach 90 degrees or just past.', 'Press through your heels to extend your legs fully, but avoid locking out the knees.']::text[], 'Inhale as you lower the platform, exhale as you press it back up.', ARRAY['Allowing knees to collapse inward', 'Rounding lower back', 'Half reps or short range', 'Locking knees at extension']::text[], 'intermediate'::difficulty_level, 'quadriceps', ARRAY['glutes', 'adductors', 'hamstrings']::text[], ARRAY['machine']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'quads'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/sled-45-degree-leg-wide-press.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/sled-45-degree-leg-wide-press.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('sled-hack-squat-0743', 'Sled Hack Squat', 'A machine squat on an angled sled with your back supported to train the quads, glutes, and legs through a controlled range.', 'Adjust the sled machine to a comfortable position for your height. Stand with your feet shoulder-width apart on the platform, toes slightly pointed outwards. Hold onto the handles or bars for stability. Lower your body by bending your knees and hips, keeping your back straight and chest up. Continue lowering until your thighs are parallel to the ground or slightly below. Pause for a moment, then push through your heels to raise your body back up to the starting position. Repeat for the desired number of repetitions.', ARRAY['Stand on the sled platform with your back against the pad and your shoulders under the pads.', 'Place your feet about shoulder-width apart on the platform with toes turned slightly out, then grip the handles.', 'Unlock the sled and lower yourself by bending your knees and hips until your thighs reach parallel or your deepest controlled position.', 'Keep your full foot planted against the platform as your knees track in line with your toes.', 'Drive through your heels and midfoot to extend your knees and hips and return the sled upward.', 'Stop just short of locking your knees, then continue into the next repetition.']::text[], 'Inhale as you lower the sled, then exhale as you press it back up.', ARRAY['Feet placed too low so the heels lift off the platform', 'Knees collapsing inward during the lowering phase', 'Lower back rounding or hips peeling off the pad', 'Bouncing out of the bottom instead of pausing briefly']::text[], 'beginner'::difficulty_level, 'glutes', ARRAY['quadriceps', 'hamstrings', 'calves']::text[], ARRAY['machine']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'glutes'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/sled-hack-squat.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/sled-hack-squat.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('smith-chair-squat-0750', 'Smith Chair Squat', 'A Smith machine squat variation that targets the quads while training the glutes and hamstrings through a controlled bar path.', 'Adjust the height of the smith machine bar to a comfortable position. Stand with your feet shoulder-width apart, toes slightly turned out. Place the barbell across your upper back, resting it on your traps. Engage your core and keep your chest up as you slowly lower your body by bending your knees and hips. Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go. Pause for a moment, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', ARRAY['Set the Smith bar across your upper back and stand with your feet about shoulder-width apart, slightly in front of the bar path.', 'Unrack the bar and brace your core with your chest up and eyes forward.', 'Bend your knees and hips together to sit straight down under control.', 'Lower until your thighs are about parallel to the floor or slightly below while keeping your heels down.', 'Drive through your midfoot and heels to stand back up until your knees and hips are fully extended.', 'Lock out tall, then repeat for the next rep.']::text[], 'Inhale and brace before you lower, then exhale as you drive back up to standing.', ARRAY['Feet set directly under the bar so the knees travel too far forward.', 'Heels lift off the floor at the bottom.', 'Knees cave inward during the ascent.', 'Lower back rounds as the hips drop.']::text[], 'beginner'::difficulty_level, 'quadriceps', ARRAY['glutes', 'hamstrings', 'calves']::text[], ARRAY['machine']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/smith-chair-squat.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/smith-chair-squat.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('smith-machine-calf-raise-1393', 'Smith Machine Calf Raise', 'A standing calf raise using a Smith machine to isolate and strengthen the calf muscles.', 'Stand upright under the Smith machine bar, with the bar resting across your upper traps and feet shoulder-width apart. Raise your heels to stand on your toes, contract your calves, and slowly lower back to the ground.', ARRAY['Set up the Smith machine bar at shoulder height.', 'Step under the bar, position it across your upper traps, and unrack.', 'Stand upright with feet hip to shoulder-width apart.', 'Rise onto the balls of your feet by extending your ankles.', 'Pause at the top, then lower your heels in a controlled manner.']::text[], 'Exhale as you rise, inhale as you lower.', ARRAY['Bouncing for momentum', 'Partial range of motion', 'Allowing ankles to roll outward/inward']::text[], 'beginner'::difficulty_level, 'calves', ARRAY['soleus']::text[], ARRAY['machine']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/smith-calf-raise.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/smith-calf-raise.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('smith-machine-deadlift-0752', 'Smith Machine Deadlift', 'A guided barbell deadlift performed with a Smith machine to build lower back, glutes, and hamstrings strength.', 'Stand with feet hip-width apart beneath the Smith bar. Hold the bar with an overhand grip, hinge at your hips, bend knees, and keep your back neutral. Extend hips and knees to lift the bar along the rails, then return slowly under control.', ARRAY['Position feet shoulder-width beneath the Smith bar.', 'Grip the bar just outside your knees with both hands.', 'Hinge hips back and lower torso, keeping chest up.', 'Extend hips and knees to lift the bar along the guides.', 'Lower the bar with control to the starting position.']::text[], 'Inhale as you lower the bar, exhale as you lift.', ARRAY['Rounding the lower back', 'Lifting with arms instead of legs', 'Letting the bar drift away from body', 'Jerky movements']::text[], 'beginner'::difficulty_level, 'erector_spinae', ARRAY['glutes', 'hamstrings', 'traps', 'forearms']::text[], ARRAY['machine']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/smith-deadlift-deadlift-1.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/smith-deadlift-deadlift-1.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('smith-machine-leg-press-0748', 'Smith Machine Leg Press', 'A machine-based variation of leg press performed with a Smith machine barbell in a supine or incline position.', 'Lie on the floor or bench under a Smith machine with feet placed on the bar wider than shoulder-width. Unlock the bar and press upwards with your legs, lowering until your knees reach a 90-degree angle before pressing back to the start.', ARRAY['Set the safety stops and load the appropriate weight.', 'Lie under the Smith bar and position feet wider than shoulder-width on the bar.', 'Unrack the bar by rotating your feet upward.', 'Lower the bar slowly toward your torso until legs form roughly a 90-degree angle.', 'Press the bar up by extending your knees and hips.']::text[], 'Inhale as you lower the bar, exhale as you press upward.', ARRAY['Incorrect foot placement', 'Pressing with toes only', 'Shallow movement', 'Letting knees cave inward']::text[], 'intermediate'::difficulty_level, 'quadriceps', ARRAY['glutes', 'hamstrings', 'adductors']::text[], ARRAY['machine']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'quads'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/smith-leg-press.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/smith-leg-press.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
