INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('smith-seated-shoulder-press-0765', 'Smith Seated Shoulder Press', 'A seated overhead press on a Smith machine that trains the delts and triceps with a fixed bar path.', 'Adjust the seat height so that the handles are at shoulder level. Sit on the machine with your back against the pad and your feet flat on the floor. Grasp the handles with an overhand grip and lift them off the supports, extending your arms fully. Lower the handles down to shoulder level, keeping your elbows slightly bent. Press the handles up overhead until your arms are fully extended. Pause for a moment at the top, then slowly lower the handles back down to shoulder level. Repeat for the desired number of repetitions.', ARRAY['Set a bench or seat under the Smith bar so the bar starts around shoulder height when you sit down.', 'Sit tall with your back supported, plant your feet flat, and grip the bar just wider than shoulder width with palms forward.', 'Unrack the bar and hold it above your upper chest with wrists stacked over elbows.', 'Lower the bar in a straight path until it reaches about chin to shoulder level.', 'Press the bar straight up until your arms are extended overhead.', 'Lower the bar with control to the start position and repeat.', 'Finish by locking out the top and rotating the bar to re-rack it on the hooks.']::text[], 'Inhale as you lower the bar to shoulder level, and exhale as you press it overhead.', ARRAY['Lowering the bar behind the head', 'Flaring the elbows straight out to the sides', 'Arching the lower back off the bench', 'Letting the wrists bend back excessively']::text[], 'beginner'::difficulty_level, 'deltoids', ARRAY['triceps', 'upper_back']::text[], ARRAY['machine']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/smith-seated-shoulder-press.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/smith-seated-shoulder-press.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('spell-caster-0777', 'Spell Caster', 'A standing dumbbell core move where you hinge and rotate side to side, reaching the weight toward each foot to train the obliques.', 'Stand with your feet shoulder-width apart and hold a dumbbell in one hand. Bend your knees slightly and hinge forward at the waist, keeping your back straight. Extend your arm with the dumbbell towards the opposite foot, rotating your torso as you do so. Return to the starting position and repeat on the other side. Continue alternating sides for the desired number of repetitions.', ARRAY['Stand tall with your feet about shoulder-width apart, holding one dumbbell with both hands in front of your hips.', 'Soften your knees and hinge slightly at your hips while keeping your chest up and back flat.', 'Rotate your torso and lower the dumbbell toward the outside of one foot.', 'Drive through your hips and return to the center with the dumbbell back in front of your hips.', 'Rotate to the other side and lower the dumbbell toward the outside of the opposite foot.', 'Continue alternating sides with controlled movement.']::text[], 'Inhale as you lower and rotate toward one foot, then exhale as you return to center and switch sides.', ARRAY['Rounding the lower back as the dumbbell lowers', 'Bending mostly through the spine instead of hinging at the hips', 'Letting the knees cave inward during the reach', 'Swinging the dumbbell quickly instead of controlling each side']::text[], 'beginner'::difficulty_level, 'abdominals', ARRAY['obliques', 'lower_back']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/spell-caster.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/spell-caster.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('spine-stretch-1363', 'Spine Stretch', 'A floor stretch focusing on lengthening the spine and improving flexibility in the lower back and hamstrings.', 'Sit with legs extended and feet flexed, arms extended in front of you. Exhale as you reach forward, articulating the spine and stretching through your fingertips. Hold the stretch, then slowly return to start.', ARRAY['Sit on floor with legs extended and feet flexed.', 'Extend arms straight ahead at shoulder height.', 'Inhale, then as you exhale, reach forward, articulating your spine.', 'Stretch forward as far as comfortable, keeping legs straight.', 'Hold and return slowly to start.']::text[], 'Exhale as you stretch forward, inhale as you return to start.', ARRAY['Rounding shoulders excessively', 'Forcing the stretch', 'Bending knees']::text[], 'beginner'::difficulty_level, 'erector_spinae', ARRAY['lats', 'hamstrings']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-spine-stretch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-spine-stretch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
