INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('squat-drv-squat', 'Squat', 'A foundational lower body movement that strengthens the quads, glutes, and hamstrings by bending and straightening the knees and hips.', 'Stand with feet shoulder-width apart and toes slightly turned out. Lower your hips back and down as if sitting into a chair, keeping your chest upright, then drive through your heels to stand back up.', ARRAY['Stand with feet shoulder-width apart and toes slightly outward.', 'Brace core and keep chest up.', 'Initiate movement by pushing hips back and bending knees.', 'Descend until thighs are at least parallel to the floor.', 'Push through heels to return to standing.']::text[], 'Inhale as you lower down, exhale as you stand up.', ARRAY['Letting knees collapse inward', 'Rounding lower back', 'Not reaching parallel depth']::text[], 'beginner'::difficulty_level, 'quadriceps', ARRAY['glutes', 'hamstrings', 'erector_spinae', 'adductors']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'quads'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/squat.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/squat.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('stability-ball-leg-curl-0353', 'Stability Ball Leg Curl', 'A hamstring-focused curl using a stability ball for both resistance and core engagement.', 'Lie on your back with your heels on a stability ball. Lift your hips, then curl the ball toward your glutes by flexing your knees, and extend legs back out while keeping hips elevated.', ARRAY['Lie face up on the floor, arms at your sides, heels on a stability ball.', 'Lift hips to form a straight line from shoulders to heels.', 'Bend knees to roll the ball toward your glutes.', 'Pause and squeeze your hamstrings.', 'Extend your legs to roll the ball back out.']::text[], 'Exhale as you curl in, inhale as you extend out.', ARRAY['Letting hips drop', 'Rapid reps', 'Not extending legs fully']::text[], 'intermediate'::difficulty_level, 'hamstrings', ARRAY['glutes', 'calves', 'erector_spinae']::text[], ARRAY['bench']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'hamstrings'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/leg-curl-on-stability-ball.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/leg-curl-on-stability-ball.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('stability-ball-leg-elevated-crunch-0271', 'Stability Ball Leg Elevated Crunch', 'A crunch variation where the legs rest on a stability ball, increasing core engagement and instability.', 'Lie on your back with legs bent and calves resting on a stability ball, hands behind your head. Engage your core and lift your shoulders toward your knees, keeping your lower back on the floor, then return to the starting position.', ARRAY['Place stability ball in front of you and sit down.', 'Lie back and position your calves and feet on top of the ball with knees bent.', 'Place your hands lightly behind your head or crossed on your chest.', 'Engage your core and curl your upper body toward your knees.', 'Pause briefly at the top, then lower back down without losing control.']::text[], 'Exhale as you crunch up, inhale as you lower down.', ARRAY['Using momentum instead of muscle', 'Straining the neck', 'Letting the ball roll away', 'Arching the lower back']::text[], 'intermediate'::difficulty_level, 'rectus_abdominis', ARRAY['obliques', 'hip_flexors']::text[], ARRAY['bench']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/crunch-legs-on-stability-ball.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/crunch-legs-on-stability-ball.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
