INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('stairs-calf-stretch-drv-stretching-stairs-calf-stretch', 'Stairs Calf Stretch', 'A stretch performed using stairs to lengthen and increase flexibility in the calf muscles.', 'Stand on the edge of a step with your heels hanging off. Slowly lower your heels toward the ground, feeling the stretch in your calves. Hold, then return to starting position or alternate legs.', ARRAY['Stand with the balls of your feet on a step or stair.', 'Support yourself with a railing, wall, or sturdy object.', 'Lower your heels slowly below the step to feel a stretch in your calves.', 'Hold the stretch for 15-30 seconds.', 'Raise heels back up and repeat as desired.']::text[], 'Exhale as you lower into the stretch, inhale as you return.', ARRAY['Letting heels drop too fast', 'Rounding your back', 'Bouncing during stretch']::text[], 'beginner'::difficulty_level, 'calves', ARRAY['achilles_tendon']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-stairs-calf-stretch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-stairs-calf-stretch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('standing-adductor-stretch-drv-stretching-adductor-stretch', 'Standing Adductor Stretch', 'A static stretch targeting the inner thighs by lunging to the side and holding.', 'Stand with feet wide apart and slowly bend one knee while keeping the other leg straight. Lean into the bent knee side, feeling the stretch along your inner thigh. Hold, then switch sides.', ARRAY['Stand wide with feet apart.', 'Shift weight to one leg, bending at the knee.', 'Keep the opposite leg straight and toes forward.', 'Lean gently toward the bent knee for a deep inner thigh stretch.', 'Hold, then switch to the other side.']::text[], 'Breathe deeply and steadily while holding the stretch.', ARRAY['Letting the heel lift', 'Twisting hips', 'Bending forward at the waist']::text[], 'beginner'::difficulty_level, 'adductors', ARRAY['hamstrings', 'glutes']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'mobility'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-adductor-stretch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-adductor-stretch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('standing-back-rotation-stretch-drv-stretching-standing-back-rotation-stretch', 'Standing Back Rotation Stretch', 'A standing twisting stretch targeting the obliques and rotational muscles of the back.', 'Stand with feet shoulder-width apart and arms out in front or at your sides. Slowly rotate your upper body to one side, keeping hips square, to feel a gentle stretch along your back and waist. Hold, return to center, and repeat to the other side.', ARRAY['Stand tall with feet shoulder-width apart.', 'Extend arms at shoulder height or place hands on hips.', 'Rotate torso gently to one side without moving hips.', 'Hold stretch for desired time.', 'Return to center and repeat on other side.']::text[], 'Exhale as you twist, inhale as you return to center.', ARRAY['Over-rotating', 'Letting hips twist', 'Holding breath']::text[], 'beginner'::difficulty_level, 'obliques', ARRAY['erector_spinae', 'lats']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'abs'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-standing-back-rotation-stretch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-standing-back-rotation-stretch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('standing-bench-calf-stretch-drv-stretching-standing-bench-calf-stretch', 'Standing Bench Calf Stretch', 'A static stretch using a bench to lengthen the calf muscles.', 'Stand facing a bench and place your toes up onto the edge with your heel on the ground. Lean forward slightly until you feel a stretch through your calf. Hold for the desired time and repeat with the other leg.', ARRAY['Stand in front of a bench or sturdy surface.', 'Place the ball of one foot onto the edge, keeping heel on the floor.', 'Lean your body forward while keeping your knee straight.', 'Hold the stretch for 15-30 seconds.', 'Switch legs and repeat.']::text[], 'Exhale as you relax into the stretch, inhale as you ease off.', ARRAY['Bending the knee too much', 'Letting the foot roll inward or outward', 'Forcing the stretch']::text[], 'beginner'::difficulty_level, 'calves', ARRAY['soleus']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-standing-bench-calf-stretch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-standing-bench-calf-stretch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('standing-hamstring-stretch-1511', 'Standing Hamstring Stretch', 'A static stretch targeting the hamstring muscles along the back of the upper leg.', 'Stand tall and keep knees slightly bent. Hinge forward at the hips, lowering your torso while reaching towards your toes to feel a gentle stretch in your hamstrings. Hold the stretch without bouncing.', ARRAY['Stand up straight with feet hip-width apart.', 'Keep knees soft, and hinge forward at the hips.', 'Lower your torso toward your legs while reaching for your toes.', 'Stop when you feel a gentle stretch in your hamstrings.', 'Hold for the desired duration, then return to standing.']::text[], 'Exhale as you hinge forward, inhale as you return upright.', ARRAY['Rounding the back', 'Locking out the knees', 'Forcing the stretch']::text[], 'beginner'::difficulty_level, 'hamstrings', ARRAY['glutes', 'calves']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'hamstrings'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-hamstring-stretch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-hamstring-stretch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('standing-hip-flexor-and-abdominal-stretch-drv-stretching-ceiling-look-stretch', 'Standing Hip Flexor and Abdominal Stretch', 'A standing stretch focusing on opening the hips and lengthening the abdominal muscles by reaching overhead and leaning back.', 'Stand tall with feet shoulder-width apart. Raise both arms overhead and gently arch your back, lifting your chest and looking up at the ceiling. Engage your glutes and extend hips forward to feel a stretch through the front of your hips and abdomen.', ARRAY['Stand upright with feet shoulder-width apart.', 'Lift arms overhead, palms facing forward.', 'Arch back gently, lifting chest and looking upward.', 'Shift hips forward slightly to increase hip flexor stretch.', 'Hold and breathe for desired duration.']::text[], 'Inhale before arching; exhale as you hold the stretch.', ARRAY['Overarching lower back', 'Locking knees', 'Failing to engage core']::text[], 'beginner'::difficulty_level, 'hip_flexors', ARRAY['abdominals', 'quadriceps']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-ceiling-look-stretch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-ceiling-look-stretch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('standing-knee-raise-stretch-0484', 'Standing Knee Raise Stretch', 'A stretch that targets the hip flexors and glutes by pulling one knee toward the chest while standing.', 'Stand upright and balance on one foot. Lift one knee up toward your chest, grasping it with both hands and pulling gently until you feel a stretch in the hip and glute. Hold briefly, lower, and repeat on the other leg.', ARRAY['Stand tall with feet together.', 'Lift one knee toward your chest.', 'Grasp your knee with both hands.', 'Pull the knee gently toward your chest, feeling the stretch.', 'Hold, then lower and repeat on the opposite leg.']::text[], 'Exhale as you pull the knee up, inhale as you release.', ARRAY['Rounding shoulders', 'Pulling too forcefully', 'Losing balance']::text[], 'beginner'::difficulty_level, 'hip_flexors', ARRAY['glutes', 'hamstrings', 'quadriceps']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-knee-raise.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-knee-raise.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
