INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('standing-lateral-stretch-0794', 'Standing Lateral Stretch', 'A standing side-bending stretch to target the obliques and lengthen the muscles along the side of the torso.', 'Stand tall with feet hip-width apart; raise one arm overhead and gently lean to the opposite side. Feel a stretch along the side of your torso and hold, then switch sides.', ARRAY['Stand upright, feet hip-width apart.', 'Raise one arm overhead, keeping it straight.', 'Place other hand on hip or let it hang at side.', 'Gently lean to the opposite side, keeping hips square.', 'Hold, then return to center and repeat on the other side.']::text[], 'Inhale to lengthen, exhale as you lean into the stretch.', ARRAY['Rotating torso', 'Bending forward or backwards', 'Not keeping arm straight']::text[], 'beginner'::difficulty_level, 'obliques', ARRAY['lats', 'intercostals']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'abs'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-standing-lateral-stretch-1.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-standing-lateral-stretch-1.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
