INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('standing-quadriceps-stretch-drv-stretching-quadriceps-stretch', 'Standing Quadriceps Stretch', 'A standing stretch that targets the quadriceps for improved flexibility.', 'While standing, bend one knee and reach back to grasp your foot or ankle. Pull your heel towards your glutes while keeping your knees close together and torso upright. Use support if needed for balance.', ARRAY['Stand upright, balancing on one foot.', 'Bend the opposite knee, reaching back for the foot.', 'Pull heel gently towards glute while keeping knees together.', 'Keep torso tall and hips level.', 'Hold the stretch, then switch legs.']::text[], 'Exhale as you pull heel in, inhale as you release.', ARRAY['Knees apart', 'Leaning forward', 'Pulling foot too aggressively']::text[], 'beginner'::difficulty_level, 'quadriceps', ARRAY['hip_flexors']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'quads'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-quadriceps-stretch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-quadriceps-stretch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
