INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('standing-reach-up-back-rotation-stretch-drv-stretching-standing-reach-up-back-rotation-stretch', 'Standing Reach Up Back Rotation Stretch', 'A dynamic stretch involving reaching overhead and rotating to open up the chest and upper back.', 'Stand with your feet shoulder-width apart. Reach both arms overhead and gently arch your upper back while rotating your torso to one side, focusing on stretching through your chest and shoulders. Hold for a moment, return to center, and repeat to the other side.', ARRAY['Stand tall with feet shoulder-width apart.', 'Raise both arms overhead.', 'Gently arch your upper back and chest.', 'Rotate your torso to one side while maintaining the stretch.', 'Return to center, then rotate to the other side.']::text[], 'Inhale before reaching up; exhale as you rotate and stretch.', ARRAY['Overarching the lower back', 'Not fully extending arms', 'Twisting too abruptly']::text[], 'beginner'::difficulty_level, 'pectoralis_major', ARRAY['deltoids', 'lats', 'traps']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'chest'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-standing-reach-up-back-rotation-stretch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-standing-reach-up-back-rotation-stretch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('standing-side-bend-stretch-bent-arm-drv-stretching-standing-side-bend-bent-arm', 'Standing Side Bend Stretch (Bent Arm)', 'A side bending stretch performed while standing to lengthen the obliques and lats.', 'Stand tall with feet hip-width apart, raise one arm overhead and bend it, then lean to the side while keeping the torso in one plane, hold the stretch, and repeat on the other side.', ARRAY['Stand with feet shoulder-width apart.', 'Raise one arm overhead, bending the elbow comfortably.', 'Lean sideways away from the raised arm to stretch the side of your torso.', 'Hold the stretch for 15-30 seconds.', 'Switch sides and repeat.']::text[], 'Breathe deeply throughout the stretch.', ARRAY['Rotating the torso', 'Overextending', 'Holding breath']::text[], 'beginner'::difficulty_level, 'obliques', ARRAY['lats', 'serratus_anterior']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'abs'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-standing-side-bend-bent-arm.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-standing-side-bend-bent-arm.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('standing-wheel-rollout-0796', 'Standing Wheel Rollout', 'An advanced rollout exercise that stretches and strengthens the abdominals, chest, shoulders, and back.', 'Begin standing with an ab wheel on the floor in front of you. Holding the handles, slowly roll the wheel forward as you lower your torso, keeping your arms straight, until your body is almost parallel to the ground. Use your core and lats to pull yourself back up.', ARRAY['Stand with feet shoulder-width apart and hold the ab wheel.', 'Bend forward and place the wheel on the floor in front of your feet.', 'Roll the wheel forward, extending your arms and torso while keeping your core tight.', 'Lower your body until you''re just above the floor, maintaining a straight line from head to heels.', 'Reverse the motion by pulling the wheel back toward your feet, returning to the start.']::text[], 'Inhale as you roll out, exhale as you pull back in.', ARRAY['Letting lower back arch excessively', 'Collapsing hips', 'Bending elbows during rollout']::text[], 'advanced'::difficulty_level, 'abdominals', ARRAY['lats', 'pectoralis_major', 'deltoids']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'abs'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-standing-wheel-rollout.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-standing-wheel-rollout.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('stationary-bike-2138', 'Stationary Bike', 'A cardio exercise performed while seated, pedaling a stationary machine to boost heart rate and endurance.', 'Adjust the seat height and handlebar position for comfort and knee alignment. Pedal continuously at your desired intensity, maintaining good posture throughout the workout.', ARRAY['Set seat and handlebar to appropriate heights.', 'Sit upright and grip the handlebars lightly.', 'Place feet securely on the pedals.', 'Begin pedaling at a comfortable resistance and pace.', 'Continue for your intended duration, maintaining good form.']::text[], 'Breathe evenly and deeply throughout the session.', ARRAY['Slouching forward', 'Bouncing in the seat', 'Pedaling with toes only', 'Setting seat too low/high']::text[], 'beginner'::difficulty_level, 'cardiovascular_system', ARRAY['quadriceps', 'hamstrings', 'glutes', 'calves']::text[], ARRAY['machine']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stationary-bike.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stationary-bike.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('straight-leg-up-crunch-drv-crunch-straight-leg-up', 'Straight-Leg Up Crunch', 'A crunch variant with straight legs held vertically to challenge upper abdominals.', 'Lie on your back with legs straight up in the air, arms at your sides or behind your head. Engage your core to lift your head, neck, and shoulders toward your feet, then lower back down with control.', ARRAY['Lie on back, legs straight up, feet flexed.', 'Place arms beside you or hands behind head.', 'Engage core, lift head and shoulders toward legs.', 'Pause at top, exhale.', 'Lower down with control.']::text[], 'Exhale as you crunch up, inhale as you lower down.', ARRAY['Jerking up', 'Using momentum', 'Flaring elbows']::text[], 'beginner'::difficulty_level, 'rectus_abdominis', ARRAY['obliques', 'hip_flexors']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/crunch-straight-leg-up.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/crunch-straight-leg-up.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
