INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('supine-dumbbell-biceps-curl-0350', 'Supine Dumbbell Biceps Curl', 'A biceps isolation curl performed lying face up for strict form and minimal cheating.', 'Lie supine (face up) on a flat bench with a dumbbell in each hand, arms extended. Keeping your upper arms still, curl the weights towards your shoulders, then lower under control.', ARRAY['Lie flat on your back holding dumbbells at your sides, arms fully extended.', 'Keep palms facing forward (supinated grip).', 'Curl the dumbbells up toward your shoulders, elbows stationary.', 'Squeeze your biceps at the top.', 'Lower the weights slowly to the start position.']::text[], 'Exhale as you curl up, inhale as you lower down.', ARRAY['Lifting shoulders off bench', 'Swinging arms', 'Partial range']::text[], 'beginner'::difficulty_level, 'biceps', ARRAY['brachialis', 'forearms']::text[], ARRAY['dumbbell']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'biceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/lying-supine-dumbbell-curl.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/lying-supine-dumbbell-curl.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('treadmill-running-drv-treadmill-running', 'Treadmill Running', 'A popular form of indoor cardiovascular exercise performed at varying intensities on a treadmill machine.', 'Set your desired speed and incline on the treadmill. Start jogging or running, ensuring good posture with a natural stride. Adjust settings as needed for intensity and duration.', ARRAY['Step onto the treadmill and position feet on the sides.', 'Select preferred speed and incline.', 'Begin running, holding onto the handrails if necessary for balance.', 'Focus on smooth strides and upright posture.', 'Cool down by gradually reducing speed before stopping.']::text[], 'Inhale through nose, exhale through mouth in rhythm with strides.', ARRAY['Holding handrails too long', 'Slouching', 'Overstriding', 'Staring down']::text[], 'beginner'::difficulty_level, 'cardiovascular_system', ARRAY['quadriceps', 'hamstrings', 'calves', 'glutes']::text[], ARRAY['machine']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/treadmill-running.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/treadmill-running.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('triceps-dips-drv-triceps-dips', 'Triceps Dips', 'A bodyweight exercise that targets the triceps through a pressing motion while lowering and raising the body.', 'Sit on the edge of a bench or chair with hands next to your hips and legs extended forward. Slide your hips off the seat and lower your body by bending your elbows to about 90 degrees, then push yourself back up by straightening your arms.', ARRAY['Sit on a bench or chair with hands gripping the edge.', 'Extend legs forward and slide hips off the seat.', 'Lower body by bending elbows to 90 degrees.', 'Press through palms to straighten arms and lift body.', 'Repeat for reps.']::text[], 'Inhale as you lower down, exhale as you push up.', ARRAY['Letting shoulders roll forward', 'Dropping hips too low', 'Elbows flaring out']::text[], 'beginner'::difficulty_level, 'triceps', ARRAY['anterior_deltoid', 'pectoralis_major']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'triceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/triceps-dips.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/triceps-dips.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
