INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('twisting-crunch-0985', 'Twisting Crunch', 'A crunch variation with a rotation to engage the obliques and upper abdominals.', 'Lie on your back, knees bent, hands behind head. Crunch up while rotating one elbow toward the opposite knee, then return and alternate sides.', ARRAY['Lie on your back with knees bent and feet flat.', 'Place hands lightly behind your head.', 'Crunch up, twisting your torso to bring one shoulder toward the opposite knee.', 'Return to start and repeat to the other side.', 'Alternate sides for each repetition.']::text[], 'Exhale as you crunch and twist, inhale as you return.', ARRAY['Pulling on the head/neck', 'Not rotating enough', 'Lifting lower back']::text[], 'beginner'::difficulty_level, 'obliques', ARRAY['rectus_abdominis', 'hip_flexors']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'abs'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/twisting-crunch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/twisting-crunch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
