INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('v-up-drv-v-up', 'V-Up', 'A dynamic core exercise where both legs and torso are lifted to meet in a ''V'' position, activating the abdominals.', 'Lie flat on your back with arms extended overhead and legs straight. Simultaneously raise your legs and upper body, reaching your hands towards your feet to form a ''V'' shape, then lower back down in control.', ARRAY['Lie on your back with arms extended overhead and legs straight.', 'Engage your core to lift your legs and torso simultaneously.', 'Reach your hands toward your feet at the top, forming a ''V'' shape.', 'Pause briefly, squeezing your abs.', 'Lower down slowly to starting position.']::text[], 'Exhale when lifting up, inhale as you lower down.', ARRAY['Swinging legs', 'Arching lower back', 'Not fully engaging abs']::text[], 'intermediate'::difficulty_level, 'rectus_abdominis', ARRAY['hip_flexors', 'obliques']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/v-up.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/v-up.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
