INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('vertical-leg-raise-on-parallel-bars-0826', 'Vertical Leg Raise (on parallel bars)', 'A bodyweight core exercise on parallel bars where you raise straight legs in front of you under control.', 'Hang from the parallel bars with your arms fully extended and your body straight. Engage your core and lift your legs up in front of you, keeping them straight. Continue lifting until your legs are parallel to the ground or slightly higher. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', ARRAY['Support yourself on the parallel bars with straight arms and your legs hanging together.', 'Pull your shoulders down and brace your midsection to stop your body from swinging.', 'Keep your knees straight and lift your legs forward in front of you.', 'Raise your legs until they reach hip height or slightly higher.', 'Pause briefly at the top without leaning back.', 'Lower your legs with control to the start and reset before the next repetition.']::text[], 'Exhale as you lift your legs, then inhale as you lower them back to the start.', ARRAY['Swinging the torso to start each rep', 'Bending the knees as the legs rise', 'Shrugging the shoulders up toward the ears', 'Dropping the legs quickly on the way down']::text[], 'intermediate'::difficulty_level, 'abdominals', ARRAY['hip_flexors']::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/vertical-leg-raise-on-parallel-bars.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/vertical-leg-raise-on-parallel-bars.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
