INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('walk-wave-machine-drv-walk-wave-machine', 'Walk Wave Machine', 'A low-impact cardio machine utilizing a unique lateral gliding motion to engage lower body muscles and improve endurance.', 'Step onto the wave machine and grip the handles if available. Begin with a slow pace, moving feet in a side-to-side, skating motion. Gradually increase resistance and speed as you feel comfortable.', ARRAY['Step onto the machine and position feet on pedals.', 'Grip handles for stability.', 'Initiate movement by pushing one leg outward while the other follows.', 'Maintain a rhythmic, lateral gliding motion.', 'Continue for the desired time or intensity.']::text[], 'Keep breath steady and controlled throughout.', ARRAY['Leaning forward', 'Letting knees cave in', 'Jerky movements']::text[], 'beginner'::difficulty_level, 'cardiovascular_system', ARRAY['glutes', 'quadriceps', 'hamstrings', 'hip_abductors', 'calves']::text[], ARRAY['machine']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/walk-wave-machine.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/walk-wave-machine.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
