INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('weighted-leg-extension-crunch-0832', 'Weighted Leg Extension Crunch', 'A core exercise combining a crunch with a resisted leg extension to engage the abdominals.', 'Lie on your back holding a weight at your chest, legs lifted and knees bent. Extend your legs out as you crunch upward, then return to the start position.', ARRAY['Lie flat on your back with knees bent, holding a weight across your chest.', 'Lift your legs to tabletop position (knees over hips, 90-degree bend).', 'Simultaneously extend your legs outward and crunch your upper body up.', 'Pause briefly at peak contraction.', 'Return arms and legs to the starting position.']::text[], 'Exhale as you crunch and extend, inhale as you return.', ARRAY['Using momentum', 'Letting lower back arch', 'Holding breath']::text[], 'intermediate'::difficulty_level, 'rectus_abdominis', ARRAY['hip_flexors', 'obliques']::text[], ARRAY['bench']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/weighted-leg-extension-crunch.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/weighted-leg-extension-crunch.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
