INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('weighted-lying-twist-0846', 'Weighted Lying Twist', 'A core rotational movement that targets the obliques using added resistance.', 'Lie flat on your back, arms extended to your sides and holding a weight between your feet or over chest. Rotate your lower body side-to-side while stabilizing your upper body.', ARRAY['Lie on your back with arms outstretched for support.', 'Hold a weight between your feet (or over chest).', 'Lift your legs up to a 90-degree angle.', 'Slowly rotate your legs to one side, keeping shoulders down.', 'Return to center and repeat on the other side.']::text[], 'Exhale as you twist, inhale as you return to center.', ARRAY['Letting shoulders lift', 'Using momentum', 'Dropping legs too low']::text[], 'intermediate'::difficulty_level, 'obliques', ARRAY['rectus_abdominis', 'hip_flexors']::text[], ARRAY['bench']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'abs'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/weighted-lying-twist.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/weighted-lying-twist.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
