INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('weighted-sissy-squat-0851', 'Weighted Sissy Squat', 'A quad-focused squat variation done on the balls of the feet with a backward torso lean while holding added weight.', 'Stand with your feet shoulder-width apart and your toes pointing slightly outward. Hold a weight in front of your chest with both hands, or place a barbell across your upper back. Keeping your chest up and your core engaged, slowly lower your body down by bending at the knees and hips. Continue lowering until your thighs are parallel to the ground or as low as you can comfortably go. Pause for a moment at the bottom, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', ARRAY['Stand tall with your feet about hip-width apart and hold the weight securely in front of your chest or across your upper back.', 'Rise onto the balls of your feet and brace your midsection.', 'Lean your torso back in one straight line from knees to shoulders as your knees travel forward.', 'Lower under control by bending your knees until you feel a strong stretch through the front of your thighs.', 'Drive through the balls of your feet and straighten your knees to return to the start.', 'Finish tall and reset your balance before the next repetition.']::text[], 'Inhale as you lower under control, then exhale as you drive back up to the starting position.', ARRAY['Bending forward at the hips during the descent', 'Dropping the heels and shifting weight backward', 'Letting the knees cave inward', 'Lowering too fast and bouncing out of the bottom']::text[], 'advanced'::difficulty_level, 'quadriceps', ARRAY['glutes', 'hamstrings', 'calves']::text[], ARRAY['bench']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'cardio'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/weighted-sissy-squat.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/weighted-sissy-squat.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('weighted-standing-curl-0853', 'Weighted Standing Curl', 'A standing biceps exercise where you curl weights from your sides up toward your shoulders with palms facing forward.', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward. Keep your elbows close to your torso and exhale as you curl the weights up to shoulder level. Pause for a moment at the top, then inhale as you slowly lower the weights back down to the starting position. Repeat for the desired number of repetitions.', ARRAY['Stand tall with a weight in each hand at your sides and turn your palms forward.', 'Set your feet about hip-width apart and keep your elbows pinned near your ribs.', 'Curl the weights upward by bending your elbows until your hands reach shoulder height.', 'Pause briefly at the top without letting your elbows drift forward.', 'Lower the weights back down with control until your arms are fully straightened at your sides.']::text[], 'Exhale as you curl the weights up, and inhale as you lower them back down under control.', ARRAY['Swinging the torso to lift the weights', 'Letting the elbows drift forward at the top', 'Dropping the weights quickly on the way down', 'Bending the wrists back instead of keeping them neutral']::text[], 'beginner'::difficulty_level, 'biceps', ARRAY['forearms']::text[], ARRAY['bench']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'biceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/weighted-standing-curl.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/weighted-standing-curl.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('wide-grip-cable-lat-pulldown-drv-cable-bar-lateral-pulldown-wide-shoulder-grip', 'Wide Grip Cable Lat Pulldown', 'A cable exercise performed with a wide grip that primarily targets the latissimus dorsi to build back width and upper body strength.', 'Sit at the cable pulldown machine and grip the wide bar with hands wider than shoulder width and palms facing forward. Engage your core, pull your shoulder blades down and back, and pull the bar down to your upper chest while keeping your back straight. Slowly return the bar to the starting position while controlling the resistance.', ARRAY['Adjust the thigh pad and sit at the cable pulldown machine.', 'Grip the wide bar overhead with a pronated (overhand) grip, hands wider than shoulders.', 'Lean back slightly, brace your core, and retract your shoulder blades.', 'Pull the bar down to your upper chest, driving elbows down and out.', 'Pause briefly, then slowly release the bar back to the starting position.']::text[], 'Exhale as you pull the bar down, inhale as you return to start.', ARRAY['Using momentum or body swing', 'Allowing shoulders to shrug up', 'Not fully extending arms', 'Pulling bar behind neck']::text[], 'beginner'::difficulty_level, 'lats', ARRAY['biceps', 'traps', 'rhomboids', 'posterior_deltoid']::text[], ARRAY['cable']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'back'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/cable-bar-lateral-pulldown-wide-shoulder-grip.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/cable-bar-lateral-pulldown-wide-shoulder-grip.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, steps = EXCLUDED.steps, breathing = EXCLUDED.breathing, common_mistakes = EXCLUDED.common_mistakes, difficulty = EXCLUDED.difficulty, primary_muscle = EXCLUDED.primary_muscle, secondary_muscles = EXCLUDED.secondary_muscles, equipment = EXCLUDED.equipment, category_id = EXCLUDED.category_id, video_url = EXCLUDED.video_url, thumbnail_url = EXCLUDED.thumbnail_url, updated_at = now();

INSERT INTO public.exercises (slug, name, description, instructions, steps, breathing, common_mistakes, difficulty, primary_muscle, secondary_muscles, equipment, category_id, video_url, thumbnail_url, source_url, attribution, license, source, is_active)
VALUES ('wrist-circles-1428', 'Wrist Circles', 'A warm-up and mobility exercise to increase wrist flexibility and circulation in the forearms.', 'Extend your arms in front or to your sides. Make fists or keep hands open, then slowly rotate wrists in circular motions, both clockwise and counterclockwise.', ARRAY['Extend arms out in front or to sides.', 'Make fists or keep hands open.', 'Slowly rotate wrists in circular motions.', 'Perform several circles in one direction.', 'Switch direction and repeat.']::text[], 'Breathe evenly throughout the movement.', ARRAY['Moving arms instead of wrists', 'Rushing motions', 'Holding breath']::text[], 'beginner'::difficulty_level, 'forearms', '{}'::text[], ARRAY['bodyweight']::text[], (SELECT id FROM public.exercise_categories WHERE slug = 'triceps'), 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-wrist-circles.mp4', 'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-wrist-circles.jpg', 'https://github.com/harshvishu/free-exercise-db-with-videos/blob/main/data/exercises.json', 'Free Exercise DB with Videos', 'MIT', 'free_exercise_db'::source_type, true)
